/* ÇEVİRİ en · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("en","olay",{
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Albanian soldiers overthrew the governor of Egypt", "c76a0ec2"], "d": ["Albanian troops whose pay (ulufe) had not been paid rose in revolt and forced the governor Hüsrev Pasha to flee from the citadel. In the vacuum created by the French withdrawal, the Mamluk beys, the Albanian corps and the governors appointed by the Sublime Porte entered a three-cornered struggle; Mehmed Ali came to the fore by establishing balances within this triangle. Other settlements lost on the same date: Taif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["The ulama of Cairo proclaimed Mehmed Ali governor", "a16752f2"], "d": ["The tradesmen and ulama of Cairo, overwhelmed by the burden of taxation, rose under the leadership of the naqib al-ashraf Umar Makram, declared that they did not recognize the governor Hurşid Pasha, and seated Mehmed Ali in the office of governor. The choice of a governor by the people is a rarely encountered event in Ottoman history.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["The Sublime Porte accepted the fait accompli: firman of the governorship of Egypt", "b86736a3"], "d": ["The Sublime Porte, lacking the power to uphold its own candidate in Egypt, sent Mehmed Ali a firman of the governorship of Egypt with the rank of vizier. On the map, from this date Egypt passes to the tributary (light-toned) layer: legally Ottoman territory, in practice the domain of the Kavalalı dynasty. Other settlements passing to the tributary layer on the same date: Cairo, Alexandria, Damietta, Asyut, Aswan, Ibrim, Suez, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["British Fraser expedition landed at Alexandria", "4d6c31be"], "d": ["In response to the Ottoman rapprochement with France, Britain sent a landing force to Egypt. Mehmed Ali was at that time in Upper Egypt dealing with the Mamluks; he returned swiftly and organized the defence.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Rout at Reşid (Rosetta) — the British repulsed", "3636004c"], "d": ["The British column that entered the town of Reşid suffered heavy losses in street fighting; in September the forces evacuated Egypt entirely. This victory consolidated Mehmed Ali's standing both in Egypt and in Istanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["The Citadel Incident: liquidation of the Mamluk beys", "84030b97"], "d": ["The Mamluk beys, invited to the ceremonial procession arranged for the Hejaz campaign, were trapped in the narrow passage of the Cairo Citadel and eliminated. Five centuries of Mamluk influence thus came to an end, and Mehmed Ali was left without a rival in Egypt.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Hejaz campaign began — the army marched to Yanbu by sea from Suez and by land along the pilgrimage road", "1c05c159"], "d": ["Recovering the Haramayn, under Saudi-Wahhabi rule since 1803, was Mahmud II's greatest problem of legitimacy; since the power of the Sublime Porte was insufficient, the task was given to the governor of Egypt. Mehmed Ali sent his sixteen-year-old son Tosun at the head of the army.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu taken over — first coastal base of the Hejaz campaign", "179bc78d"], "d": ["Some two thousand Albanian infantry, who set out from Suez in newly built ships, landed near Yanbu in October 1811; the town surrendered after two days of weak resistance. The cavalry under Tosun's command followed the pilgrimage road by land and reached Yanbu only two weeks later by way of Aqaba and al-Wajh. Yanbu became the first base in the Hejaz of the Egyptian army that was to march on Medina and Mecca.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["First rout in the Safra-Jadida defile", "99ef804d"], "d": ["The Egyptian vanguard, ambushed in narrow mountain passes, was scattered. The defeat became the tactical lesson of the campaign: it was understood that marching in the Hejaz was not possible without the support of the Bedouin tribes.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina recovered", "6f6a5d55"], "d": ["After a long siege Medina surrendered. The recovery of the city of the Prophet was celebrated in Istanbul with cannon festivities; as a reward, Mehmed Ali was also given the governorship of Jeddah.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Mecca recovered — the pilgrimage road opened", "3d6d66a0"], "d": ["The Egyptian forces that entered Mecca had the khutba read at the Kaaba once again in the name of the Ottoman sultan. The pilgrim caravans, interrupted for ten years, were able to set out again. On the map the Hejaz returns to Ottoman dominion, but since its administration is in Cairo, it is shown in the tributary tone. The other place passing to tributary administration on the same date: Jeddah.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Recovery of Taif — completion of the Hejaz campaign", "6315fb31"], "d": ["After Medina (December 1812) and Mecca (January 1813), the Egyptian army under Tosun Pasha finally retook Taif from the Wahhabis. The Saudi dominion of ten years came to an end, and all three holy centres of the Hejaz had once again come under Ottoman-Egyptian control.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali himself crossed to the Hejaz", "fda0ea2d"], "d": ["Seeing that the campaign was being conducted slowly, the governor took the administration directly into his own hands; by bargaining with the tribal chiefs he tried to dissolve the Saudi front from within. Egypt's share in the Red Sea trade also grew through this campaign.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Battle of Bisel: the Saudi forces routed", "9c9ab91f"], "d": ["The Saudis, who suffered a heavy defeat in the pitched battle, withdrew to the interior regions. The truce that was made did not prove lasting; two years later operations would be carried into the heart of Najd.", "4a8ae0e2"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ibrahim Pasha set out on the Najd campaign", "d5ed80d1"], "d": ["Ibrahim Pasha, who took over the command upon the death of his brother Tosun, embarked on a heavy march in the desert that lasted two years. The army, advancing well by well and eliminating the tribes one by one, closed in on the Saudi capital.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Diriyah fell — the First Saudi State ended", "aa96206d"], "d": ["After a siege of six months Diriyah surrendered and was destroyed. The emir Abdullah b. Saud was sent to Istanbul and executed. The Ottoman flag reached so deep into the interior of Arabia for the first time; the Najd garrison remained until 1824. Other places joined on the same date: Diriyah (Najd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Sudan campaign began", "b1fc6905"], "d": ["Mehmed Ali's aim was threefold: to recruit soldiers for his army, to reach the gold of Sennar, and to destroy the remnant of the fugitive Mamluks. The force under the command of his son İsmail Pasha descended southward following the Nile.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola taken — the Mamluk remnant dispersed", "ba6bc24b"], "d": ["The army that entered Dongola, on the great bend of the Nile, liquidated the last Mamluk group that had taken refuge there. On the map, from this date Sudan appears in the tributary layer: it is Cairo that conquers it, and it will be Cairo that governs it.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["The Sultanate of Sennar (Funj) surrendered", "3cac7dd2"], "d": ["The Funj dynasty of three centuries surrendered without fighting. The camp established in the same year at the point where the two branches of the Nile meet soon turned into Khartoum, the administrative centre of Sudan. Other places joined on the same date: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan captured", "06440602"], "d": ["The second column, sent to the west, defeated the forces of Darfur at Bara and took Kordofan. Egypt's dominion in Sudan thus extended from the Nile valley to the western steppes.", "e18d449a"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Egyptian forces landed on Crete", "835aee90"], "d": ["When the Greek revolt spread to Crete, the Sublime Porte requested that an Egyptian force be sent to the island. Mehmed Ali's influence on the island began with this intervention and, eight years later, culminated in the granting of the governorship of Crete to him.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Killing of İsmail Pasha at Shendi", "223860c9"], "d": ["The local emir Nimr, enraged by the demands for heavy taxes and soldiers, set fire to the house in which İsmail Pasha was lodged and burned him and his retinue. The punitive expedition turned the region into a lake of blood; the administration of Sudan was thereafter founded on harshness.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II asked Mehmed Ali for help for the Morea", "03594a42"], "d": ["For the Morea revolt, which could not be suppressed in three years by the Janissary army, the sultan applied to the Egyptian army trained in the European manner. In return, the governorship of the Morea and Crete were promised. This request was the first open admission that the empire had come to depend on its own province.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ibrahim Pasha landed at Modon", "9c993dba"], "d": ["The landing force, protected by the Egyptian fleet, set foot on the south-western tip of the Morea. This army, equipped with regular (nizami) infantry and field artillery, quickly gained the upper hand over the rebel bands.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa retaken — the centre of the Morea fell", "8a478c11"], "d": ["With the fall of Tripolitsa, the administrative centre of the revolt, the greater part of the Morea came again under control. On the map the peninsula appears in the tributary tone because it is in the hands of the Egyptian forces.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) fell", "07257f87"], "d": ["The city was taken after a siege of a year. However, the echo that its defence created in the European press raised sympathy for the Greek cause to its peak and prepared the ground for the intervention of the great powers.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Athenian Acropolis taken over", "3b19f946"], "d": ["With the fall of the Acropolis the Greek revolt had almost ended militarily. At precisely this point the matter ceased to be an internal revolt and became a subject of European diplomacy.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Treaty of London: three powers imposed Greek autonomy", "7ce46fd8"], "d": ["Britain, France and Russia decided on joint action to have the Ottomans and the Greeks accept an armistice and the condition of autonomy; it was announced that their fleets would intervene if this was refused. The Sublime Porte rejected the proposal.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Convention of Alexandria: decision of Egypt to withdraw from the Morea", "cc978f37"], "d": ["Mehmed Ali, who had lost his fleet at Navarino, came to terms directly with the British admiral without consulting Istanbul and agreed to withdraw his forces from the Morea. A governor's making an independent agreement with the great powers was a harbinger of the future crisis.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Egyptian forces evacuated the Morea", "8fb742dd"], "d": ["The last units were embarked on ships; the peninsula was lost in practice and, with the London Protocol of 1830, became the nucleus of independent Greece. Mehmed Ali, for his part, had not received the promised governorship of the Morea and had lost a great fleet and army in return. Other settlements lost on the same date: Modon, Coron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Administration of Crete left to Mehmed Ali", "7f76396d"], "d": ["As compensation for the loss of the Morea, the governorship of Crete was given to Mehmed Ali. The island was governed from Cairo for ten years; on the map it appears in the tributary tone throughout this period. Other places joined on the same date: Candia (Crete).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ibrahim Pasha entered Syria — the first crisis began", "1a5cc386"], "d": ["The pretext was the governor of Acre, who would not return the fellahin who had fled from Egypt; the real reason was Mehmed Ali's need for Syria's timber, ports and manpower. The army crossed Sinai and swiftly took the Palestinian coast.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Siege of Acre began", "b211d96d"], "d": ["The fortress that had stopped Napoleon in 1799 resisted for six months. The siege was the first great test of the Egyptian army's modern artillery.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Acre fell", "0f47917b"], "d": ["When the batteries pounding the walls opened a breach, the fortress was taken. The gate of Syria had been opened; in the same days the Sublime Porte declared Mehmed Ali a rebel and abolished his governorship.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damascus surrendered", "48da3b62"], "d": ["The city surrendered without fighting. Ibrahim Pasha tried to win local support by proclaiming a tax order and the equality granted to non-Muslims; the same policies would a few years later be the cause of revolts against him. Other places joined in the same days: Beirut, Tripoli of Syria, Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Battle of Homs", "867810ee"], "d": ["The Ottoman army sent to save Syria was routed in the open field. It was seen that the new army, established six years after the abolition of the Janissaries, was not yet ready.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo captured", "9c0ead76"], "d": ["The commercial and administrative centre of northern Syria also fell. The Egyptian army thus closed in on the foothills of the Taurus and turned toward the passes at the gate of Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Rout at the Belen (Beilan) Pass — Çukurova opened", "4bae872b"], "d": ["The defensive line was broken in the narrow pass in the Amanus mountains. Antioch, Adana and Tarsus passed to the Egyptian forces (the occupation of Maraş, according to TDV, is 1833, a separate item); on the map Çukurova changes to the tributary tone. The road into the interior of Anatolia was now undefended.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Gülek Pass fell — the İçil coast (Mersin, Silifke) came under Egyptian control", "d9049b5b"], "d": ["The Gülek Pass, the Çukurova gate of the Taurus, fell into the hands of the Egyptian army. Ibrahim Pasha appointed his own mütesellim to the Sancak of İçil, and all the landing places on the coast came under Egyptian control. On the map Mersin and Silifke are shown as attached to Egypt from this day (lower bound; the day of the appointment is not in the source); since in the Kütahya decision only the muhassıllık of Adana was transferred, this control ends with the evacuation of Anatolia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğli under Egyptian occupation — the Taurus mouth of the Konya–Adana road", "fb908900"], "d": ["Ereğli, on the road to Konya of the Egyptian army that crossed the Gülek Pass, came under the occupation of Ibrahim Pasha in 1832 and, when it was evacuated with the Kütahya arrangement of 1833, was again attached to the province of Karaman. On the map it is the sourced intermediate point of the occupation line between Adana and Konya; no city-level testimony could be found for Ulukışla and Karapınar.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Egyptian army entered Konya", "13952a2d"], "d": ["The army that crossed the Taurus reached Central Anatolia. The forces of an Ottoman governor were for the first time advancing in the core lands of the empire. Other places joined on the same date: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Battle of Konya: the grand vizier taken prisoner", "ec82cc9a"], "d": ["The Ottoman army, dispersed in foggy weather, suffered a heavy defeat, and the grand vizier Reşid Mehmed Pasha was taken prisoner. The central army of the state no longer existed; there was no force left to stand between Istanbul and the Egyptian forces.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş came under Egyptian occupation", "f558e383"], "d": ["According to TDV, Maraş came under the occupation of Kavalalı Ibrahim Pasha in 1833 and remained under his administration for nearly nineteen months. Since Maraş remained outside the provincial boundaries of the Kütahya arrangement, this administration is de facto, not legal.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) came under Egyptian occupation — the Konya–Kütahya road", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, on the route of the Egyptian army advancing to Kütahya after the Battle of Konya, remained for a time in the hands of Ibrahim Pasha in 1833. On the map it is the sourced intermediate point of the occupation line between Konya and Kütahya; no city-level testimony could be found for Akşehir, Ilgın and İshaklı, and they are in the Ottoman colour.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Egyptian army reached Kütahya", "214f8df6"], "d": ["Ibrahim Pasha halted at Kütahya, three stages from Istanbul. His not advancing further was political, not military: the Russian intervention and the reaction of Europe had been taken into account.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Russian fleet off Büyükdere", "6f836d61"], "d": ["Mahmud II, who could obtain no help from Britain and France, applied to Russia, his enemy of yesterday. This decision, remembered by the sultan's saying \"a drowning man clutches at a serpent\", resulted in Russian troops landing on the Straits and set the alarm bells ringing in Europe.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Convention of Kütahya — Syria and Adana to Kavalalı", "c16c5a94"], "d": ["The Sublime Porte left to Mehmed Ali, in addition to Egypt, Crete and the Hejaz, the governorships of Damascus, Aleppo, Tripoli of Syria and Sidon, and to Ibrahim Pasha the muhassıllık of Adana. In return the army withdrew to the south of the Taurus. This took the form not of a treaty but of firmans given by the sultan to a governor — the problem had not been resolved but postponed.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Withdrawal of the Egyptian army from Anatolia completed through Gülek", "a53ac2a3"], "d": ["After the Kütahya arrangement the Egyptian forces evacuated Anatolia; toward mid-June the whole army crossed through the Gülek Pass into Çukurova. The İçil coast (Mersin, Silifke) returns to Ottoman administration; the muhassıllık of Adana and Syria remain with Egypt.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Treaty of Hünkâr İskelesi", "da741d5c"], "d": ["An eight-year mutual defence alliance was signed with Russia. According to the secret article, the Ottomans would close the Straits to warships if Russia were attacked. This became one of the most controversial decisions of Ottoman diplomacy and made Britain active in the Egyptian question.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Palestine-Nablus revolt against Egyptian rule", "4fe43e27"], "d": ["Conscription, the collection of arms and new taxes led to a broad uprising in Palestine. The revolt was harshly suppressed; the support of the Egyptian administration among the local population melted away rapidly.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["End of the Egyptian administration of Maraş (approximate)", "bb46ca42"], "d": ["When TDV's phrase 'nearly nineteen months' is counted from the occupation of 1833, the Egyptian administration ends around the summer of 1834. That Mustafa Bey of the Küçükalioğulları, unable to resist the Egyptian army in 1834, withdrew toward Maraş also shows that Maraş was at that time a refuge outside Egyptian control.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Jabal al-Druze uprising", "12e74626"], "d": ["The resistance that broke out in the Druze region lasted two years. The discontent that accumulated in Syria would, in 1840, leave the rear of the Egyptian army exposed when the allied fleets landed on the coast.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali declared his intention of independence", "48633bbd"], "d": ["The governor announced to the consuls of the great powers that he was considering proclaiming the independence of Egypt and Syria. Britain opposed this categorically: the emergence of a strong state in the Mediterranean close to France would threaten the road to India.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Ottoman army crossed the Euphrates", "9af1ea69"], "d": ["Mahmud II drove his army to the Syrian frontier to recover what had been lost at Kütahya. The Prussian officer Moltke, who was with the army as adviser, objected to the choice of position and to the early attack; his objections were not heeded.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Battle of Nizip — the Ottoman army dispersed", "156b3cdf"], "d": ["The badly positioned Ottoman army was routed within a few hours. The sultan died before news of the defeat reached Istanbul; within a few days the state was to lose its army, its sovereign and then its fleet.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Death of Mahmud II", "07eccfff"], "d": ["The sultan who, during a reign of thirty-one years, abolished the Janissaries and re-established central administration, died without having defeated his greatest adversary. His illness had not been correctly diagnosed. His death was concealed until 30 June, until military measures were taken in the city for fear that the Janissary mentality would be set in motion.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Accession of Abdülmecid and funeral of Mahmud II", "d0f3d2cc"], "d": ["Upon his father's death, the sixteen-year-old Abdülmecid acceded to the throne. On the same day Mahmud II's funeral cortege was brought to Topkapı Palace; the feared disorder did not occur, and broad masses of Muslims and non-Muslims joined the funeral procession.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Handing over of the fleet to Alexandria", "a53e6103"], "d": ["The grand admiral (kaptan-ı derya) Ahmed Fevzi Pasha, suspecting that the grand vizier Koca Hüsrev Pasha would give the fleet to Russia, took the fleet to Alexandria and handed it over to Mehmed Ali. Within the same month the Ottoman State was left without an army, without a sultan and without a fleet.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Joint note of the great powers", "2a3b8316"], "d": ["The five powers presented a note to the Sublime Porte asking it not to reach an agreement alone on the Egyptian question. An internal matter thus officially became a \"European question\"; the Ottoman state in practice lost the authority to decide about its own province.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Treaty of London: four powers on the Ottoman side", "a517f775"], "d": ["The treaty, signed with France left out, gave Mehmed Ali an ultimatum: if he accepted within ten days, the hereditary governorship of Egypt and Acre for life; if within twenty days, Egypt only; if he refused, nothing. The governor refused.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardment of Beirut and allied landing", "0905ce92"], "d": ["The British-Austrian fleet bombarded Beirut; arms were distributed to the people who rose against Egyptian rule in the mountains of Lebanon. Ibrahim Pasha's control of Syria collapsed between internal revolt and external intervention.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut and the coastal cities lost", "09bdaf23"], "d": ["After the clashes in the direction of Baalbek, the Egyptian forces withdrew from the coast. On the map the Lebanese coast leaves the tributary tone and returns to direct Ottoman administration.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Acre fell in two hours", "5aec21f0"], "d": ["Under the bombardment of the allied fleet, the fortress's magazine exploded and Acre surrendered within a few hours. The fortress that Ibrahim Pasha had been able to take in six months eight years earlier showed the superiority of naval artillery.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Convention of Alexandria", "85cb47b0"], "d": ["Mehmed Ali agreed to renounce Syria, Adana, Crete and the Hejaz, to return the Ottoman fleet and to recognize the sovereignty of the sultan; in return the hereditary governorship of Egypt was guaranteed.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Egyptian army evacuated Syria and Çukurova", "719a28dc"], "d": ["The occupation of nine years ended; Ibrahim Pasha's army returned to Egypt by way of Sinai. On the map the broad belt extending from Aleppo to Gaza and from Adana to Crete passes again to direct Ottoman administration. Other settlements lost on the same date: Urfa, Maraş, Tarsus, Antioch, Candia (Crete), Hama, Damascus, Jerusalem, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman: governorship of Egypt left hereditary to the Kavalalı family", "87b89ff8"], "d": ["The sultan's firman recognized the governorship as passing from father to son within the dynasty; in return the strength of the army was reduced to eighteen thousand, taxation was tied to Istanbul, and the authority to mint coins and to conclude treaties was removed. Egypt remained a province but was now the domain of a separate dynasty. The administration of the Hejaz and the Haramayn returned to the Sublime Porte. Other settlements returning from the tributary layer to the direct layer on the same date: Mecca, Medina, Jeddah, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["London Straits Convention", "0e95a1ea"], "d": ["The convention, which replaced Hünkâr İskelesi, stipulated that the Straits were closed to all warships in time of peace. The privilege that Russia had won alone thus became a common guarantee of Europe; the question of the Straits acquired an international status.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ibrahim Pasha became governor of Egypt in practice", "9e14f5d9"], "d": ["In place of Mehmed Ali, who was ageing and losing his mental faculties, his son Ibrahim Pasha was installed in the governorship. A few months later, however, in November 1848, he died before his father.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Death of Kavalalı Mehmed Ali Pasha", "871310e0"], "d": ["The governor, who was born in Kavala, founded a dynasty in Egypt and twice brought the empire to the edge of the abyss, died at the age of eighty. The dynasty he founded ruled Egypt until 1953; the state, seeing that it had been able to close the wound he opened only by European intervention, advanced on the path of the Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış was defeated and killed at Aynüseylem; Antioch left the Anatolian Seljuks", "0412dfa1"], "d": ["Süleyman b. Kutalmış, who had taken Antioch from Byzantium in 1084, was killed in the battle of Aynüseylem that he fought with Tutuş, the ruler of the Syrian Seljuks; the city passed to the control of the Great Seljuk Sultan Malik-Shah, and Yağısıyan was appointed governor.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Malik-Shah died; Antioch, together with Yağısıyan, became attached to Tutuş of the Syrian Seljuks", "c61da1b4"], "d": ["Following the death of the Great Seljuk Sultan Malik-Shah, the state was divided among his heirs; Yağısıyan, governor of Antioch, became attached to Tutuş, the ruler of Syria.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nicaea surrendered to the Crusaders; the Seljuk centre withdrew to Konya, and Byzantium began to retake western Anatolia", "8a4e90fa"], "d": ["After the Crusaders' siege of Nicaea, the city surrendered to Byzantium on 19 June 1097; the Seljuk sultan Kilij Arslan I withdrew his centre to the interior, to Konya, while Byzantium took back places on the western Anatolian coast such as Ephesus.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kilij Arslan II took Dorylaion (Eskişehir) and Kütahya from Byzantium", "3ddee6c2"], "d": ["After Myriokephalon (1176), Byzantium's fortresses of Dorylaion and Kütahya in the Anatolian interior passed into the hands of Kilij Arslan II in 576/1180, in the last years of Manuel or after his death.", "4358e7d4"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Death of Ertuğrul Gazi and Osman Bey's accession to the beylik — the legacy of Söğüt and Domaniç", "395fb9fa"], "d": ["According to TDV, Ertuğrul Gazi died in the year 680 (1281-82); the entry notes that the dates 1288 and 1289 are also given. Osman Bey inherited from his father not a conquered city but two grants that the Seljuk sultan had made to Ertuğrul, whom he had settled on the most advanced line of his frontier region: winter quarters (yurtluk) at Söğüt and summer pasture (yaylak) at Domaniç. That is, the beylik began not with an inheritance of conquest but with two grants of pasture; on the map these two places are shown as 'inheritance', not 'conquest'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Sicilian Vespers — the House of Anjou lost the island of Sicily", "547db635"], "d": ["The uprising that broke out in Palermo at the hour of the evening prayer on Easter Monday against the rule of Charles I of Anjou tore the island of Sicily from the House of Anjou. The Kingdom of Sicily was divided in two: the island turned to Aragon, while the House of Anjou held on in the mainland kingdom centred on Naples. The dynasty's overseas possessions in the Adriatic and the Mediterranean also remained attached to this kingdom: Corfu, which they had held since 1267, and Durazzo, which they had held since the 1270s, continued as part of the Kingdom of Naples; the fortresses of Valona, Kanina and Himara on the Albanian coast also remained in the Naples-centred kingdom (the commander of Valona, John of Taxis, resisted the Byzantines throughout 1282; Durazzo, Valona and Kanina most probably passed to Byzantium in early 1285). Malta, however, fell into the hands of the Aragonese only in 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Raid on Kulacahisar — Osman Bey's first military operation", "79b00b14"], "d": ["TDV, Osman I entry: 'He plundered and set fire to the small Kulaca Castle near İnegöl (684/1285).' This is Osman Bey's first datable military action in the sources. No lasting settlement was captured; the castle was plundered and burned, so it is a classic frontier raid rather than a conquest. It is regarded as the starting point of the beylik's military activity.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Conquest of Karacahisar — first urban gain and dominion over Eskişehir", "178ae619"], "d": ["TDV, Osman I entry: in 687 (1288) Osman Bey 'conquered Karacahisar and became master of Eskişehir'. This is the beylik's first real urban gain, and according to tradition Osman Bey rose with this success to the sancak beylik on the frontier; it is related that the first Friday khutba was read in his name at Karacahisar and that the first kadi was appointed here. The TDV Eskişehir entry notes that the Ottoman tradition gives the date 1291, but that its accuracy is doubtful.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Fall of Acre to the Mamluks — liquidation of the Crusaders from the Syrian coast: Sidon and Beirut", "3ca7a464"], "d": ["Acre, which had long been the centre of the Crusader Kingdom of Jerusalem, was conquered by the Mamluk Sultan al-Malik al-Ashraf Khalil, and the Crusaders' dominion in Palestine came to an end. The Templar knights who withdrew from Acre took refuge in Sidon; when the Mamluk army approached, they abandoned the sea castle and fled to Cyprus, and the city passed to the Mamluks the same summer. Beirut, too, which had been in Crusader hands since 1197, was taken in 1291 by the governor of Damascus, Sanjar al-Shuja'i. The Crusader presence of two centuries was thus erased from the Syro-Palestinian coast.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Conquest of Bilecik and Yarhisar by night raid", "f461b0af"], "d": ["TDV, Bilecik entry: 'Although the other tekfurs of the region, among them the tekfur of Bilecik, prepared an assassination of Osman Gazi, when this plot was learned of the Ottoman forces conquered Yarhisar and Bilecik by a sudden raid (1299).' The two fortresses were taken in a single operation, in the same night raid. This date is the turning point accepted as the year of the founding of the Ottoman State. Other places joined on the same date: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Battle of Koyunhisar (Bapheus) — first great victory over a Byzantine army", "584a9512"], "d": ["TDV, Osman I entry: on 27 July 1302 Osman Bey fought the Byzantine army at Bapheus (Koyunhisar) and defeated it. This victory is the turning point that raised Osman Bey from being a regional frontier lord to the status of founder of a dynasty. After the battle the plain of Bursa came under Ottoman control and the blockade of Nicaea began.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Victory at Dimbos and the subsequent taking of Kite and Ulubat", "e168ab64"], "d": ["TDV, Osman I entry: in 702 (1303) the alliance formed by the tekfurs of Bursa, Kestel, Kite and Adranos was routed in the Dimbos defile; the enemy was driven back, fighting, as far as the narrow defile, and the tekfur of Kestel died on the battlefield. Immediately after the victory the fortresses of Kite and Ulubat were seized, cutting Bursa's land connection and tightening its blockade. The young Orhan also took part in this battle.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Sakarya campaign: taking of Leblebicihisar, Lefke, Mekece and Geyve", "a51ba4d3"], "d": ["TDV, Osman I entry gives the order of the Sakarya campaign of 704 (1304): 'When he came to Leblebüci Castle, the tekfur submitted... He arrived at Lefke... He reached Mekece... He went to Geyve and took the castle, which he found empty.' Lefke is the gate of the Sakarya valley opening toward Bilecik. This single campaign, by bringing the chain of fortresses extending along the valley under Ottoman control, closed the eastern flank of the Nicaea basin.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chios passed under the control of the Genoese Zaccaria family", "9eebe4de"], "d": ["Faced with the Aydinid threat, the Byzantine emperor asked for help from the Genoese Benedetto Zaccaria; the island passed under his control (nominal Byzantine vassalage). The Zaccaria domination lasted until 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos entered the possession of the Genoese (Zaccaria) in Chios", "0e6f51e3"], "d": ["The Genoese Zaccaria family, which took Chios under its control, also added to its possession Samos, which had been almost emptied (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Conquest of the Geyve Pass fortresses: Karaçepüş, Karatigin and Absu", "76907c78"], "d": ["TDV, Orhan entry: in the Sakarya campaign of 705 (1305) Orhan 'conquered the fortresses of Karaçepüş (Katoikia), Karatigin before Nicaea, and Absu (Hypsu: in the Geyve Pass)'. These three fortresses, by closing the passage between the Sakarya valley and the Nicaea basin, completely cut off Nicaea's help by land. Gazi Abdurrahman was settled at Karaçepüş and Absu in the Geyve pass; the city could now be brought down only by hunger.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Adranos (Orhaneli) campaign — Osman Bey's last campaign", "4811546c"], "d": ["TDV, Orhan entry records the campaign against Adranos Castle in the autumn of 1323 as Osman Bey's last campaign. The tekfur of Adranos had been a member of the alliance of tekfurs formed against the Ottomans at Dimbos twenty years earlier; this campaign meant the settling of that account. The exact day of the fortress's conquest is unknown; the operation was continued by Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Death of Osman Gazi and Orhan Bey's accession to the beylik", "021487cd"], "d": ["Osman Gazi, who gave the beylik its name, died in the year 724 (1324), as attested by the endowment deeds (vakfiye) of Asporça Hatun and Mekece. His son Orhan, who had been at the head of the army on campaigns since 1305, took the head of the beylik on his father's death without any struggle for the throne. The founding generation's passing the standard on without upheaval shows that the dynasty passed its first great test on the road from frontier beylik to state with calm.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["The taking of Chios from the Zaccaria and its attachment to Byzantium", "f6741b26"], "d": ["Emperor Andronikos III removed the Zaccaria from the island and attached the island to Byzantium under the governorship of Benedetto III. The island will be occupied in 1346 by the Genoese Simone Vignoso.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos returned from the Zaccaria to Byzantium (the Chios chain)", "08034974"], "d": ["With the collapse of the Zaccaria lordship (the attachment of Chios to Byzantium in 1329), the Genoese possession in Samos also came to an end.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Battle of Pelekanon (Maltepe) and the taking of the whole of Kocaeli", "389e7bd4"], "d": ["TDV, Orhan entry: on the first day of the battle Orhan Gazi sent a force of three hundred men to draw the Byzantine army toward himself; on the second day the battle grew as the units under Pazarlu's command descended onto the plain, and when the emperor was wounded by an arrow, panic broke out in the Byzantine army. The result is decisive: 'Orhan seized the whole of Kocaeli; after the victory the people of Nicaea had no hope left.' The coastal towns from Hereke to Üsküdar came under Ottoman rule, and Gebze was made the centre of the region. This was the last Byzantine imperial army that came to save Constantinople.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Founding of the first Ottoman madrasa at Nicaea", "c85fb625"], "d": ["Immediately after taking Nicaea (İznik), Orhan Bey appointed Çandarlı Kara Halil kadi here, converted a basilica into a mosque, and began the city's development by having an imaret and a madrasa built beside it. According to the TDV entry Davud-i Kayseri, the construction of the madrasa was completed in 1336, and Orhan Gazi brought Davud-i Kayseri to its professorship at 30 akçe a day. This madrasa is the first institutional step of Ottoman scholarly life; the beylik thus added a scholarly tradition to its conquering power. The transformation of a Byzantine city taken by conquest into a centre of Islamic learning was the first concrete sign of the Ottoman claim to be an established state.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Byzantium made tributary — siege of İzmit and treaty", "0c1ec8d3"], "d": ["TDV, Orhan entry: in the summer of 733 (1333) Orhan besieged İzmit with a large army and with mangonels, and the emperor consented to a treaty. In return for his giving up the siege, Byzantium agreed to pay Orhan 12,000 gold pieces (hyperpyra) a year; 'thus in the eyes of the Ottoman emir Byzantium fell to the condition of a tribute-paying country'. In return Orhan would be a friend of the emperor and would not attack the cities subject to Byzantium. A frontier beylik's imposing tribute on the Eastern Roman Empire was a proclamation of how far the balance of power had turned.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samothrace passed from the Venetians to the Genoese Gattilusio family", "c499ed5f"], "d": ["The Genoese Gattilusio family removed from the island the Venetians who had held it since 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Annexation of the Karesi Beylik: Balıkesir, Pergamon, Biga, Edremit and Erdek", "c7cb0511"], "d": ["TDV, Orhan entry (İnalcık) places the annexation in 735 (1334-35): upon the death of Demirhan Bey, the Karesi ghazis and Hacı İlbey invited Dursun Bey to the throne and asked Orhan for help. Orhan first marched on Balıkesir; when Dursun Bey, who went to a peace negotiation, was killed by an arrow shot from the Pergamon fortress, the beylik was joined entirely to Ottoman territory. In the same operation Kirmasti and Mihaliç submitted, Gölyazı was taken, and Ulubat, which had earlier been left on terms of safe-conduct (eman), was definitively seized. Orhan appointed Süleyman Pasha to the sancak of Karesi and made Biga the frontier centre — the seafaring cadre for the crossing to Rumelia was thus gained. Note: the TDV entry Karesioğulları gives the date 746 (1345) for the same event; the encyclopaedia contradicts itself. Other places joined on the same date: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos entered the possession of the Maona of Chios", "01628b2f"], "d": ["With the taking of Chios by the Genoese Simone Vignoso and the leaving of the administration to the Maona company, Samos also entered the possession of the Genoese of Chios (the Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Orhan Gazi's first capitulation with the Genoese", "e64cb196"], "d": ["Orhan Gazi, who came to terms with the Genoese during the Venetian-Genoese war, after the Bosporus battle of February 1352 sent 1000 archers to the defence of Pera and provided 60,000 gold pieces for the transport of troops; in return he granted the Genoese the first capitulation. The full text of the treaty has not come down to the present. This is the first official agreement the Ottomans made with a European naval power, and it was to be renewed thirty-five years later, in 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Taking of Gallipoli — permanent bridgehead in Rumelia", "ba51a160"], "d": ["The Ottomans took Gallipoli in 1354, a place whose surroundings they had come to know between 1349 and 1352 as allies of Kantakouzenos; the great earthquake that brought down the city's walls had provided the opportunity. The narrow bridgehead at Çimpe thus turned into a real base on the Rumelian side of the Straits, and the gate opening to Thrace was opened wide. Gallipoli was to be lost in 1366 to the Savoyard crusade, but with the second conquest in 1376 it was to come definitively under Ottoman dominion. Other places joined on the same date: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Death of Süleyman Pasha, conqueror of Rumelia", "2dc98228"], "d": ["Süleyman Pasha, Orhan Bey's eldest son and the architect of the conquests in Rumelia, died in the autumn of 1357, the most widely accepted of the dates given in the sources as 758 (1357), 759 and 760 (1359), falling from his horse during a hunt. The death of the prince, who established the permanent Ottoman presence in Rumelia through his crossings between 1352 and 1354, left the order of succession to his brother Murad. The tomb of Süleyman Pasha, buried at Bolayır, remained the oldest dynastic monument of the Ottomans in Europe.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Pencik Law — laying of the foundation of the Janissary Corps", "e5877c2d"], "d": ["After the conquests in Rumelia, on the advice of Karamanlı Kara Rüstem of the ulama, the pencik system, which provided for setting aside for the state one fifth of the prisoners of war or its equivalent in money, was put into force. Through those chosen from these prisoners being raised with Turkish families and then taken into the army, the nucleus of a permanent infantry force directly attached to the sultan — the Janissary Corps — was formed. The transformation of a frontier beylik based on tribal cavalry into a state with a central army began with this arrangement.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Descent into Western Thrace: conquest of Gümülcine", "9ef69221"], "d": ["After the taking of Edirne, the frontier forces that turned to the west of the Maritsa took Gümülcine (Komotini), the centre of Western Thrace, under the command of Gazi Evrenos Bey. The city became the forward headquarters from which Evrenos Bey would carry his raids into Macedonia. The part of Thrace extending to the Aegean coast thus came under Ottoman control, and the road to Thessalonica was opened.", "0206d2bb"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["West of Plovdiv: annexation of Tatarpazarcığı and İhtiman", "1664d0e1"], "d": ["After the taking of Plovdiv (Filibe) in 1372, Tatarpazarcığı at the upper end of the Maritsa valley and İhtiman (Ihtiman), which held the pass opening toward Sofia, were attached to Ottoman administration. This line, which was in the hands of the local lords who became vassals after the Battle of Chirmen, was placed under direct administration, making the Plovdiv-Sofia route continuous. This advance was the preparation for the road leading, twelve years later, to the conquest of Sofia.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Rebellion of Savcı Bey — joint revolt of a prince and the Byzantine heir", "75198c33"], "d": ["Savcı Bey, son of Murad I, and Andronikos Palaiologos, son of the Byzantine Emperor John V, rose against their fathers simultaneously in Bursa and Constantinople at the beginning of May 1373. This alliance, which united the heirs of the two dynasties, was swiftly suppressed; Savcı Bey was captured, blinded and executed. The date 787 (1385) given for the rebellion by the Ottoman tradition is erroneous; the event falls just after the years in which Byzantium entered Ottoman vassalage and shows how intertwined the two courts were.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Strymon and Mesta valleys: annexation of Kyustendil, Petrich, Nevrokop and Drama", "8c0980c4"], "d": ["The Strymon and Mesta valleys, held by the Serbian and Bulgarian local lords who had begun to pay tribute to the Ottomans after the victory of Chirmen, were taken under direct Ottoman administration through the advance of the frontier lords. With the annexation of Kyustendil, Petrich, Nevrokop and Drama, the eastern half of Macedonia was opened, and Thessalonica and Serres came within the ring of siege. The expansion of Rumelia toward the south-west on the map is the result of this operation.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur took Herat: end of the Kart dynasty and the passage of Khorasan to the Timurids", "15f6019e"], "d": ["In 1380 Khorasan lay fragmented by the struggle among the Sarbadars, the Karts and the Muzaffarids. After sending his son Miran Shah to the region, Timur himself marched on Herat and, after besieging it for some time, took the city over from the Kart malik Ghiyath al-Din Pir Ali. The revolt that broke out after his departure was suppressed in blood by Miran Shah, and the Kart dynasty, which had ruled in Herat since 1255, was brought to an end. All of Khorasan, from Mashhad to Nishapur, came under Timurid rule on this date.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["End of the Eretna Beylik and founding of the State of Kadı Burhaneddin", "60dcaf57"], "d": ["The Eretnids, who arose in 1335 from the Ilkhanid governorship and governed Central Anatolia, centred on Sivas and Kayseri, for forty-six years, dissolved through palace intrigues. Kadı Burhaneddin, who became vizier in May 1378, after eliminating his rivals Kılıcarslan and Hacı Şadgeldi, proclaimed his sultanate in the autumn of 1381, ended the beylik and founded the state known by his name. The eastern neighbour of the Ottomans thus changed hands; the Sivas-Kayseri line was to remain in the hands of Kadı Burhaneddin for seventeen years thereafter.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Advance into Macedonia: conquest of Monastir and Ohrid", "63bb7838"], "d": ["Monastir (Bitola) on the Via Egnatia and Ohrid on the lakeshore came under Ottoman administration during the raids in the direction of Albania. Both were key points on the road extending to the Adriatic; Ohrid was moreover the oldest Orthodox archiepiscopal centre of the Balkans. TDV records that there is no certain information on the date of the conquest of Ohrid, and that the dates 787 (1385) and 797 (1395), after the death of Marko Kraljević, have been put forward; 1385 has been taken as the basis here. In the following centuries Monastir was to become one of the most important military centres of Rumelia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Battle of Savra — opening of the gates of Albania", "dda6671b"], "d": ["At the call for help of the Albanian lord Karlo Thopia, hard pressed against the Balšić dynasty, the Ottoman forces routed the army of Balša II on the plain of Savra; Balša lost his life on the battlefield. This battle, entered upon at the invitation of a native lord, gave the Ottomans their first lasting influence in the Albanian lands extending to the Adriatic coast. This policy, which turned the setting of the region's lords against one another into an opportunity, was to be the unchanging method of Balkan conquests throughout the next century.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Timur's 'Three-Year Campaign': conquest of Azerbaijan and northern Iran", "2a98ec51"], "d": ["Timur, who had seen at close quarters the fragmented state of Iran during the Khorasan campaigns, marched west in 788 (1386). In the operations of 1386-1388, known as the 'Three-Year Campaign', he passed through Mazandaran, Luristan and Georgia into Azerbaijan and reached Karabakh; Tabriz, Ardabil, Urmia and Nakhchivan came under Timurid rule. His seizure of northern Iran and Azerbaijan was also the beginning of a long contest with the Golden Horde, as had once been the case between the ulus of Jochi and the Ilkhanids.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Battle of Frenkyazısı and siege of Konya — first Karaman campaign", "af4e5d77"], "d": ["Murad I himself set out on campaign against the Karamanid Alaeddin Ali Bey, who, although his son-in-law, was disturbed by the Ottoman expansion in western Anatolia; in the battle fought at the place called Frenk Yazısı, the trained and experienced Ottoman army defeated the Karamanid forces. Then the fortress of Konya was besieged, but with the pardoning of Alaeddin Bey the beylik was not entirely abolished. This campaign is the opening act of the long reckoning between the Ottomans and Karaman, which would last a century and end only with the definitive annexation in 1468.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Founding of the Gallipoli Dockyard — birth of the Ottoman navy", "47546241"], "d": ["The first properly organized dockyard of the Ottoman State was founded in 1390 by Bayezid the Thunderbolt at Gallipoli, on the site of the dockyard left over from Byzantium. The Ottomans, inheriting the seafaring legacy of the western Anatolian beyliks, thus for the first time became a naval power that built its own ships. Located at the key point of the Dardanelles, the dockyard served for a century and a half as the main base of the Ottoman navy, from the siege of Constantinople to the Aegean campaigns.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Taking of Varna on the Black Sea coast", "a84b2abf"], "d": ["During the squeezing of the lands of the Bulgarian Tsardom between the Danube and the Black Sea, Varna, the greatest port on the coast, passed to Ottoman administration. The taking of the port opened the way for the advance toward Dobruja and gave the Ottomans their first great landing place on the western coast of the Black Sea. Varna was also to be the scene of the victory of 1444, in which the Crusader army would be destroyed fifty-three years later.", "421a978f"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["End of the Muzaffarid dynasty: Shah Mansur defeated before Shiraz", "5fd14eb8"], "d": ["Shah Mansur, the last powerful ruler of the Muzaffarids, who had ruled in Yazd, Fars, Isfahan and Kerman since 1318, united with his relatives and moved against Timur. In the battle near Shiraz, when one of his emirs went over to the other side, he lost most of his forces and was defeated and killed. When Timur afterwards had all the members of the dynasty killed as well, Muzaffarid dominion came to an end and Fars and Kerman were joined to Timurid rule.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Annexation of Amasya to Ottoman lands", "fe2860cf"], "d": ["The emir of Amasya, besieged during Bayezid the Thunderbolt's operation in Central Anatolia, surrendered the city to the Ottomans, and Bayezid entered the city in 1393. The sultan left its administration to his son Mehmed Çelebi; as a princely sancak, Amasya thereafter became one of the most important training grounds of the Ottoman dynasty. This choice was to prove decisive in the later Interregnum, and Çelebi Mehmed was to conduct his struggle to reunify the state from precisely this Amasya base.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur seized Baghdad — the Jalayirids fled to Anatolia", "4d5602b3"], "d": ["Timur took Baghdad after a long siege; the Jalayirid Sultan Ahmed, the ruler of the city, fled westward and took refuge first with the Mamluks and then at the Ottoman court. Timur's expansion to the west thus came for the first time into direct contact with the Ottoman sphere of influence. The first link in the enmity between the two rulers begins here.", "2fac674f"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["The Nevşehir and Ürgüp region passed from the Karamanids to the Ottomans", "06ff59e8"], "d": ["In Bayezid the Thunderbolt's campaigns against the Karamanids, the Nevşehir (Muşkara) and Ürgüp region passed to Ottoman administration in 800/1398; in 1402, after the Battle of Ankara, Timur gave the region back to the Karamanids.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Fall of the State of Kadı Burhaneddin", "b13391e3"], "d": ["Kadı Burhaneddin, who fell prisoner to the Aqquyunlu ruler Qarayuluk Osman Bey, offered to be released in return for the surrender of Sivas, but the people of the city resisted, and the sultan was executed before the walls. Although the notables of Sivas installed his son Alaeddin Ali Çelebi at the head, in the face of Aqquyunlu pressure they asked help from Bayezid the Thunderbolt; the Ottoman forces under the command of Süleyman Çelebi defeated Qarayuluk and became master of the city. The State of Kadı Burhaneddin thus passed into history, and Sivas, Tokat, Niksar and Kayseri were joined to Ottoman lands. Other places joined on the same date: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Timur's test of will: refusal to return the fugitives", "33790bc8"], "d": ["Under Timur's pressure, the Jalayirid Sultan Ahmed and the Qaraquyunlu leader Qara Yusuf took refuge in Ottoman territory; Timur demanded the return of these two fugitives, and Bayezid the Thunderbolt refused. Thereupon letters containing mutual grave insults began to be exchanged between the two rulers. The ideological ground of the war was laid by this correspondence, before a single soldier had moved.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["The Yıldırım Darüşşifa at Bursa — first Ottoman hospital", "5f0dc59a"], "d": ["In the years in which Bayezid the Thunderbolt had the magnificent Great Mosque (Ulucami) built at Bursa, he also gave the city a dar al-shifa (hospital); this was the link devoted to medicine in a broad programme of pious foundations consisting of an imaret, a madrasa, a han and a bridge. This building, the first hospital founded by the state, also functioned as a medical school training physicians, and determined the model of Ottoman health institutions. Completed only two years before the Ankara catastrophe, the work is among the last links of Yıldırım's vision of turning Bursa into an imperial capital.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur razed Sivas", "f4d79de6"], "d": ["Timur, who marched on Sivas guided by the Aqquyunlu Qarayuluk Osman Bey and the emir of Erzincan, Mutahharten, besieged the city for eighteen days and, after taking it over with the promise that no one's blood would be shed, carried out a great massacre; he had the defenders thrown into trenches and had them covered over alive. The city's important works, beginning with the walls, were destroyed, and Sivas collapsed demographically. This was the first great blow that Timur dealt to Ottoman lands, two years before the Battle of Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid the Thunderbolt retook Erzincan and Kemah", "7047ca08"], "d": ["Bayezid the Thunderbolt, taking advantage of Timur's setting out on his Syrian campaign, took Erzincan and Kemah from the hands of the emir of Erzincan, Mutahharten, who was subject to Timur. Although he had not intervened in the destruction of Sivas, this move amounted to a direct challenge to Timur's sphere of influence in eastern Anatolia. The relations of the two rulers thereafter became beyond repair.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Timur's ultimatum sent from Tabriz — four conditions", "3e1ac50e"], "d": ["Timur communicated four conditions through an envoy sent from Tabriz: the return of Kemah to Mutahharten, the restoration to their owners of the lands taken from the Anatolian beys, the sending of an Ottoman prince as hostage and the acceptance of the cap (külah) and belt as marks of vassalage, and the surrender of Qara Yusuf. Bayezid accepted none of these; despite the insistence of statesmen and the mediation of Mutahharten, the negotiations collapsed. Timur was determined to close the Anatolian question definitively before setting out on the China campaign.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanids re-established — Manisa left the Ottomans", "ac747b05"], "d": ["Three weeks after the Ankara disaster, with Timur's support, Orhan Bey took over the head of the beylik and the land of Saruhan became independent again. The region centred on Manisa disappeared from the map twelve years after the Ottoman annexation of 1390. This is among the first applications, with a securely known date, of Timur's policy of reviving the beyliks.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman fled to Rumelia with the state treasury", "0a2b7363"], "d": ["Emir Süleyman, taking with him the state treasury at Bursa, the archives, his family and his brothers, crossed from Gemlik by ship to Güzelcehisar (Anadoluhisarı), reached Gallipoli from there and proclaimed his rulership at Edirne. The transfer of the state archive and treasury to Rumelia is the beginning of the shift of the Ottoman centre of gravity to the Balkans for a generation. On the map Rumelia is drawn from this date in Emir Süleyman's own colour.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur re-established the Anatolian beyliks — Turkish unity dissolved", "15187774"], "d": ["After the victory at Ankara, Timur restored the beys who were with him to their former lands. To the Karamanid Mehmed and Ali Beys he gave the land of Karaman together with Kayseri, Kırşehir, Sivrihisar and Beyşehir; to the Germiyanid Yakub Bey II, Kütahya and the land of Germiyan; to the Candarid İsfendiyar Bey, in addition to the Kastamonu-Sinop line, Çankırı and Kalecik. The lands of Aydın, Menteşe and Teke also returned to their former dynasties. The Anatolian Turkish unity that Bayezid the Thunderbolt had built in ten years dissolved in a single summer; on the map these beyliks reappear in their own colours.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur took İzmir from the Knights of Saint John", "66dd1dd4"], "d": ["Timur, descending westward by way of Kütahya, Denizli, Aydın, Ayasuluk and Tire, besieged and took the coastal city of İzmir, which had been in Christian hands since 1344. Having quickly seized this fortress that Bayezid the Thunderbolt had been unable to take for years, and having taken the surrounding fortresses as well, Timur left the land of Aydın to its former owners and turned eastward. The city thereafter came under the administration of Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Isa Çelebi seized Bursa — the Anatolian share was born", "955128c1"], "d": ["Isa Çelebi, who had withdrawn to the Karesi region after the Ankara disaster, seized Bursa while Timur was at İzmir. In the former capital, plundered and burned by Timur's soldiers, he proclaimed his rulership and had coins struck in his own name; in January 1403 he was recognized in Anatolia with the title 'ruler of the Turks'. On the map this share, extending along the Asian shore of the Marmara, appears in Isa Çelebi's own colour.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Timur's withdrawal from Anatolia", "93a98839"], "d": ["Timur, receiving the news that Bayezid the Thunderbolt had died at Akşehir, regarded his business in Anatolia as finished and turned eastward. Behind him remained the beyliks that had declared loyalty to him and the Ottoman princes set against one another; some cities, such as Sivas, were left in the hands of emirs subject to Timur, such as Mezid Bey. Timur never returned to Anatolia, but the fragmented order he established lasted ten years.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman crossed to Anatolia: Bursa came into his hands", "9b27aa5f"], "d": ["Emir Süleyman, hearing of Isa Çelebi's defeat, crossed to Anatolia with a strong army together with Çandarlı Ali Pasha and seized Bursa; records of March 1404 show that Karadeniz Ereğli too was under his rule. Çelebi Mehmed could not resist Süleyman, who soon came to dominate both Rumelia and the greater part of Anatolia. On the map, from this date until Çelebi Mehmed's retaking of Bursa (1410) the two shores appear in a single colour, in Emir Süleyman's share.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Battle of the Yenişehir Plain — Çelebi Mehmed withdrew to Amasya", "f1568288"], "d": ["Çelebi Mehmed, who had lost Bursa and Ankara, was defeated by Emir Süleyman on the plain of Yenişehir, lost all his gains in western Anatolia and withdrew to his base at Tokat-Amasya. After this defeat he avoided direct confrontation and turned to consolidating his authority in the interior of Anatolia. The longest quiet phase of the Interregnum began in this way.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman took Ankara from Çelebi Mehmed", "d6a2acd6"], "d": ["Emir Süleyman besieged in 1406 Ankara, which had remained in Çelebi Mehmed's hands after Timur's withdrawal from Anatolia. The commander of the fortress, Yakub Bey, held out for a time, but through a stratagem of the grand vizier Çandarlı Ali Pasha he surrendered the fortress to Süleyman. Thereupon Çelebi Mehmed came to an agreement with the Karamanid Mehmed Bey and moved against Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed retook Sivas from the Timurid Mezid Bey", "90079b0c"], "d": ["After the Timurid invasion the administration of Sivas had been left to Mezid Bey, who was subject to Timur. Çelebi Mehmed at Amasya sent his commander Bayezid Pasha to take the city, and after fierce resistance Sivas passed for the second time into the hands of the Ottoman dynasty. Mehmed's share thus reached its former frontier in the east, six years after the Battle of Ankara.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["End of the Artuqid dynasty: surrender of Mardin to the Qaraquyunlu", "15b06f33"], "d": ["The Artuqids, who had ruled in Mardin since 1106 and were the longest-lived branch of the dynasty, could not hold out in the face of Aqquyunlu pressure. Malik Ahmed, realizing that he could not defend the city, came to terms with the Qaraquyunlu ruler Qara Yusuf and surrendered Mardin to him. Artuqid dominion of over three centuries thus ended; Mardin and its surroundings were the scene of the Qaraquyunlu-Aqquyunlu struggle until its passage to the Ottomans a century later.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Battle of Yambol — Musa Çelebi entered Edirne", "8f978408"], "d": ["Musa Çelebi, who crossed to Rumelia by way of Wallachia, routed Emir Süleyman's forces at Yambol with Wallachian and Serbian support and entered Edirne. In the Interregnum, Rumelia thus for the first time left Emir Süleyman's hands. His dominion, however, was not lasting; four months later he was to be defeated at Kosmidion and withdraw into the interior of the Balkans.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Battle of İnceğiz — Çelebi Mehmed's first defeat in Rumelia", "3c35cd43"], "d": ["Çelebi Mehmed, who crossed to Rumelia with Byzantine ships, engaged Musa Çelebi in battle at İnceğiz; Musa, with seven thousand Janissaries under his command, defeated Mehmed, and Mehmed was forced to return to Anatolia. This defeat turned Mehmed away from direct fighting toward a strategy of drawing the Rumelian frontier lords and the Serbian despotate to his own side. The ground for the victory of Çamurlu nine months later was prepared by this diplomacy.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Siege of Konya and treaty with the Karamanids — Hamid-ili, Said-ili, Beyşehir, Seydişehir and Akşehir recovered", "0996257e"], "d": ["Çelebi Mehmed mounted a great campaign against the Karamanids, who had attacked Ottoman territory and besieged and burned Bursa during the Interregnum, and besieged Konya in Muharram 818. Karamanid Mehmed Bey II was compelled to ask for peace; as a result of the treaty, Hamid-ili (the Isparta region) and Said-ili rejoined Ottoman lands, Beyşehir, Seydişehir and Akşehir were also given back, and Sivrihisar, which Timur had given the Karamanids in 1402, also returned to the Ottomans. This campaign, in which the Anatolian unity shattered by the Battle of Ankara began to be patched together, is among the concrete grounds for regarding Çelebi Mehmed as the 'second founder'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Taking of İzmir from Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["İzmir, the centre of Aydınoğlu Cüneyd Bey, who throughout the Interregnum continually changed sides among the princes, was taken by Çelebi Mehmed after a siege of ten days; Cüneyd was pardoned and sent to the sancak beylik of Nicopolis. The city, which Timur had returned to the Aydınids in 1402, thus returned to the Ottomans after thirteen years. Cüneyd was to seize the city again in 1422, and the matter would be closed only by Murad II in 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Execution of Torlak Kemal — Saruhan definitively Ottoman", "8a09dbf1"], "d": ["Torlak Kemal, who led the western Anatolian wing of the movement of Sheikh Bedreddin, was defeated in the Manisa region and executed. After this date the Saruhan region came definitively under Ottoman control, and the beylik that Timur had revived in 1402 passed into history. The last political remnants of the Interregnum in western Anatolia were thus cleared away.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Conquest of Valona, Berat and Kanina", "1e1949b8"], "d": ["In 1417 the Ottomans brought under their dominion Valona (Avlonya) on the Adriatic coast, together with the city of Berat and the Kanina Fortress in the interior of the country. A year later Venice's attempt to retake the city failed, and by the establishment of a sancak organization here Ottoman authority became permanent. The taking of Valona made the Ottomans for the first time the owner of a port directly on the Adriatic, giving them an overseas springboard facing Italy.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Recovery of Central Anatolia: Kayseri and Kırşehir", "204eacb3"], "d": ["The cities of Central Anatolia that had fallen into the hands of the Karamanids in the Interregnum returned to Ottoman administration during Çelebi Mehmed's campaigns to put the state in order again. With the annexation of Kayseri and Kırşehir, the Kızılırmak basin lost at the Battle of Ankara was to a large extent recovered. This advance is the continuation of the eastward policy begun with the siege of Konya four years earlier.", "c663fc08"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["The death of Mehmed I and the accession of Murad II", "98acac77"], "d": ["Mehmed I, who ended the Interregnum and gathered the Ottoman lands again in a single hand, died at Adrianople on 25 June 1421, and his son Murad ascended the throne at Bursa. According to the arrangement made with Byzantium before his death, his younger sons were to be sent as hostages to the emperor's side, and the emperor in turn would not release the pretender to the throne, Mustafa Çelebi, whom he held; Murad II refused to send his brothers to the emperor.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Definitive liquidation of the Teke Dynasty: taking of Antalya", "e65565b2"], "d": ["The Beylik of the Tekeoğulları, which had been re-established through Timur's reviving it after the Battle of Ankara, came to an end when the Ottoman forces under Hamza Bey besieged Antalya; Osman Çelebi, the last important man of the beylik, was eliminated. The land of Teke on the Mediterranean coast thus definitively joined the Ottomans after a separation of twenty-one years. The beylik had ruled in Antalya since 1321 as the branch that split from the Hamidids.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Turahan Bey's Morea campaign and destruction of the Hexamilion Wall", "c6c2706d"], "d": ["When Byzantium supported the rival claimant to the throne Mustafa Çelebi, Murad II sent Turahan Bey against the Morea. Turahan Bey destroyed the Hexamilion wall that closed the Isthmus of Corinth from end to end, entered the peninsula and caused great devastation. Peace was secured on the conditions that the wall would not be rebuilt and that an annual tax would be paid; the Despotate of the Morea was thus left militarily defenceless, and the ground for the final conquest of 1460 was prepared thirty-seven years in advance.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Athos monasteries came under Ottoman protection", "562de5ea"], "d": ["In the years when Thessalonica was under siege, the monastic republic of Mount Athos (Aynaroz) on the eastern prong of Chalkidiki applied to Murad II, asked for protection and accepted Ottoman rule. The monks' rights of property and worship were guaranteed; in return for tax, the monasteries were left free in their internal affairs. This arrangement became the longest-lived example of the relationship of protection that the Ottomans established with Orthodox institutions, and it lasted five centuries.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Annexation of the Tacettinids Beylik: Niksar", "370ffd47"], "d": ["Under pressure from Yörgüç Pasha, the beylerbeyi of Amasya, Taceddinoğlu Hüsameddin Hasan Bey handed over the keys of his country, centred on Niksar, in the year 830 (1427); he was given a sancak in Rumelia. The beylik, founded in the second half of the fourteenth century and whose borders at times extended to Kelkit, Amasya, Samsun, Ordu and Giresun, thus came to an end. In the same year the lands belonging to the Hacıemiroğulları were also surveyed (tahrir) and attached to the sancak of Canik; the period of the beyliks in the central Black Sea region was closed.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["The ceding of Belgrade to Hungary — the Treaty of Tata", "62481183"], "d": ["Upon the death of the Serbian despot Stefan Lazarević, under the Treaty of Tata concluded between the Hungarian king Sigismund and the heir, Đurađ Branković, the fortress of Belgrade was handed over to Hungary. The fortress, standing at the confluence of the Danube and the Sava, had until then been in the hands of the Serbian despotate and was, for the Ottomans, the lock on the gate opening to Central Europe. This transfer made Belgrade for a hundred years the harshest obstacle before the Ottoman advance: the sieges of 1440 and 1456 would fail, and the fortress would fall only in 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin passed from the Qaraquyunlu garrison commander to the Aqquyunlu Qarayuluk Osman Bey", "d82bc97f"], "d": ["Mardin, which Qara Yusuf took in 1409, was governed by the Qaraquyunlu through governors; Emir Nasir, who had been left as garrison commander, surrendered the city in 835 (1432) to the Aqquyunlu Qarayuluk Osman Bey. Aqquyunlu rule lasted until the beginning of the sixteenth century.", "407382cb"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Buçuktepe Incident — first Janissary uprising and Murad II's return to the throne", "6388dda1"], "d": ["The Buçuktepe Incident, the first Janissary uprising known to history, which broke out in Edirne, began with a demand for an increase of half an akçe in their pay (ulufe) and ended with the deposition of the young Mehmed II from the throne. Murad II set out in haste from Manisa on 8 Safar 850 and began his second reign. The incident became the first sign that the kapıkulu corps had become a force with a voice over the throne, and shaped the Conqueror's lifelong wariness toward the Janissaries.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Annexation of the Epirote coast: Arta and Preveza", "796f7ecf"], "d": ["Nineteen years after the surrender of Ioannina in 1430, Arta and Preveza, on the coastal part of the Despotate of Epirus, also came under Ottoman administration. The Ambracian Gulf opening onto the Ionian Sea was thus brought under control, and Ioannina's sea connection was completed. Preveza is the key point of the bay which, ninety years later, was to give its name to Barbarossa's celebrated victory.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Death of Murad II and the second accession of Mehmed II", "8f8256ad"], "d": ["Murad II, who fell ill after his son's wedding, died at Edirne on 1 Muharram 855 (3 February 1451). The nineteen-year-old Mehmed II acceded to the Ottoman throne for the second time on 16 Muharram 855 (18 February 1451) — this time permanently. The return of the young ruler who had been deposed at Buçuktepe five years earlier is the beginning of the reign that, two years later, would be crowned with the conquest of Constantinople and transform the Ottoman Beylik into a world empire.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["First siege of Kefe by joint Ottoman-Crimean forces", "e346d163"], "d": ["The Crimean khan Hacı Giray, who came to terms with Mehmed the Conqueror in June 1454, besieged Kefe by land with 7000 horsemen; an Ottoman fleet of fifty to sixty galleys also took station offshore. Genoese Kefe had the siege lifted by paying tribute, and the definitive conquest was left to twenty-one years later, 1475. This first joint operation was the first example of Ottoman-Crimean military cooperation, which would be repeated later in the definitive conquest of Kefe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Taking of the northern Aegean islands: Bozcaada, Imbros and Thasos", "76575895"], "d": ["Immediately after the conquest of Constantinople, Mehmed the Conqueror turned to the islands at the Aegean mouth of the Dardanelles in order to secure the new capital's sea route; Tenedos (Bozcaada) and Imbros (İmroz) were taken from Byzantium, and Thasos from the Gattilusio family of Genoese origin. These islands, which lock both sides of the Straits, became thereafter the first link in Istanbul's provisioning and defence line. With the interventions of the papal and Venetian fleets dominion went back and forth for a time and was settled only in 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Conquest of Kosovo: taking of Pristina and Novi Pazar", "d7ed2345"], "d": ["The Ottoman army, marching on the Serbian Despotate, took Pristina on the plain of Kosovo and Novi Pazar (Yenipazar), the centre of the Raška region; in the same operation Novo Brdo, famed for its silver mines, was also taken. The southern half of Serbia was thus attached to direct Ottoman administration, and the despotate at Smederevo was cut off from its central lands. This conquest was the decisive step on the road to the complete annexation of Serbia four years later.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peć) came under Ottoman administration — one of the centres of the sancak of Dukakin", "19511588"], "d": ["Immediately after Mehmed the Conqueror's Serbian campaign of 1455, İpek, the centre of the Serbian patriarchate, passed to Ottoman administration; there is no record of this passage in Ottoman sources. The town in time became a small Muslim town and was one of the residences of the sancak bey in the sancak of Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Conquest of Enez and Samothrace — completion of the Western Thracian coast", "106e723b"], "d": ["Enez (Ainos), at the point where the Maritsa river flows into the sea, was taken from the Gattilusio family of Genoese origin, who had held it for eighty years; the island of Samothrace, attached to it, was also seized in the same operation. With the fall of Enez the coastal strip of Western Thrace became continuous Ottoman territory from Thessalonica to Gallipoli. Only Lesbos (Midilli) remained in the hands of the Gattilusio family; it too was to be taken six years later.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Failure of the siege of Belgrade", "3d53a604"], "d": ["Mehmed the Conqueror, after the conquest of Constantinople, besieged Belgrade, regarded as the lock of Central Europe; however, the reinforcements that John Hunyadi brought down the Danube and the volunteers gathered by the crusade preacher Capistrano prevented the fortress from falling. The sultan, despite the personal heroism he displayed before the siege, was wounded and forced to withdraw. This failure was to close the Hungarian frontier to Ottoman advance for sixty-five years; Belgrade could be taken only in 1521 by Süleyman the Lawgiver.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Conquest of the northern Morea: Balyabadra (Patras)", "c08a8509"], "d": ["The forces of Mehmed the Conqueror, who turned to the Despotate of the Morea in the same years as the annexation of Serbia, took Balyabadra (Patras) in the north-west of the peninsula. This port, which holds the mouth of the Gulf of Corinth, is the lock of the entry into the Morea by land; its taking prepared the ground for the final conquest two years later. The city was the last great landing place by which the Byzantine despots made contact with the Latin world.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Taking of the western Black Sea coast: Amasra", "f43608fc"], "d": ["Amasra, the fortified colony of Genoa on the western Black Sea, surrendered without resistance under the combined pressure of the fleet and land forces of Mehmed the Conqueror. This port on the Bartın-Zonguldak coast had stood as a Latin pocket between the Candarids and Ottoman territory; with its taking the coast was unified. The fall of Amasra was the first step of the great Black Sea campaign directed two years later (1461) at Sinop and Trabzon.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Conquest of the island of Lesbos (Midilli)", "fe17aeba"], "d": ["The Ottoman army under the command of Mehmed the Conqueror took Lesbos in Dhu al-Hijja 866, after a short but fierce siege, from the Gattilusio family of Genoese origin, and annexed it. The fall of the largest island of the northern Aegean also liquidated the last important Genoese base in the region. The island, thanks to its proximity to the Anatolian coast, would thereafter serve as an advance outpost for the Ottoman navy and would also enter naval history as the place where the Barbarossa brothers were raised.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Beginning of the sixteen-year Ottoman-Venetian War", "563ddb68"], "d": ["The Venetians, in order to halt the Ottoman advance in the Morea and the Aegean, began the war in 1463 by allying with the Karamanid and Aqquyunlu rulers. This strategy of encirclement, set up with Uzun Hasan in the east, Venice in the west and Karaman in between, forced the Conqueror to fight on several fronts at once. The struggle, which lasted sixteen years, was to cover all the great operations of the period from Otlukbeli to the Albanian campaigns, and to end only with the Treaty of Istanbul of 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Conquest of most of Herzegovina: Trebinje and Mostar", "f54c0100"], "d": ["The lands of Stjepan Vukčić-Kosača, Duke of Herzegovina, who had established an administration separate from Bosnia, passed largely to Ottoman administration three years after the fall of the Kingdom of Bosnia: in the south, Trebinje was taken in 1466 \"together with almost the whole of the Herzegovina region\". Mostar, which grew up around the two small fortresses of the bridge over the Neretva, must also have been taken shortly before the conquest of Blagaj, the centre of Herzegovina, in 1466-1468; it is recorded under the name \"Köprülü Hisar\" in the Bosnian summary survey (icmal tahrir) of 1468-1469. The conquest of Herzegovina, with the remaining fortresses of the duchy, was completed in 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Second Albanian campaign — the Conqueror's personal march against Skanderbeg", "9cdd2bfa"], "d": ["To break Skanderbeg's resistance, which had lasted more than a quarter century, Mehmed the Conqueror mounted great campaigns in 1466-1467, commanding them in person. The Ottoman army besieged Akçahisar (Kruja) and built the fortress of Ilbasan (Elbasan) in order to bring the region under control. The campaign, while breaking the back of Albanian resistance, did not succeed in bringing down the fortress; the full subjugation of the region was to take ten years after Skanderbeg's death.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Collapse of the Qaraquyunlu State: killing of Jahan Shah", "30bc6358"], "d": ["The Qaraquyunlu ruler Jahan Shah, who was attacked while returning from a campaign against Uzun Hasan because winter had closed in, was killed while fleeing between Bingöl and Kiğı. After this blow the state could not recover; the last ruler, Hasan Ali, was captured and killed in 1469 by Uzun Hasan's son Uğurlu Mehmed. Qaraquyunlu dominion, which had lasted for nearly a century in eastern Anatolia, Azerbaijan and Iraq, thus passed to the Aqquyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Death of Skanderbeg — extinction of Albanian resistance", "9158c35f"], "d": ["Skanderbeg, who, although raised at the Ottoman court, rebelled in 1444 after the Izladi rout and resisted in Albania for more than a quarter century, died at Lezhë (Leş), where he had taken refuge. This resistance, which in the reigns of Murad II and the Conqueror repeatedly occupied Ottoman armies, lost its central leadership with his death. With the collapse of the Albanian front, nourished by the papacy and Venice, the Ottomans took Akçahisar and Shkodër within ten years and definitively annexed the region to their lands.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Ottoman administration established in Kayseri: Gedik Ahmed Pasha ended the Karamanids", "33cf35fc"], "d": ["With Gedik Ahmed Pasha's ending of the Karamanids in 1474, Kayseri came under Ottoman administration; the city had changed hands among the Dulkadirids, the Ramazanids and the Karamanids throughout the 15th century. Under Ottoman rule Kayseri became a sancak centre of the beylerbeylik of Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos abandoned: Genoese (Maona) possession ended", "5bdc380c"], "d": ["According to the TDV, the island was abandoned after 1475; in 1479 Mehmed the Conqueror conquered the island and had a fortress built.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Rout at Racova (Vaslui) in Moldavia", "a1a74bf7"], "d": ["The voivode of Moldavia, Stephen the Great (Ştefan cel Mare), drew the Ottoman forces under the command of the beylerbeyi of Rumelia, Hadım Süleyman Pasha, onto marshy ground and inflicted a heavy defeat on them. This rout, one of the heaviest land defeats of the Conqueror's reign, aroused a great echo in Europe and won Stephen fame in the crusading world. The sultan was to set out on campaign in person the following year in reprisal.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Victory at Akdere (Valea Albă) — Moldavian campaign", "45a66791"], "d": ["Mehmed the Conqueror, who set out on campaign in person to avenge the Racova rout of a year earlier, inflicted a great defeat on the Moldavian forces with the Ottoman army at the place called Akdere and entered Suceava, the centre of the principality. The fortresses, however, could not be taken; because of supply shortages, the plague that broke out among the Janissaries and Hungarian preparations, the army was forced to withdraw. The definitive allegiance of Moldavia could be secured only in the following years and with the taking of Kili (Chilia) and Akkirman (Cetatea Albă) in 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Conquest of Akçahisar (Kruja) and completion of Albania", "559a79b4"], "d": ["Ten years after Skanderbeg's death, with the seizure of Akçahisar, Drivasto, Lezhë and Jabyak in 1478, the conquest of Albania was largely completed. The fall of Kruja Castle, which had resisted the Ottoman armies for years and was the symbol of Skanderbeg's resistance, meant the end of the Venetian-Albanian alliance in the region. Shkodër, the remaining place, was to be left to the Ottomans by the Treaty of Istanbul to be signed the following year.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Annexation of the Taman Peninsula", "4ef917b8"], "d": ["After the taking of Kefe and Kerch in 1475, the fleet that Mehmed the Conqueror sent to the Caucasian coasts seized, together with Anapa and Kopa, the Genoese Matrega (Tamatarkhan) on the Taman Peninsula. Both banks of the strait were thus brought under control, and the entrance to the Sea of Azov became entirely controlled. Taman, as the gate opening to the North Caucasus, was attached to the sancak of Kefe.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["The entry of Samos under Ottoman administration (Mehmed the Conqueror)", "c877bc14"], "d": ["Mehmed the Conqueror conquered Samos, had a fortress built and reorganised the survey; the fortress was demolished in 1483 by Bayezid II for political reasons.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Failure of the siege of Rhodes", "35a85c28"], "d": ["By order of Mehmed the Conqueror, the fleet of 160 vessels under the command of Mesih Pasha besieged Rhodes in the spring of 885 (1480), and the island remained under blockade for three months. The Knights of Saint John, led by the grand master Pierre d'Aubusson, resisted fiercely despite heavy losses; when the last great assault, made on 20 Jumada al-Awwal 885, was also repulsed, the fleet withdrew on 3 August. After this failure the city's walls were renewed from the foundations and made the strongest fortification in Europe, and the island could be taken only in 1522 by Süleyman the Lawgiver.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikaria (Ikaria) entered the administration of the Knights of Saint John of Rhodes", "5cbc2669"], "d": ["Nikaria, between Samos and Chios, was under the administration of the Knights of Saint John of Rhodes from 1481 to 1521.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Battle of Yenişehir — defeat of Prince Cem", "c35abee2"], "d": ["The two brothers, who moved for the throne after the Conqueror's death, faced each other on the plain of Yenişehir, and Prince Cem suffered a decisive defeat. The prince, who ruled in Bursa for eighteen days and had the khutba read in his name, was forced after the defeat to take refuge first in Konya and then in Mamluk territory. Yenişehir began the longest-lasting dynastic crisis of Ottoman history: for fourteen years the Cem question was to paralyse Ottoman foreign policy vis-à-vis Europe.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Annexation of Herzegovina", "bf247891"], "d": ["After the conquest of Bosnia in 1463, the lands of the Duchy of Herzegovina, which had remained standing, passed stage by stage to Ottoman administration: Trebinje and Mostar were taken in 1466, the sancak of Herzegovina was organized in 1470, and the last lands of the duchy on the Adriatic coast, together with Herseknovi (Herceg Novi), were conquered in early 1482 and joined to the sancak. The mountainous region behind the Adriatic thus became wholly Ottoman, and Bosnia and Herzegovina became a single administrative geography. The son of the last duke, who entered the Ottoman court, was Hersekzade Ahmed Pasha, who would later rise to the grand vizierate.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["The relinquishing of Zakynthos to Venice in return for an annual tribute", "268a691a"], "d": ["Zakynthos, one of the Ionian islands taken from the Tocco family at the end of Mehmed the Conqueror's reign, was left to Venice by the new sultan, who was occupied with the question of Prince Cem and was seeking tranquillity in the West. The island was transferred to a Venetian administration that recognised Ottoman sovereignty and paid an annual tribute of five hundred ducats. Thus in the Ionian Sea direct Ottoman administration remained only in Santa Maura.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Prince Cem's taking refuge in Rhodes", "2228d6da"], "d": ["Prince Cem, whose attempt to besiege Konya also came to nothing, fled from Anatolia with some thirty men and reached Rhodes, where he was received with ceremony by the Knights of Saint John. But the hospitality soon turned into captivity; the prince was handed over first to France and then to the papacy and became a trump card in the hands of European politics. Bayezid II was obliged to make annual payments in return for his brother's detention, and Ottoman military moves toward the West were suspended until Cem's death.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Beginning of the Ottoman-Mamluk War (Çukurova front)", "3fe3f0c7"], "d": ["The contest for influence over the Dulkadirids and the enmity left by Prince Cem's taking refuge in Mamluk lands began in 1485 a war between the two great Sunni powers that would last six years. In the clashes in Çukurova around Adana and Tarsus the parties could not gain the upper hand over one another; the Ottoman armies took several heavy blows. This war is the first phase of the break in Ottoman-Mamluk relations and the opening of the process that was to conclude thirty years later with Selim the Grim's campaigns of Marj Dabiq and Ridaniya.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Ottoman-Mamluk peace — Tunisian mediation", "60dd6719"], "d": ["In the Ottoman-Mamluk war that began in 1485 the parties could not win a decisive victory; through the mediation of the Hafsid ruler of Tunis, Uthman, an agreement was reached in 1491. The treaty returned the frontiers largely to their prewar state, and the reckoning between the two Islamic states was postponed for a generation. The wearing struggle of six years was among the principal reasons for Bayezid II's cautious foreign policy and for his emphasis on internal arrangements rather than turning eastward.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Admission to the Ottoman lands of the Sephardic Jews expelled from Spain", "5c2b5c24"], "d": ["After the fall of Granada, some of the Jews fleeing the persecution of the Inquisition in Spain took refuge in Ottoman lands and were settled in various cities. Under Ottoman rule these Sephardic communities gained a freedom they had not known until then: to settle where they wished, to practise their faith, to open educational institutions and to build new synagogues. This migration, which transformed the economic life of Thessalonica and Istanbul with the printing, medical and financial knowledge they brought with them, became the most discussed example in Europe of the Ottoman order of tolerance.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Death of Prince Cem — end of the fourteen-year hostage", "f6588b70"], "d": ["Prince Cem, handed over from the papacy to King Charles VIII of France, died at the place called Castel Capuana after setting out from Rome on 27 January 1495; the sources record that he may have been poisoned by papal circles. The death of the prince, who for fourteen years was held in the hands of the European states as a card of threat against the Ottomans, at last freed Bayezid II's hand. Indeed, the sultan thereafter declared war on Venice and led his fleet to its first great victory.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Naval Victory of Sapienza (Zonchio) — first great naval success in the Mediterranean", "9754aaef"], "d": ["Bayezid II, who found his hands free with the end of the Cem question, declared war on Venice in 1499; the Ottoman fleet defeated the Venetian fleet off Sapienza (Zonchio) and won its first great naval victory in the Mediterranean. With this victory the navy announced that it could now stand against Venice at sea.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["The loss of Cephalonia and Ithaca", "60f0f687"], "d": ["Shaken by the capture of Modon and Koron, Venice united with Spain and went on the counteroffensive, besieging Cephalonia, which had been in Ottoman hands since 1479. After forty-seven days of resistance the fortress fell, and the island, together with Ithaca, passed to Venice and did not return to Ottoman administration for three hundred years. This loss created a balance in which what was gained in the Morea was given back in the Ionian.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Fall of the Golden Horde Khanate and the rise of Crimea", "0d1dc515"], "d": ["Its last ruler, Sheikh Ahmed Khan (1481-1502), could not save his country from the crisis into which it had fallen, and the Golden Horde Khanate passed into history in 1502 through the coup of the Crimean khan Mengli Giray. As a result of struggles for the throne and fragmentation, the khanates of Crimea, Kazan, Nogai, Astrakhan and Sibir emerged on the former Golden Horde lands. This triumph of Crimea, under Ottoman protection, made Ottoman influence north of the Black Sea unquestionable, while the vacuum that arose in the region would be filled by Moscow in the following century.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["End of the Ottoman-Venetian War and peace", "125b1526"], "d": ["The war that began in 1499 and shook Venice with the losses of Sapienza, Lepanto (İnebahtı), Modon and Coron ended in peace in 1502. Venice, having lost its most important bases in the Morea, was forced to recognize Ottoman superiority in return for retaining its commercial privileges in the eastern Mediterranean. The reign of Bayezid II, regarded as cautious, had with this war raised the Ottomans for the first time to the position of a serious naval power in the Mediterranean.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Şahkulu Rebellion — Kızılbaş uprising extending from the Teke region to Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, who revealed his rebellion in 1510 under the influence of Safavid propaganda in Anatolia, had stormed the bazaar of Antalya in March 1511 and in April defeated Ottoman forces in and around Kütahya. In the last clash he engaged in near Sivas with the grand vizier Hadım Ali Pasha, both sides suffered heavy losses; both the grand vizier and the rebel leader lost their lives. This uprising, which shook the state's authority in Anatolia, laid bare the vacuum of power in the last years of Bayezid II and became the strongest justification for Prince Selim's march on the throne.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdication of Bayezid II and accession of Selim the Grim", "c4cfab69"], "d": ["Under pressure from Prince Selim, who had the support of the Janissaries in the struggle for the throne with his brothers, Bayezid II abdicated on 24 April 1512, and Selim I acceded to the throne the same day as the ninth Ottoman ruler. The aged sultan, on his way to Dimetoka, where he was born, died on the road in the village of Abalar near Çorlu on 25 Rabi al-Awwal 918 (10 June 1512). A cautious and inward-looking reign of thirty-one years was replaced by the era of the Grim, which would double the frontiers of the empire in eight years.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["The conquest of the fortress of Sinj", "83271ea5"], "d": ["Ottoman raiding forces on the Bosnian frontier took the fortress of Sinj, extending into the interior of Dalmatia, from the Kingdom of Hungary. This was an early link in the Dalmatian frontier line, which would expand nine years later with Gazi Husrev Bey's conquest of Knin and its surroundings; the fortress would be lost to Venice in 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["The Battle of Yenişehir and the Elimination of Prince Ahmed", "e2ed15dd"], "d": ["Selim the Grim defeated his elder brother Prince Ahmed, the strongest rival for the throne, on the plain of Yenişehir near Bursa, and removed him by taking him prisoner. Thus the fraternal strife that had continued since 1511 came to an end, and the internal division in Anatolia was over. Having secured his rear, Selim gained the freedom to turn to the Safavid question.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Selim the Grim's Entry into Tabriz", "dad2e227"], "d": ["Following the victory at Chaldiran, the Ottoman army entered the Safavid capital Tabriz, and the khutba was read in the city in the name of the sultan. Selim stayed there for a week and had some of the artists and scholars (ulema) of Tabriz transferred to Istanbul; this transfer was to have a profound influence on Ottoman court art. Although the city was abandoned as winter approached and because of the discontent of the Janissaries, Safavid superiority in the East had been broken. The places that passed to the Ottomans on the map on this day are not contiguous with one another, and this is correct: Tabriz is a nine-day army occupation; the plain of Erzincan surrendered without a fight during the campaign, while the fortress of Kemah in its midst held out as Safavid until 19 May 1515; Siirt was recovered from the Safavids by Halil Bey, the ruler (melik) of Hasankeyf, who had been freed from Shah Ismail's imprisonment in Tabriz and submitted to the Ottomans — Diyarbakır around it remained Safavid until 1515, and Hasankeyf until 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş and Bingöl (Çapakçur) passed from the Safavids to Ottoman administration", "b0a53b5a"], "d": ["With the taking of Eastern Anatolia from the Safavids after Chaldiran, Muş came under Ottoman administration in 921/1515; neighbouring Çapakçur (Bingöl) was added to the Ottomans in the same process.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Conquest of Kemah Castle from the Safavids", "73fd8671"], "d": ["Selim the Grim, who spent the winter at Amasya on his return from Chaldiran, assigned Bıyıklı Mehmed Pasha to the conquest of the fortified Kemah Castle, which held the crossing point of the Euphrates. At the end of the siege, in which the sultan himself took part, the fortress was taken from Safavid hands and the gate of eastern Anatolia was opened. This conquest is the first concrete step that turned the victory of Chaldiran into a lasting territorial gain.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["The Victory of Turnadağ — The Dulkadir Principality Became an Ottoman Vassal", "fd879145"], "d": ["Ottoman forces defeated Alâüddevle Bozkurt, the Dulkadir ruler who had taken an equivocal stance during the Chaldiran campaign, at the locality of Ördekli between Göksun and Andırın; Alâüddevle was killed in this battle. The principality was not annexed at this date: after Alâüddevle, Selim the Grim installed Şehsuvaroğlu Ali Bey at the head of the Dulkadir principality, and the realm centred on Maraş and Elbistan continued as a principality subject to the Ottomans. The buffer on the Mamluk frontier thus came under Ottoman control, and the way was opened for the Egyptian campaign two years later; annexation would take place only after the killing of Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Conquest of Amid (Diyarbekir) and founding of the beylerbeyilik of Diyarbekir", "a6867d5b"], "d": ["After İdris-i Bitlisi won over the Sunni Kurdish lords of the region to the Ottomans, the Safavid forces could not withstand a long siege, and the keys of Amid were handed over to Bıyıklı Mehmed Pasha. The city was made the centre of the newly founded beylerbeyilik of Diyarbekir. The administrative core of Upper Mesopotamia thus passed into Ottoman hands.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Conquest of Harput — opening of the Diyarbekir road", "564eb269"], "d": ["Hüsrev Pasha, the beylerbeyi of Karaman, who set out to relieve Diyarbekir, taken after Chaldiran, from the Safavid siege, took Harput Castle, whose surroundings Çerkez Hüseyin Bey had seized earlier, after a siege of three days. The road east of the Euphrates extending to Diyarbekir was thus secured.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Battle of Koçhisar (Kızıltepe) — defeat of Kara Han", "9ea9e843"], "d": ["The Ottoman army under the command of Bıyıklı Mehmed Pasha defeated the Safavid governor Kara Han, in a pitched battle lasting all day at the place called Koruk on the plain of Dede Garkın near Koçhisar; Kara Han's severed head was sent to the sultan's camp. Although the Ottoman forces then entered the city of Mardin, they stayed a few days and left; Mardin Castle, held by Safavid guards, could be taken over only a year later. This victory secured Selim's southern frontier and made it possible for him to turn to the Egyptian campaign. Other places joined on the same date: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Departure of Selim the Grim from Istanbul for the Egyptian campaign", "ac258b4b"], "d": ["Selim the Grim set out from Istanbul, apparently in preparation for a new eastern campaign against the Safavids, and turned south by way of Akşehir. The Mamluk Sultan Qansuh al-Ghawri's making contact with Shah Ismail and threatening the Ottomans' eastern flank was soon to cause the target to change. The campaign is the beginning of the great operation that would last two years and turn the Ottomans into a Middle Eastern empire.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Taking of Zabid: first entry of Ottoman seamen into the Red Sea", "38740e0c"], "d": ["The seamen of Ottoman origin Hüseyin Bey and Selman Reis, sent to the Red Sea at the request of the Mamluk Sultan Qansuh al-Ghawri in the face of Portuguese pressure in the Indian Ocean, took Zabid with their fleet. This operation, still conducted in Mamluk service, is the first actual presence of the Ottoman navy on the Red Sea-India line. A year later, when Egypt passed to the Ottomans, the same fleet would be tied directly to Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Official declaration of the Mamluks and Aleppo as the target of the campaign", "689e310d"], "d": ["Selim the Grim, when Qansuh al-Ghawri came to terms with the Safavids and drove his army to Aleppo, openly declared the Mamluk sultan and Aleppo to be the target of the campaign. The covert rivalry that had lasted for years between the two Sunni states thus turned into open war. This declaration began the four-week countdown to Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Failure of the siege of Aden: first Red Sea attempt against Portugal", "8ffd46f2"], "d": ["Selman Reis and Hüseyin Bey conducted a siege lasting eight days to take Aden, the gate of the Red Sea opening onto the Indian Ocean, but were forced to withdraw in the face of the city's strong fortifications. The failure to take Aden would for many years obstruct the southern strategy to be conducted against Portugal. This attempt is the Ottomans' first test in oceanic policy.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Attachment of the Ramazanid Beylik to the Ottomans", "cfaa3754"], "d": ["During the appointments (tevcih) made after the victory of Marj Dabiq, the Ramazanid Beylik, centred on Adana, was given to Mahmud Bey and taken under Ottoman sovereignty. The beylik, which left Mamluk vassalage, was not abolished but left to the family with the status of 'ocaklık'; the Ramazanids continued the administration of Çukurova as Ottoman sancak beyis. This privileged arrangement continued until 1608, the year in which Pir Mansur gave up the beylik. Other places joined on the same date: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa and Deir ez-Zor came under Ottoman dominion", "2088eb6a"], "d": ["Four days after Marj Dabiq, Selim the Grim entered Aleppo without meeting resistance, and the khutba in the city's mosques was read in his name. The fall of Aleppo, regarded as the commercial and administrative capital of Syria, so quickly shows that Mamluk authority in the region had collapsed. The taking of the city at once opened the road to Damascus and from there to Egypt. Other places joined on the same date: Antioch, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Meeting at the Gökmeydan in Aleppo with the Abbasid Caliph al-Mutawakkil III", "22979f42"], "d": ["The Abbasid caliph of Cairo, al-Mutawakkil III, who had fallen prisoner at Marj Dabiq together with the Mamluk army, was brought before the sultan at the Gökmeydan in Aleppo, and Selim the Grim showed him great respect. The caliphate of Cairo, a symbolic office in the shadow of the Mamluk sultans since 1261, passed in practice under Ottoman protection with this meeting. The caliph would later be taken to Istanbul with the sultan.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli of Syria and Hama came under Ottoman administration", "a1e19a79"], "d": ["After Aleppo and Hama, Tripoli of Syria on the Syrian coast also passed to Ottoman administration without resistance. The city, one of the busiest ports of the eastern Mediterranean, was Damascus's gate to the sea and the centre of the silk and sugar trade. With its taking, the coastal strip of Bilad al-Sham changed hands in its entirety.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damascus (Dimashq) came under Ottoman dominion", "2b844d91"], "d": ["Selim the Grim, whose way had been opened by the surrender of Hama and Homs after Aleppo, reached the front of Damascus on 27 September; he did not enter the city at once but pitched his tent outside at the place called Mastaba, and on the twelfth day after his arrival entered with a great ceremony. Remaining in Damascus for some time, he set up the administrative order of Syria and had the tomb of Muhyiddin Ibn al-Arabi built. All of Bilad al-Sham thus passed out of Mamluk administration. Other places joined on the same date: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tumanbay proclaimed Mamluk sultan in Cairo", "6020d90d"], "d": ["After Qansuh al-Ghawri, who died at Marj Dabiq, the Mamluk emirs raised Tumanbay, who was to be the last sultan of the state, to the throne. The new sultan of Circassian origin took over a state that had lost Syria, whose treasury was exhausted and which lacked firearms. Nevertheless, by establishing a line of defence before Cairo he would organize a last resistance against the Ottoman advance.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Battle of Gaza (Khan Yunus): defeat of Janbirdi al-Ghazali", "9f1eb8cb"], "d": ["Selim the Grim sent the grand vizier Hadım Sinan Pasha to Gaza with a vanguard of four thousand men. Janbirdi al-Ghazali, whom Tumanbay had appointed to the governorship of Damascus, tried to halt the Ottoman vanguard on the Gaza-Khan Yunus line but suffered a heavy defeat and fled to Egypt. With the dispersal of the last Mamluk buffer force in Palestine, the road to the Sinai desert was entirely opened.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["East of the Jordan: Amman came under Ottoman administration", "9db62667"], "d": ["As the Ottoman forces, preparing for the Egyptian campaign after the battle of Gaza, descended southward, Amman, east of the Jordan, also came under Ottoman administration. The coastal and inland cities of Palestine (Jaffa, Nablus, Sidon, Acre, Jerusalem) had already changed hands after Marj Dabiq in the autumn of 1516. These cities were administered for four centuries as sancaks of the province of Damascus.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Selim the Grim's arrival in Jerusalem", "66d7bfad"], "d": ["To Jerusalem, which had passed to Ottoman administration without resistance after Marj Dabiq, Selim the Grim came after the battle of Gaza with the dignitaries of the state and the army. The sultan visited the Dome of the Rock and the Aqsa Mosque and confirmed the holy status of the city. Jerusalem would remain under Ottoman administration from this date until December 1917, a full four centuries.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Selim the Grim's entry into Gaza and turn toward the Sinai desert", "2106bfc7"], "d": ["After the defeat of Janbirdi al-Ghazali at Khan Yunus (21 December 1516), Gaza was in the hands of the vanguard. The sultan entered Gaza on 2 January 1517 and met here with Sinan Pasha, at the head of the vanguard, and the army made its last preparations for the crossing to Egypt. Eight stages were to be marched in the waterless desert of Qatiya (Sinai) extending from Gaza to Salihiyya, with water carried by camels. This crossing is the most risky and logistically most difficult phase of the campaign.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Taking of Suez — gate opening to the Red Sea", "05f3324e"], "d": ["With the entry of the Ottoman troops into Cairo after the victory of Ridaniya, Suez at the northern end of the Red Sea also passed to Ottoman administration. This dockyard-port, from which the Mamluks had sent a fleet to the Indian Ocean, became the base of the southern policy to be conducted against Portugal. Suez is the northern mouth of the line along which, three centuries later, the canal would be opened.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["First entry of the Ottoman troops into Cairo", "0a3f4f4d"], "d": ["On the day after the victory of Ridaniya the Ottoman armies were permitted to enter Cairo, and on 24 January the troops settled in the city. This entry, however, did not mean full control of the city; Tumanbay had withdrawn to Upper Egypt, and Mamluk resistance had not yet been broken. The conquest of Cairo would be completed not in a single day but in a bloody process spread over weeks.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Tumanbay's raid on Cairo and three days of street fighting", "b83b6ce6"], "d": ["Tumanbay, who had withdrawn to Upper Egypt, suddenly entered Cairo on the night of 27-28 January with about seven thousand men, began resistance inside the city and left the Ottoman troops in an extremely difficult position. In fierce street clashes lasting three days, the Mamluks temporarily held most of the city. The resistance could be broken only when the Ottoman artillery and reinforcements came into play.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Janbirdi al-Ghazali's entry into Ottoman service", "a94ea459"], "d": ["Janbirdi al-Ghazali, the former Mamluk emir, who had withdrawn to Salihiyya after Ridaniya, applied to the sultan and begged for aman. Selim the Grim, thinking that he would be useful in establishing order in Egypt and Syria, accepted him into his service. This choice is the first great example of the Ottoman policy of incorporating the Mamluk cadres into the system rather than liquidating them.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Selim the Grim's ceremonial entry into Cairo and reading of the khutba", "6d98080c"], "d": ["After the suppression of the street fighting, the sultan entered Cairo on 15 February 1517 in a most splendid ceremony, and the khutba was read in his name in the mosques. The reading of the khutba in Cairo in the name of the Ottoman sultan is the proclamation that Mamluk dominion, which had lasted since 1250, had legally ended. This date is regarded as the symbolic moment of completion of the actual conquest of Egypt.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Capture of the last Mamluk sultan Tumanbay at Terrūja", "7058e6ad"], "d": ["Tumanbay, who hid in the Nile delta after leaving Cairo, was denounced by the Bedouin who had given him refuge and was seized in the Terrūja region. His capture eliminated the organized centre of Mamluk resistance. The last sultan would be held thereafter for fourteen days in Ottoman hands.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Execution of Tumanbay at Bab Zuwayla and the end of the Mamluk State", "ad9820be"], "d": ["Fourteen days after his capture, Tumanbay was hanged at Bab Zuwayla, the celebrated gate of Cairo; his body was later buried in the madrasa built by his uncle. The Mamluk State, which had ruled Egypt and Syria since 1250, thus officially passed into history. With the breaking of the resistance, cities of Upper Egypt (the Sa'id) such as Asyut and Aswan were also attached to Ottoman administration.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Portuguese fleet's attack on Jeddah and Selman Reis's defence", "52322cf5"], "d": ["A Portuguese fleet of some thirty galleys and galleons attacked Jeddah; Selman Reis directed the city's defence, prevented the enemy from landing and sank several Portuguese ships. This defence prevented the port of Mecca, and thus the pilgrimage road, from falling into the hands of a Christian state. A few months later Jeddah would be officially incorporated into Ottoman administration with the allegiance of the Hejaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Alexandria taken over with the fleet — completion of the conquest of Egypt", "386878fe"], "d": ["Exactly four months after Ridaniya and thirty-six days after Tumanbay's execution, Alexandria passed to Ottoman administration with the arrival at the port of the Ottoman fleet under Cafer Bey; delta ports such as Rosetta (Reşîd) and Damietta were also attached in the same process. That this great Mediterranean port of Egypt was taken over months after the fall of Cairo, and from the sea rather than by land, clearly shows that the conquest was completed not by a single battle but region by region. Alexandria would thereafter become the vital port linking Istanbul and Cairo. Other places joined on the same date: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Peaceful annexation of the Hejaz: allegiance of Abu Numayy, son of the Sharif of Mecca", "c13b98c7"], "d": ["Selim the Grim had first considered sending troops for the seizure of Mecca and its surroundings, but gave this up when the emir of Mecca, Sharif Barakat, announced his obedience. Barakat's twelve-year-old son Abu Numayy came to Cairo with his father's gifts and the keys of Mecca and was received in the sultan's presence. Thus the Hejaz was joined to the Ottomans not as an automatic consequence of Ridaniya, but five and a half months later and without a single shot, peacefully and by way of allegiance (bi'a). Other places joined on the same date: Taif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Acceptance of the title Khadim al-Haramayn and khutba in Medina", "63b32b59"], "d": ["After the second reception of the Meccan delegation, Selim the Grim officially took upon himself the protection of the Haramayn and began to use the title 'servant of the two noble sanctuaries' (hadim al-Haramayn al-sharifayn). Sharif Barakat put on the robe of honour (hil'at) sent to him and had the khutba read in the sultan's name; with the Medinan delegation's going to Istanbul, Barakat's emirate was confirmed by a diploma (berat). The sultan sent the people of the Haramayn two hundred thousand gold pieces and abundant provisions, beginning the tradition of the surre to be repeated every year. Other places joined on the same date: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis's entry into Ottoman service and the transfer of Red Sea policy", "771da99a"], "d": ["Selman Reis, who had defended Jeddah against the Portuguese, came to Cairo and appeared before Selim the Grim; although he was detained for a time, he was summoned to Istanbul in 1519 and undertook to prepare thirty galleys and several galleons against the Portuguese threat. This meeting is the beginning of the inheritance of Red Sea and Indian Ocean policy from the Mamluks and its attachment directly to Istanbul. The Ottomans were now a power that, besides being a Mediterranean state, also conducted oceanic policy.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Selim the Grim's departure from Cairo and Hayır Bey's beylerbeyilik", "8cd4fb23"], "d": ["Selim the Grim, who had stayed in Egypt for about eight months and established the administrative, financial and military order, left Cairo; Hayır Bey, the former governor of Aleppo, who by withdrawing the left wing at Marj Dabiq had hastened the Mamluk rout, began the administration from the Citadel (Qal'at al-Jabal) as the first Ottoman beylerbeyi of Egypt. The choice of a governor of Mamluk origin was a deliberate policy of transition that ensured the new administration did not appear foreign to the local people. On his return journey the sultan took with him to Istanbul the last Abbasid caliph, al-Mutawakkil III, and the eminent artisans and scholars of Egypt.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["End of the Abbasid caliphate of Cairo — the 'ceremony of transfer' tradition", "1d357640"], "d": ["When Selim the Grim seized Egypt, he brought with him to Istanbul the last caliph, al-Mutawakkil III 'Ala Allah, who had fallen prisoner at Marj Dabiq; the Abbasid caliphate of Cairo, which had continued without authority in the shadow of the Mamluk sultans since 1261, thus came to an end. By contrast, the famous tradition that the caliphate was transferred to the Grim in an official ceremony in Hagia Sophia appears for the first time at the end of the eighteenth century in d'Ohsson's work and is found in none of the sources of the Grim's period. The TDV İslâm Ansiklopedisi regards the tradition as fabricated, since there is no original source documenting the ceremony; but it also notes that no such ceremony of transfer was needed under the shari'a for the caliphate to be transferred.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum Joined the Ottoman Administration — Safavid Influence in Eastern Anatolia Was Broken", "78d1be02"], "d": ["Although Ottoman influence in the region grew after the victory at Çaldıran (1514), the full seizure of Erzurum was delayed until Iranian influence was broken; the city came under Ottoman administration only in 1518-19, after the Egyptian campaign. Erzurum had come under Safavid rule in 1502, when Shah Ismail ended the Akkoyunlu Principality; that sixteen-year period was thus closed. In 1534, during the Campaign of the Two Iraqs, the Erzurum beylerbeylik will be established. Between 1518 and 1519, Aşkale, together with the Erzurum region, came under Ottoman administration (day unconfirmed).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["The Beginning of the Celali Rebellions: The Uprising of Şeyh Celâl of Bozok", "99bd8a99"], "d": ["In the Bozok region a man named Şeyh Celâl proclaimed himself the Mahdi and rose in revolt around Tokat; although the rebellion was suppressed, his name became for a century the name of all brigand and uprising movements in Anatolia. Combined with the disintegration of the timar system and population pressure at the end of the sixteenth century, Celalism turned into the longest-lasting internal security problem of the empire. The uprisings led to mass migrations in Anatolia known as the 'great flight'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["The Attachment of Algiers to the Ottoman State", "b8eba4c1"], "d": ["Hayreddin Reis, who was resisting Spanish pressure in North Africa, appealed to Istanbul in order to hold out, offered Algiers to the sultan, and the khutba was read in the name of Selim the Grim. Thus Algiers was officially added to Ottoman territory, and soldiers and cannon were sent to Hayreddin with the title of beylerbeyi. This attachment laid the foundation of the Ottoman naval dominance in the Western Mediterranean that would last for centuries. Other places that joined on the same date: Constantine, Cherchell (Şerşel), Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["The Death of Selim the Grim at Çorlu", "9fe83744"], "d": ["Selim I, who in eight years had more than doubled the territory of the state, set out from Istanbul on 18 July 1520 for a new campaign; because of a large tumour that appeared on his back he could not go beyond Çorlu. Despite the physicians' intervention his illness worsened, and after a hopeless treatment lasting two months he died there on 8-9 Shawwal 926 (21-22 September 1520). He had stopped Iran with Chaldiran, Marj Dabiq and Ridaniya, had eliminated the Mamluk state, and had brought the caliphate and the guardianship of the Two Holy Sanctuaries (Haramayn) to the Ottomans. He left behind a single male child: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["The entry of the island of Nikaria (Ikaria) under Ottoman administration", "6afa972b"], "d": ["Nikaria, between Samos and Chios, was under the administration of the Knights of Saint John of Rhodes from 1481 to 1521; the first Ottoman period on the island began in 1522 and lasted until 1822. In this period the kaymakam was responsible for the collection and payment of taxes; as in the other Aegean islands, the local council of elders (demogerontia) also continued to exist and at times came into conflict with the Ottoman administration.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["The annexation of the land of Dulkadir — the province of Dulkadir centred on Maraş", "595c3c30"], "d": ["The land of Dulkadir, which had continued after the debacle of Turna Dağı in 1515 as a principality subject to the Ottomans, was incorporated directly into Ottoman territory after Şehsuvaroğlu Ali Bey was massacred with his children at Artukova, and was made a province centred on Maraş. The Bozok region of the principality was attached to Ottoman administration as a separate sancak. Thus the roughly two-century Dulkadirid period of Maraş, Elbistan, Göksun, Gürün, Zamantı and Darende was closed; the buffer principality on the Mamluk frontier disappeared entirely.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["The conquest of Knin", "a46d3117"], "d": ["Through the raids in the years 927-928 (1521-1522) of Gazi Husrev Bey, the sancak bey of Bosnia, a series of Venetian fortresses, foremost among them Knin, Skradin and Ostrovica, passed to Ottoman administration; the frontier was pushed beyond the second mountain range. This chain of conquests laid the foundation of the sancak of Dalmatia, which would be completed fifteen years later with the capture of Klis.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["The withdrawal of the Knights: the handing over of Bodrum, Kos and the Dodecanese", "ea01666e"], "d": ["Under the terms of the surrender of Rhodes, the Knights of Saint John evacuated not only the island's centre but all the positions they had held for two hundred years. The fortress of Bodrum (Saint Peter) on the Anatolian coast, together with the islands of Kos, Kalymnos and Leros, thus passed to Ottoman administration without fighting. With this transfer, completed two weeks after the fall of Rhodes, the Latin presence in the southeastern corner of the Aegean came to a complete end.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["The Rebellion of Hain Ahmed Pasha in Egypt", "b18bb805"], "d": ["Ahmed Pasha, who had been sent to the governorship of Egypt while he was expecting the grand vizierate, declared his independence in Cairo by proclaiming himself 'al-Malik al-Mansur Sultan Ahmed'. The rebellion was suppressed in a short time and the pasha was killed, but the event showed the fragility of central control in the richest province of the empire. Thereupon Ibrahim Pasha went to Egypt and had the famous Egyptian Kanunname, which reorganised the administration of the province, prepared.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["The annexation of northern Bosnia: Jajce and Banja Luka", "8ec86cfa"], "d": ["When the Hungarian defensive line collapsed after Mohács, Gazi Husrev Bey, the sancak bey of Bosnia, marched into the Vrbas valley and took the last Bosnian fortresses remaining in the hands of the Hungarian kingdom. With the fall of Jajce and Banja Luka, the province of Bosnia reached the Sava River in the north, and the Croatian front was born. Banja Luka soon became the province's second centre.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["The Capture of Buda and Its Handing Over to Zápolya", "fba4f89b"], "d": ["On the road to the Vienna campaign the Ottoman army besieged and retook Buda, which had fallen into Ferdinand's hands, and delivered the city to János Szapolyai, the Hungarian king under Ottoman protection. Thus a model of a buffer vassal kingdom was established over Hungary in the Habsburg-Ottoman rivalry. This arrangement would last until 1541; after Zápolya's death Buda would be made a direct Ottoman province.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Süleyman the Lawgiver Set Out on the German Campaign — A Challenge to Charles V", "7c3d7055"], "d": ["After the inconclusive outcome of the siege of Vienna and Ferdinand's renewed siege of Buda, the sultan set out from Istanbul, this time to draw the emperor Charles V himself into a pitched battle. In August the army would be delayed by the resistance of the small fortress of Güns, and since the emperor did not come out to fight, the campaign would remain limited to raids. The campaign prepared the ground for the first peace made with the Habsburgs the following year.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["The German Campaign and the Siege of Güns (Kőszeg)", "8aec937a"], "d": ["Süleyman the Lawgiver marched with his army against Austria in order to force Charles V into a pitched battle; the small fortress of Güns resisted for twenty-five days and delayed the army's advance. Since the emperor did not come out to fight, the raiders (akıncı) struck the environs of Vienna, and the army turned back as the season advanced. The campaign brought no territorial gain, but by bringing the Habsburgs to the table it prepared the ground for the following year's peace.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["The Treaty of Istanbul — The First Peace with the Habsburgs", "b085767a"], "d": ["The sultan, who received Ferdinand's envoy Cornelius, consented to a truce, and the first official peace text between the Ottomans and Austria came into being. By the treaty Ferdinand agreed to pay an annual tribute for the Hungarian lands he held, and the archduke of Austria was regarded in protocol as equal to the grand vizier. This unequal status was the clear expression of the Ottoman diplomacy's claim to superiority in the sixteenth century.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["The Taking of Kars and the Opening of the Northeastern Frontier", "742e3101"], "d": ["As the vanguard column of the Campaign of the Two Iraqs turned eastward from Erzurum, the fortress of Kars, which was held by the Georgian atabegate and had lain in ruins since Timur, was taken over without encountering resistance. Since the city held the pass between the arc of the Aras and Çıldır, it was regarded as the key to the northern gate opening onto Iran. This gain became the first link of the beylerbeyilik of Kars, to be established thirty years later, and of the Caucasus line.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["The First Entry into Tabriz — The Opening of the Campaign of the Two Iraqs", "cf7ed4e3"], "d": ["Ibrahim Pasha, who moved ahead in the capacity of serdar-ı ekrem, entered the Safavid capital Tabriz without encountering resistance, as Shah Tahmasb avoided a pitched battle and withdrew into the interior. Süleyman the Lawgiver also reached the city in September; however, because of the onset of winter and the excessive lengthening of the supply line, the army turned in the direction of Baghdad, and Tabriz could not be held for long. The city, taken for the second time after Chaldiran, became the place where the Ottomans learned that in the east taking is easy and holding is hard.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Barbarossa's Conquest of Tunis", "d8754216"], "d": ["The grand admiral (kaptan-ı deryâ) Barbarossa Hayreddin Pasha, after striking the coasts of Italy with his fleet, turned to Tunis, put the Hafsid ruler Mulay Hasan to flight and entered the city. The capture of Tunis, with its position controlling the Strait of Sicily, turned the balance of power in the Western Mediterranean at once in favour of the Ottomans. However, this dominance would not last long, and Charles V would respond the following year with a great fleet.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["The Loss of Tunis to Charles V", "a691f0f8"], "d": ["Charles V, in a great expedition supported by the Genoese and Papal fleets, took Tunis after capturing La Goulette (Halkulvâd) and restored Mulay Hasan to the throne under Spanish protection. A Spanish garrison was placed in the city, and the Ottoman advance in the Central Mediterranean was temporarily halted. The definitive conquest of Tunis would be possible only forty years later, in 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Gazi Husrev Bey's campaign along the Sava: Bosanski Brod and Jasenovac", "3740ec83"], "d": ["After Jajce and Banja Luka were taken in 1528, the fortresses along the Sava River remained for some time longer in the Croatian-Slavonian frontier tied to the Habsburg crown. Gazi Husrev Bey, who in 1536 became sancak bey of Bosnia for the third time, took Požega and its surroundings that same year and also added the fortresses of Brod and Jasenovac on the Sava bank to Ottoman administration. Thus the northern frontier of Bosnia reached the Sava; the region was completed two years later with the capture of Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["The Execution of Makbul Ibrahim Pasha", "348aa7b8"], "d": ["Ibrahim Pasha, who had served as grand vizier for thirteen years and was Süleyman the Lawgiver's closest friend and the de facto second man of the state, was strangled and executed, without any reason being given, in the palace to which he had been invited for the iftar. His attitude during the Iraqi campaign, his use of the title 'serasker sultan', and the balances within the palace are regarded as having played a part in his death. The execution is a turning point showing that grand viziers had no absolute security in the Ottoman central administration.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["The Conquest of the Fortress of Klis and the Founding of the Sancak of Dalmatia", "6ffd4ebf"], "d": ["Murad Bey, the kethüdâ of Gazi Hüsrev Bey and a convert of Croatian origin, took the strategic fortress of Klis, just north of Split, from Venice. Immediately after the conquest Klis was made the centre of a new sancak and kaza encompassing its surroundings; the borders of this sancak largely drew the outline of Ottoman Croatia. This conquest, which came fifteen years after Knin, completed the administrative skeleton of the Dalmatian interior.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["The Siege of Corfu and the War with Venice", "11af95bd"], "d": ["After the Apulia (Pulya) campaign the Ottoman army landed troops on Corfu and besieged the island's strong Venetian fortress. Because of the fortress's steep structure, heavy losses and the conditions of the season, the blockade was lifted and the army withdrew on 6 September. Although the siege was inconclusive, the war opened with Venice ended with the annexation of many islands in the Aegean and the Adriatic to the Ottomans and with the victory of Preveza the following year.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Barbarossa's Aegean campaign: the taking of the islands directly administered by Venice", "1b32ed96"], "d": ["The fleet, returning from the siege of Corfu, took advantage of the declaration of war on Venice to take over one by one the islands in the Aegean that were tied not to the duchy but directly to Venice. Aegina was taken after fierce resistance, Astypalaia, held by the Querini family, together with Karpathos and Kasos surrendered, and Patmos, under monastic administration, also accepted Ottoman protection. The Duchy of Naxos, however, was left in place, bound to the payment of tribute; its annexation would wait until 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Barbarossa's North Aegean campaign: the taking of Skyros and the Northern Sporades", "20ab688e"], "d": ["On the way to Preveza, the fleet took over one by one the North Aegean islands that had taken refuge with Venice after the conquest of Constantinople. Skyros, north of Negroponte, and Skiathos, Skopelos and Alonnisos, which hold the mouth of the Gulf of Thessaloniki, thus came under Ottoman administration. These islands closed the last North Aegean gap, which had remained in Venetian hands for sixty-eight more years even though Negroponte had been taken in 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["The Capture of Aden and the Annexation of the Yemeni Coast", "e7d46d8f"], "d": ["The fleet that left Suez for the Indian campaign turned first to the Yemeni coast, because the ocean could not be entered without securing the Red Sea. Hadım Süleyman Pasha entered the port of Aden on 3 August 1538; the Tahirid ruler Amir b. Dawud, who inclined toward the Portuguese, was brought to the captain's gate and executed, and a guard of 500 men was left in the city. During the same campaign Mocha and the islands of Kamaran and Farasan, which command the strait, were also taken over, and the foundation of the beylerbeyilik of Yemen was laid. Thus the Ottoman State for the first time came to possess the whole of the northern shore of Bab al-Mandab; Sana'a and the inner regions would have to wait nine more years.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["The Moldavian Campaign and the Annexation of the Bucak (Bender) Region", "90a88a56"], "d": ["In the campaign launched against Petru Rareş, the voivode of Moldavia, who did not fulfil his obligations to the Ottomans, Suceava was captured and the city of Iași was plundered by the Crimean Khan Sahib Giray. The sultan installed Stephen the Locust (Çekirge Stefan) as voivode and added the region of Bucak (Southern Bessarabia) together with Bender directly to Ottoman territory. This annexation became one of the links that turned the northwestern shores of the Black Sea into an Ottoman inland sea. Moldavia was already a voivodeship subject to the Ottomans; this campaign did not take land from a foreign state, but merely took the internal administration of Bender and Bucak from the voivode and attached it directly to the sultan; the rest of the voivodeship continued its vassal status. The same structure would be repeated at Kilia and Akkerman in 1484 and at Hotin in 1713: border fortresses direct, interior lands vassal.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["The Taking Over of Anabolu (Nauplion) by Treaty", "104d0937"], "d": ["The Venetian war, which lasted three years after Preveza, ended with the republic's consenting to give up its last two fortresses in the Morea. Anabolu and Benefşe, which could not be taken by siege, were handed over to the Ottomans at the table, in addition to a war indemnity of three hundred thousand ducats. The Morea peninsula thus became unified, with not a single Venetian footprint remaining.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["The entry of Szeged under Ottoman administration and the formation of the liva of Szeged", "019aa000"], "d": ["After Ottoman administration was fully established in Buda in 1541, the notables of Szeged adopted the sovereignty of Ferdinand I and prepared for armed defence. Küçük Bâlî Pasha, the beylerbeyi of Buda, in early 1543 summoned the city's leaders to him and had them executed on grounds of treason, then sent a force to seize the city. At this time the liva of Szeged was formed, and Derviş Bey, the son of Bâlî Pasha, was appointed as the first sancak bey; the liva at first extended between the Danube and the Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["The Conquest of Valpo, Šikloš and Pécs", "2ca030a3"], "d": ["The first objective of the Hungarian campaign launched two years after the annexation of Buda was to secure the southern flank of the new province between the Drava and the Danube. After the fortresses of Valpo and Šikloš were taken, Pécs, the centre of Baranya, surrendered. The city would become the most populous and most developed centre of Ottoman Hungary, and the historian İbrahim Peçuylu would take his name from here.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["The Conquest of Esztergom and Székesfehérvár", "efca9e05"], "d": ["In the Hungarian campaign that Süleyman the Lawgiver led in person, after a siege of two and a half weeks, Esztergom, the religious centre of the Hungarian Kingdom and an archiepiscopal city, came under Ottoman rule. Then Székesfehérvár, the coronation city of the Hungarian kings, was also taken, and the defensive belt of the province of Buda was completed. Esztergom would remain in Ottoman hands until 1595 as the key fortress of the Danube line.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["The Northern and Western Defence Belt of Buda: Vác, Hatvan and Simontornya", "733ee5ce"], "d": ["After Esztergom and Székesfehérvár were taken, the beylerbeyi of Buda, without a campaign of the sultan, set out to complete the ring of fortresses surrounding the capital. Vác at the Danube bend, Hatvan, the gate of the Alföld, and Simontornya on the Sió line were taken over one by one. The gains of this quiet year turned Buda from a frontier city into a provincial centre that would endure for a hundred and forty years.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["The annexation of Basra and the opening to the Persian Gulf", "02f87c11"], "d": ["During the conquest of Baghdad (1534), the ruler of Basra, Râşid b. Megāmis, had declared his obedience to Süleyman the Lawgiver, and in 1538 he sent the keys of the city. His successor, Sheikh Yahyâ, took a hostile stance toward the Ottomans; the beylerbeyi of Baghdad, Ayas Pasha, marched by land, and the sancak bey of Mosul marched along the Euphrates with 120 ships. Ayas Pasha entered Basra on 26 December 1545, and the city became the seat of a beylerbeylik. This port at the mouth of the Shatt al-Arab was the gate through which the Ottomans opened onto the Gulf, which Portugal controlled from Hormuz; with the Treaty of Amasya in 1555, Iran too recognised this situation.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["The conquest of Sana'a and the interior of Yemen", "d31ded85"], "d": ["After Taiz, Sana'a was also taken, and the entire country was attached to the beylerbeylik. However, because of the rugged geography and the sectarian difference, this domination was never comfortable; Yemen became a front that continually swallowed troops for the Ottomans.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["The conquest of Taiz", "d4509df9"], "d": ["In Yemen, where the Ottomans had previously been content with the coastal strip nine years earlier, the Zaydi imams were growing steadily stronger in the mountainous interior; in response, the forces of Özdemir Pasha climbed onto the plateau and seized Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["The Treaty of Istanbul — A Five-Year Peace with the Habsburgs", "41f81773"], "d": ["A peace of five years' duration was signed between the Ottomans and the Habsburgs; Ferdinand agreed to pay 30,000 ducats annually for the Hungarian lands he held. The treaty legally registered the de facto situation of Hungary being divided into three. The securing of the western front in this way gave Süleyman the Lawgiver the opportunity to organise new campaigns against Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["The Second Iranian Campaign and the retaking of Tabriz", "e82365df"], "d": ["In the campaign launched at the instigation of Elqas Mirza, the brother of Shah Tahmasb who had rebelled against him and taken refuge in Istanbul, the army entered Tabriz for the second time. Because the Safavids again refused to engage in a pitched battle and withdrew, burning the land, the army could remain in the city for only a few weeks. The campaign made it certain that Tabriz could not be held and directed Ottoman strategy toward establishing a lasting border line, that is, toward fortifying Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["The conquest of Van and the fixing of the eastern frontier", "fc8f930b"], "d": ["The fortress of Van, besieged on the return from Tabriz, was, with its position rising on a rock on the eastern shore of the lake, the undisputed key to the region, and it surrendered after a short siege. The city was immediately made the seat of a beylerbeylik; the sancaks of Erciş, Adilcevaz and Hakkâri were attached to it. Unlike Tabriz, Van was retained and remained for four hundred years the Ottomans' most advanced permanent position in the east.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["The annexation of al-Hasa and al-Qatif — the Arabian coast of the Gulf", "f6701e60"], "d": ["After the capture of Basra, Qatif, which had become Portugal's forward outpost on the western shore of the Gulf, was taken, and together with the oases of al-Hasa in the interior a new beylerbeylik was established. It was the point of departure for operations against Bahrain and Hormuz. The Ottoman State thus came to have a say simultaneously on both the Red Sea and the Persian Gulf coasts of the Arabian peninsula.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["The loss of Shahrizor — Sührâb, the lord of Erdelân, inclined toward the Safavids", "5600efc9"], "d": ["The Shahrizor region, which had recognised Ottoman administration during the Campaign of the Two Iraqs (1535), was governed by Bige Bey, the emir of Erdelân, who resided in the fortress of Zalm. Following the death of Bige Bey in 1550, his brother Sührâb, who seized the fortress of Zalm and took control of the principality, turned toward the Safavids and broke away from obedience to the Ottomans; the Shahrizor region thus passed out of Ottoman influence. The region was regained only during the Nakhchivan campaign, in 1554, with the siege and capture of the fortress of Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["The taking of Ardahan and the Çıldır basin", "14c9eb76"], "d": ["During the ongoing war with the Safavids, the beylerbeyi of Erzurum turned toward the lands of the Georgian atabegs along the arc of the Kura and brought Ardahan and the Çıldır area under Ottoman administration. The Kars-Ardahan line was thus consolidated, and the highlands opening onto Georgia in the northeast came under control. The definitive administrative arrangement of the region would be completed by the Çıldır province, to be established twenty-seven years later.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pasha crossed the Danube — the start of the Transylvanian war", "38fde931"], "d": ["Following the disturbances caused by the monk Martinuzzi, guardian of the king of Transylvania, the young János Zsigmond, and Transylvania's surrender of the Banat fortresses to Ferdinand, a new campaign was deemed necessary; command was given to the beylerbeyi of Rumelia, Sokollu Mehmed Pasha. Despite Martinuzzi's delaying efforts, the army crossed the Danube and took Becse, Becskerek, Csanád and Lippa; however, the siege of Timișoara was lifted on 16 November because of the cold. A new Ottoman-Habsburg war had thus been opened in Hungary.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["The city of Lipova (Lippa) fell into the hands of Castaldo's Austrian army — the fortress surrendered on 5 December", "a0e1ff0d"], "d": ["Lipova, which Sokollu Mehmed Pasha had taken in October 1551, was besieged by General Castaldo's army on 4 November; two days later the city fell into the hands of the Austrians. Ulama Pasha defended the fortress for nine more days with a garrison of 5,000 and withdrew by agreement on 5 December 1551. Until the fall of Timișoara in 1552, Lipova remained in Habsburg hands.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["The Holding of the Southern Banat Palankas by Forces Sent from Temesvár — Versec, Haram, Keve", "edca0921"], "d": ["After Temesvár's surrender to the Ottoman army, units detached from the besieging army turned to the small palankas of the Banat; according to Bánlaky's account, the palankas of Versec, Facset, Mehádia, Csákóvár, Haramvár and Keve were held by these forces. Thus Haram on the Danube bank also fell into Ottoman hands.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["The conquest of Szolnok and the failure of the siege of Eger", "a7156e8f"], "d": ["After the capture of Timișoara, the two Ottoman armies, having united, took Szolnok on the Tisza almost without fighting, as the mercenary guards abandoned the fortress. The fortress of Eger, besieged next, however, could not be taken in the face of the thirty-eight-day resistance of the two-thousand-man garrison under István Dobó, and the army withdrew as winter set in. That in the same campaign one fortress fell easily while the other held out was the first clear sign that the frontier in Hungary no longer advanced of its own accord in the Ottomans' favour.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["The Ottoman-French Alliance — The French Fleet Placed under Ottoman Command", "a8e01b22"], "d": ["By the treaty dated 1 February 1553 the French fleet was placed under the command of the Ottoman fleet; joint operations against Spain in the Western Mediterranean were envisaged. Following the treaty, Turgut Reis set out on 15 June 1553 with forty-five galleys to support France. This was the first official alliance treaty that carried the commercial basis of the 1536 capitulations over into a military cooperation.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["The Execution of Prince Mustafa at Konya Ereğlisi", "dec36858"], "d": ["Prince Mustafa, who entered his father's tent to join the army assembled for the Nakhchivan campaign, encountered the executioners just as he was about to appear before the sultan and was strangled to death. The killing of the heir apparent, who was greatly loved within the army, aroused deep anger among the Janissaries, and Rüstem Pasha was removed from the grand vizierate. The event passed into literature and popular memory as one of the most contested breaks in Ottoman princely politics.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["The shifting of the Ibrim and Nubian frontier to the south", "c57d5d77"], "d": ["The southern frontier of the beylerbeylik of Egypt was moved beyond the Second Cataract when the fortress of Ibrim, rising on a rocky promontory on the Nile, was fortified by Özdemir Bey and Lower Nubia was fully incorporated into Ottoman Egypt. (The Ottoman administrative organisation in Ibrim had been established after the conquest of Egypt; on the map Ibrim is shown as Ottoman from 1517. This year is approximate; the source gives no year.) The fortress was as much a barrier against raids coming from Nubia as it was a control point on the gold and slave route to Sennar. The Bosnian garrison stationed there became so permanent that their descendants were still in the fortress three hundred years later. The sources give two different accounts of when Ibrim came under Ottoman administration: the TDV article on Sudan links the incorporation of Lower Nubia into Ottoman Egypt to the operations of Özdemir Pasha in the middle of the 16th century, whereas the article on Nubia writes that the region as far as the Wadi Halfa valley and the administrative organisation in Ibrim were established immediately after the conquest of 1517. The sancak of Ibrim was attached to the province of Habeş on 26 July 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["The capture of Bijâya (Bougie) from the Spanish", "49691cda"], "d": ["Bijâya, which had been in Spanish hands for forty-three years and divided the coast between Algiers and Constantine in two, surrendered after being besieged by land and sea. With the fall of the fortress, the coast of the Algiers ocak became continuous as far as Oran. In Spain this loss provoked such great outrage that the commander who surrendered the fortress, Alonso de Peralta, was executed in his homeland.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["The attachment of Zeila to the Province of Habeş", "7bbf369a"], "d": ["The port of Zeila, on the African coast of the Gulf of Aden at the southern tip of the province of Habeş, was brought under Ottoman administration. This city, which was the gateway of the Adal Sultanate to the sea, was the last supply point for ships going out beyond Bab al-Mandab. With the incorporation of Zeila, the Ottoman State's frontier in Africa reached its southernmost point.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["The Battle of the Princes at Konya", "1c8de387"], "d": ["Prince Bayezid, who had entered the struggle for the throne, came before Konya with a force of about 30,000 men and was defeated by his brother Prince Selim in a clash lasting two days. The routed Bayezid took refuge in Iran with Shah Tahmasb by way of Amasya. The battle turned the succession crisis in the last years of Süleyman the Lawgiver into a foreign-policy problem.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["The Naval Victory of Djerba", "c7b905c1"], "d": ["The Ottoman fleet under Piyale Pasha scattered the allied Spanish-Genoese-Maltese fleet, assembled to retake Tripoli, off Djerba with a manoeuvre of splitting into two. The allies lost the greater part of their fleets, and the fortress on the island fell shortly afterwards. Djerba is regarded as the second great naval victory, after Preveza, that cemented Ottoman superiority in the Mediterranean.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["The Execution of Prince Bayezid at Qazvin", "a759de14"], "d": ["Prince Bayezid, who had taken refuge in Iran, was, after long bargaining, handed over by Shah Tahmasb to an Ottoman delegation and was strangled together with his four sons. In return for the handover the Safavids obtained significant material concessions and a guarantee of the frontier. With this execution the last obstacle to Selim II's accession to the throne was removed, and the peace order of the Treaty of Amasya was preserved.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["The taking of Chios from the Genoese", "a4559b96"], "d": ["Chios, which had been administered for two hundred years as a trading colony belonging to the Genoese Giustiniani family and paid tribute to the Ottomans, was taken over by Piyâle Pasha without a single shot being fired, on the grounds that it had defaulted on its tribute and had given harbour to enemy ships. Together with Chios and Psara, the last Genoese presence on the eastern shore of the Aegean was also liquidated. With the Chians' mastic production and privileges preserved, the island was attached to the province of Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["The annexation of the Duchy of Naxos — all of the Cyclades", "68f0ec0b"], "d": ["The Latin Duchy of Naxos, which had lasted since 1207 and had paid tribute to the Ottomans since 1537, was abolished on the pretext of the complaints that came in about its last duke, Giacomo Crispo, oppressing his people. Naxos, Paros, Antiparos, Andros, Syros, Mykonos, Ios, Amorgos and all the Cyclades islands around them were brought under direct Ottoman administration by a single decision. Süleyman the Lawgiver gave the administration of the islands for a time to Joseph Nasi; three and a half centuries of Latin rule thus ended in the middle of the Aegean.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["The Yemen Rebellion and Koca Sinan Pasha's Yemen Campaign", "c8218d8e"], "d": ["The Zaydi imam al-Mutahhar rose in revolt on the grounds that taxes were being collected by force and tore Ottoman administration out of the greater part of Yemen. Koca Sinan Pasha, sent from Istanbul, re-established Ottoman dominion in the region through the operations he conducted between 1568 and 1570, taking Kawkaban after a long siege. The campaign was of vital importance for preserving control of the southern gate of the Red Sea and of the Indian Ocean trade route.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["The Defensive Alliance with the Sultanate of Aceh and Aid in the Indian Ocean", "8e835f24"], "d": ["The Acehnese envoys, who had asked Süleyman the Lawgiver for help against Portuguese attacks, presented their allegiance to Selim II upon the sultan's death at Szigetvár, and a defensive agreement was signed with him. The sultan ordered cannon, muskets, munitions and craftsmen to be sent from Alexandria; seventeen warships were prepared to be dispatched to the Indian waters. The growth of the Yemen rebellion prevented the fleet from setting out, but the Ottoman gunners and craftsmen who reached Aceh left a lasting mark in the region.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["The landing on Cyprus: the capture of Limassol", "9074ccc9"], "d": ["The Ottoman army that landed on the island seized Limassol without encountering much resistance and the next day turned toward Larnaca. Because the local population was dissatisfied with Venetian rule and helped the Ottoman forces, no serious resistance was met at Larnaca either; the landing of Tuzla was made a base for landing troops and equipment. Venice had concentrated its defence at Nicosia and Famagusta; the governor of Paphos declared his obedience to the commander-in-chief only after Nicosia had fallen.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["The Conquest of Nicosia", "413d866b"], "d": ["After a siege that began on 25 July 1570 and lasted forty-five days, Nicosia, the Venetian-ruled capital of Cyprus, surrendered to the Ottoman army. The fall of the island's centre squeezed Venetian resistance into the fortress of Famagusta. The conquest aroused great repercussions in the West and accelerated the process leading to the formation of the Holy League fleet under the leadership of the Pope.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["The surrender of Kyrenia — the northern coast of Cyprus", "39fdeea5"], "d": ["The fall of Nicosia on 9 September, put to the sword, broke the resistance in the north of Cyprus. The fortress of Kyrenia, behind the Pentadaktylos mountains, upon learning the fate of the capital, surrendered on terms eight days later, and its garrison was sent away, being allowed to leave the island. The Venetian flag remained on the island only at Famagusta; that too would hold out for eleven more months.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["The Rebuilding of the Fleet after Lepanto", "db51fe44"], "d": ["The first task of Kılıç Ali Pasha, who was appointed to the grand admiralty after the disaster of Lepanto, was to rebuild the fleet that had suffered heavy losses; the shipyards worked without interruption throughout the winter of 1571-1572. In June 1572 a new fleet consisting of about 250 galleys and 300 volunteer reis galleys put to sea in the Mediterranean. This rapid recovery showed that Lepanto had not permanently broken Ottoman naval power.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["The Treaty of Istanbul with Venice — The Recognition of Cyprus", "4d08ef50"], "d": ["Venice, left alone by the dissolution of the Holy League, made a separate peace with the Ottomans, officially accepted that Cyprus belonged to the Ottomans, and consented to pay a war indemnity. The treaty made clear that the victory of Lepanto had brought the Christian world no political gain. From then on Venice would avoid entering into direct war with the Ottomans for seventy years.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["The Death of Selim II", "c289f5ee"], "d": ["Selim II, unable to attend the divan for about two months after a fall, died. His death was kept secret in the palace for twelve days until his eldest son Murad came to Istanbul from Manisa. The sources differ on the day of death: Selânikî says 15 December; Gerlach, Mehmed b. Mehmed and Cenâbî say 13 December.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["The Announcement of Selim II's Death and the Accession of Murad III", "84334d70"], "d": ["Selim II's death and the accession of Murad III, who was brought from Manisa, were officially announced on 22 December 1574. The new sultan would remain on the throne for twenty-one years, and his reign would be remembered for the long Iranian wars in the East, the eve of the Long War in the West, and the debasement of the akçe at home. Until the death of Sokollu Mehmed Pasha in 1579, the old order continued in the administration of the state.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["The Battle of Wadi al-Makhazin (Alcácer Quibir) — Abd al-Malik, Backed by the Ottomans, Annihilated the Portuguese Army", "21280dac"], "d": ["Abd al-Malik, who had taken the throne of Morocco with Ottoman support, annihilated the great army of King Sebastian of Portugal at Wadi al-Makhazin; because three rulers died in the battle at once, it is called the 'Battle of the Three Kings' in Western sources. Portugal's military power collapsed, and the country soon passed into the hands of Spain. Abd al-Malik also died in the battle; his brother Ahmad al-Mansur, who succeeded him, announced the victory to Istanbul with a delegation. The relationship between the two states remained at the level of an exchange of envoys and gifts, not tribute or vassalage, and soon became strained over the question of gifts.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["The people of Derbent's declaration of allegiance to Lala Mustafa Pasha — the Iron Gate under Ottoman administration", "9c55aeff"], "d": ["During the Shirvan campaign, a seven-man delegation from the people of Derbent went to the commander-in-chief Lala Mustafa Pasha, who was at Ereş, and declared their allegiance. Derbent (the Iron Gate), which closes the narrow pass between the Caucasus wall and the Caspian Sea, played a key role in the retention of Shirvan as the compulsory passage of the land routes coming from the north. Ottoman domination here lasted until 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["The conquest of Shirvan: the taking of Shamakhi", "9afae4c1"], "d": ["The army, which had opened onto the Caucasus after the Victory of Çıldır, entered Shirvan, the richest province of the Safavids on the Caspian shore, and took its central city, Shamakhi. With Özdemiroğlu Osman Pasha appointed beylerbeyi there, the northern branch of the Silk Road was brought under Ottoman control. Shirvan would become the front that changed hands most often and cost the most dearly in the twelve-year eastern war.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["The taking of Baku — reaching the Caspian shore", "eb5adab8"], "d": ["As the last link of the Shirvan operation, the port of Baku on the western shore of the Caspian Sea was taken. The naphtha wells around the city were, even in that period, a known source of revenue, and the port was the point of export for Iranian silk coming via the Caspian. The Ottoman State thus became, for the first and only time in its history, a littoral power on the Caspian Sea.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["The conquest of Revan (Yerevan) and the construction of the fortress", "7f623b7b"], "d": ["Ferhad Pasha, who at Kars received the order to go to Revan and build a fortress there, marched on Revan, and the city was taken under Ottoman control in the early days of Ramadan 991 (mid-September 1583). In Revan, which holds the northern gate of the Aras valley, a new and large fortress was built; the city was made the seat of a beylerbeylik. Standing in the middle of the army road between Kars and Tabriz, Revan was the logistical backbone of the eastern front. The fortress was built so solidly that for the following two hundred years it was the constant target of the Ottoman-Iranian wars.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["The annexation of Karabakh and Ganja", "29abaead"], "d": ["As the last gain of the ten-year eastern war, Ferhad Pasha marched on Ganja in 1588 and entered the city on 1 September; the Karabakh region between the Kura and the Aras and its centre, Ganja, were taken under Ottoman administration. Thus Shirvan, Revan and Karabakh joined to form an uninterrupted Ottoman line in the Caucasus. The Treaty of Ferhad Pasha, signed in 1590, would confirm this frontier, but the gain could be held for only twenty years.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["The Conquest of Bihać", "651a7275"], "d": ["Telli Hasan Pasha, the beylerbeyi of Bosnia, after taking Ripač, the outer fortress of Bihać, in November 1591, captured the city and the fortress itself in 1592; after a ten-day siege the commander Lamberg surrendered. This conquest pushed the Bosnian frontier forward along the Una river and was the last great Ottoman gain on the eve of the Long War, which would break out a year later with the martyrdom of Telli Hasan Pasha before Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["The Beginning of the Ottoman-Austrian 'Long War'", "bd22c392"], "d": ["Upon the defeat and martyrdom of the Bosnian Beylerbeyi Telli Hasan Pasha before Kulpa (Sisak), the Ottoman State declared war on Austria and the Long War, which would last thirteen years, began. This war, in which infantry with firearms was decisive, accelerated the employment of sekban and musket-armed troops in the Ottoman army order and deepened the decline of the timar-holding sipahi. The war would end in 1606 with the Treaty of Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pasha Set Out on the Austrian Campaign — The First Campaign of the Long War", "d4a2f46d"], "d": ["After the defeat and martyrdom of the Bosnian beylerbeyi Hasan Pasha before Sisak, the grand vizier Koca Sinan Pasha persuaded the sultan to go to war with brilliant words and promises and set out with 12,000 Janissaries and other units. Thus the first campaign of the Ottoman-Austrian war, which would last thirteen years, was opened.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["The Conquest of Yanıkkale (Győr)", "14b75207"], "d": ["The grand vizier Koca Sinan Pasha, after a siege of more than a month, received the surrender of Yanıkkale, regarded as the lock on the road to Vienna. The fall of the fortress caused great panic in Europe and was the Ottomans' most brilliant gain in the Long War. However, the fortress could be held for only four years.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["The Death of Murad III", "1b62e886"], "d": ["After a reign of twenty-one years, Murad III died in the days when the Wallachian army burned Brăila and reached as far as Silistra, and was buried in the cemetery of Hagia Sophia. His son Mehmed III, summoned from Manisa, reached Istanbul ten days later and ascended the throne (27 January 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["The Loss of Esztergom to Austria", "f420d333"], "d": ["The garrison of Esztergom, which did not receive sufficient aid during the siege led by Karl von Mansfeld, surrendered the fortress to Archduke Matthias. With the end of fifty-two years of Ottoman dominion, the defensive chain on the Danube line was broken and Buda came under direct threat. The fortress could be retaken only ten years later, in 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["The Conquest of the Fortress of Eger", "3e511629"], "d": ["After a struggle of three weeks, the strong fortress of Eger, which the Ottomans had never been able to take before, fell with the surrender of its garrison. This conquest, at which the sultan was personally present, repaired to some extent the morale damaged by the loss of Esztergom, and the province of Eger was established. Together with the victory of Mezőkeresztes won two weeks later, 1596 became the most successful Ottoman year of the Long War.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["The Loss of Yanıkkale (Győr)", "b4ccc679"], "d": ["Units under Miklós Pálffy and Adolf von Schwarzenberg retook Yanıkkale by blowing up the fortress gates in a surprise attack. The loss of the fortress, which Koca Sinan Pasha had obtained with great effort four years earlier, collapsed the Ottoman forward line in Hungary. Although the enemy forces that besieged Buda in the same year were repulsed, the balance of the war was gradually turning into a war of attrition.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["The Uprising of Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, who gathered the sekbans and levends who had deserted the army in the Long War, took a wide region of Central Anatolia under his control, seized the Fortress of Urfa (November 1599), proclaimed his sultanate with the title 'Halim Shah' and sent out decrees bearing his own tughra. Regarded as the first leader of the great Celali wave, Karayazıcı died in 1602, and his movement was continued by his brother Deli Hasan. The uprising marks the beginning of the period of the 'great flight', when the Anatolian peasantry abandoned their land en masse.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Tiryaki Hasan Pasha's Defence of Kanizsa", "d56a5e6a"], "d": ["Archduke Ferdinand and his allies, wishing to retake Kanizsa, which had been conquered a year earlier, besieged the fortress for more than two months; Tiryaki Hasan Pasha resisted with his force of 9,000 men. Despite receiving no help from outside, he repulsed the general assaults and, with sorties, forced the enemy to withdraw after heavy losses. The defence became epic in Ottoman historiography, and the 'Siege of Kanizsa' became a literary genre in its own right.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["The Death of Mehmed III and the Accession of Ahmed I", "da735fde"], "d": ["Upon the death of Mehmed III on 20 December, his fourteen-year-old son Ahmed I ascended the throne. His being the first sultan to take the throne at a young age and without having gone out to a provincial governorship (sancak) shows that the practice of raising princes in the provinces had effectively come to an end. In the reign of Ahmed I, fratricide would be abandoned and a transition made to the principle of 'ekberiyet' (the eldest male member succeeding to the throne).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["The Recapture of Esztergom", "7330f273"], "d": ["The grand vizier Lala Mehmed Pasha besieged Esztergom, lost ten years earlier, and brought it back under Ottoman administration. In the same campaign Pest and Vác were also liberated, and the Ottomans had consolidated their line in Hungary. This success made it possible to sit at the table from a relatively strong position at Zsitvatorok the following year; Esztergom would remain in Ottoman hands until 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["The Victory of the Plain of Oruç and the Suppression of the Canbolatoğlu Rebellion", "30f93532"], "d": ["Canbolatoğlu Ali Pasha, who had established an independent principality in Aleppo and sought an alliance with Tuscany, was heavily defeated on the Plain of Oruç by the Grand Vizier Kuyucu Murad Pasha. With the re-establishment of central authority in Syria, the most dangerous branch of the Celali wave was broken. Kuyucu Murad Pasha's ruthless purge, lasting two years, secured order in Anatolia, if only temporarily.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["The Victory of Alaçayır and the Suppression of the Kalenderoğlu Rebellion", "55db0485"], "d": ["Kalenderoğlu, the Celali leader who had put the regions of Manisa and Bursa under tribute, was defeated at Alaçayır by Kuyucu Murad Pasha and was forced to flee to Iran. With this victory the last of the great Celali armies in Anatolia was dispersed. Kuyucu Murad Pasha's harsh purge, in which he is rumoured to have filled wells that he had dug with the rebels he had killed, secured order in the short term but could not make up for Anatolia's loss of population and production.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["The Granting of the First Ahidname to the Netherlands", "5d9d117e"], "d": ["Cornelis Haga, the envoy of the United Dutch Republic, succeeded in obtaining from Ahmed I an ahidname of the same scope as those given to France and England. The Netherlands thus gained the right to open an embassy in Istanbul, to open consulates at Ottoman ports, and to trade under its own flag. This ahidname symbolises the entry into the Ottoman market of the northern maritime powers that replaced Venice in Mediterranean trade.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["The Death of Ahmed I and the Accession of Mustafa I — The Practice of Ekberiyet", "9901c09e"], "d": ["After a stomach illness lasting fifty-one days, the twenty-eight-year-old Ahmed I died, and his brother Mustafa I was placed on the throne in place of his son. Thus the practice of succession from father to son was abandoned, and a de facto transition was made to the system of 'ekberiyet', in which the eldest male member of the dynasty takes the throne. This first reign, lasting ninety-six days, is also the beginning of the era in which princes were raised in the 'kafes'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["The Deposition of Mustafa I and the Accession of Young Osman (Osman II)", "e0f552f2"], "d": ["On the grounds that he was not of sound mind, Mustafa I was deposed after ninety-six days, and Ahmed I's fourteen-year-old son Osman II became sultan. According to the account based on Hasanbeyzâde, the chief black eunuch (Kızlar Ağası) Mustafa Agha was influential in this deposition decision. With his plan to abolish the Janissary corps and form a new army, Young Osman is regarded as the first radical figure of the Ottoman reform debates. This plan would cost him his life four years later.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["The Treaty of Serav — The Renewal of Peace with Iran", "e778aca8"], "d": ["The Treaty of Serav, reached with Iran after the defeat at Pul-i Shikasta, largely confirmed the terms of the 1612 Treaty of Nasuh Pasha; the annual amount of silk to be sent by the Safavids was reduced from two hundred loads to one hundred loads. Thus the second phase of the eastern wars that had continued since 1603 came to a close. The peace would not be long-lived; with the loss of Baghdad in 1623, the war would flare up again.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["The Khotin Campaign and the Treaty of Khotin", "bc4c823c"], "d": ["The fortified camp that Chodkiewicz established before Khotin could not be overcome by the great army commanded in person by Osman II, and no result was obtained from assaults lasting months. By the treaty signed on 9 October the Dniester river was accepted as the frontier, and the Poles undertook to prevent Cossack raids. Although it was presented as a victory, the campaign, which failed to yield a result, reinforced the young sultan's distrust of the Janissaries and his intention to purge the corps.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["The Second Deposition of Mustafa I and the Accession of Murad IV", "1b3a9e74"], "d": ["Mustafa I, who had been placed on the throne for a second time after the killing of Osman II, was deposed again after one year and three months, and the eleven-year-old Murad IV was proclaimed sultan. For the first nine years the state was in effect governed by his mother Kösem Sultan and the notables of the palace. Murad IV would take over the administration in person from 1632 and begin a period of harsh centralisation.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["The Loss of Baghdad to the Safavids", "db81be0c"], "d": ["As a result of the negotiations that Bekir Subaşı, who had rebelled in Baghdad, entered into with the Safavids, his son Derviş Mehmed, who was defending the inner citadel, surrendered the city to the forces of Shah Abbas. The loss of one of the symbolic cities of the caliphal heritage and of the greater part of Iraq aroused great indignation in Istanbul. Retaking Baghdad would be the sole aim of Ottoman eastern policy for fifteen years.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["The Suppression of the Erzurum-Based Rebellion of Abaza Mehmed Pasha", "e6da2729"], "d": ["Abaza Mehmed Pasha, the beylerbeyi of Erzurum, who rose against the Janissaries with the claim of avenging the killing of Osman II, held Eastern Anatolia under his control for years and resisted the centre. He was forced to surrender at the siege of Erzurum by the Grand Vizier Hüsrev Pasha, and was pardoned and appointed to Bosnia. The end of the rebellion was the precondition for Murad IV to be able to march against Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["The First Execution of a Şeyhülislam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Şeyhülislam Ahîzâde Hüseyin Efendi was executed near Büyükçekmece, the grounds cited being that he had mediated in the military disorder and had sent the sultan a written warning concerning judicial procedure. Being the first Ottoman şeyhülislam to be executed, he broke the deep-rooted tradition that the severest punishment for members of the ilmiye was exile. The event is regarded as a symbol of the hardening authority of Murad IV and of the disruption of the balance between the state and the ulema.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Murad IV's Conquest of Revan", "b65a9b73"], "d": ["Murad IV, who set out from Istanbul on 28 March 1635, besieged Revan on 28-29 July and received the surrender of the fortress on 8 August; he then entered the evacuated Tabriz and had the city destroyed. In memory of the victory the sultan had the Revan Pavilion built in Topkapı Palace. This campaign was the first great eastern operation after an interval of thirty years in which the sultan commanded the army in person.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["The Loss of Revan to the Safavids", "fbb8dd25"], "d": ["After the withdrawal of the Ottoman army, the forces of Shah Safi besieged Revan and retook it within eight months. The fortress's being lost so quickly showed how difficult lasting dominion in the Caucasus was logistically. Revan would also be left in Iran by the 1639 Treaty of Qasr-i Shirin, and the Ottomans would give up their claim to Azerbaijan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["The Reconquest of Baghdad", "4d2f27f3"], "d": ["Murad IV, who left Istanbul on 8 May 1638, retook Baghdad, which had been in Safavid hands for fifteen years, after a fierce siege lasting forty days; the Vizier Tayyar Mehmed Pasha was martyred in the siege. With the conquest of the city Ottoman administration was re-established in Iraq, and the sultan took the title 'Conqueror of Baghdad'. The conquest was made permanent by the Treaty of Qasr-i Shirin the following year and laid the foundation of the present Turkey-Iran frontier.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["The Death of Murad IV and the Accession of Sultan Ibrahim", "e2ca1ca0"], "d": ["After the death of Murad IV at the age of twenty-eight, his brother Ibrahim, the only surviving male member of the dynasty, ascended the throne. In the reign of the new sultan, who had lived for years in the cage, palace expenditures and struggles for influence within the palace shook the order of the state. With his deposition and killing eight years later, the second regicide of Ottoman history would take place.", "4c336200"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["The Recapture of the Fortress of Azov from the Cossacks", "e5fcf160"], "d": ["The Fortress of Azov, which the Don Cossacks had seized in 1637, was evacuated in the face of the joint operation of Sultanzâde Mehmed Pasha and the Crimean Khan Mehmed Giray IV; the Cossacks set the fortress on fire and withdrew. The recovery of the northern gate of the Black Sea closed the dangerous period in which Cossack raids had reached as far as the Bosphorus of Istanbul. The fortress would be lost, this time to the Russian Tsar Peter I, in 1696.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["The Beginning of the Cretan Campaign and the Conquest of Canea", "a1b0c77f"], "d": ["War was declared on Venice on the pretext that Maltese corsairs had struck an Ottoman pilgrim ship and taken refuge in Crete, and the fleet under Yûsuf Pasha landed troops on the island. After a siege of fifty-four days the fortress of Canea was taken and the first lasting Ottoman base in Crete was established. Thus the longest war of Ottoman history began; the island could be completely conquered only twenty-four years later, in 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["The conquest of Rethymno — the splitting of Crete in two", "8f2c4353"], "d": ["One year after the taking of Chania, the fortress of Rethymno in the central part of the island also fell, and the western half of Crete came entirely under Ottoman administration. Only the capital, Candia, and the eastern tip remained in Venice's hands; the island lived for twenty-three years divided in two. The capture of Rethymno was the step that began the siege of Candia — the longest siege in history began here.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["The Loss of Klis to Venice", "5473c22c"], "d": ["On the Dalmatian front of the Cretan (Candia) War, the counter-offensive of the Venetian commander Leonardo Foscolo also encompassed Klis, which had been a sancak centre since 1537; the fortress passed to Venice. The Ottomans' concentrating all their strength on Crete made it impossible to retake this loss on the Dalmatian frontier — Klis would never return to Ottoman administration; the sancak centre was moved to Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["The Beginning of the Siege of Candia", "13016b10"], "d": ["After the capture of Canea and Rethymno, the Ottoman army laid siege to Candia, Venice's last great stronghold on the island. This blockade, which would last twenty-one years, went down in the record as one of the longest sieges in world military history. Throughout the siege, the Venetian fleet's attempts to close the Dardanelles would carry the war to the heart of the Aegean.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["The Killing of the Grand Valide Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, aged about sixty-two, was found in a room in the Harem and killed by Başlala Uzun Süleyman Agha and his men, who were acting on the order of Turhan Sultan, the mother of Mehmed IV. The death of this powerful woman of the dynasty, who had directed the policy of the state under three sultans, is regarded as the effective end of the period called the 'Sultanate of Women'. The authority thus vacated opened the way, five years later, to Köprülü Mehmed Pasha's becoming grand vizier with extraordinary powers.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["The Dardanelles Defeat and the Loss of Bozcaada and Lemnos", "e01a1f7e"], "d": ["The great naval victory that the Venetian admiral Mocenigo won off the Dardanelles in June 1656 destroyed the Ottoman fleet almost completely; Bozcaada, Lemnos and Samothrace were then occupied. With the Strait coming under Venetian blockade, food prices in Istanbul soared and fear of an attack on the capital spread. This catastrophe was the direct reason for Köprülü Mehmed Pasha's being appointed grand vizier in September 1656 on conditional terms and with extraordinary powers.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["The Dardanelles Victory and the Recapture of Bozcaada", "603da863"], "d": ["The fleet mobilised by Köprülü Mehmed Pasha defeated the Venetian fleet before the Strait on 19 July 1657; then the forces under Kurd Pasha retook Bozcaada on 25 August, and on 30 August the Venetians evacuated the island completely. In November Lemnos was also liberated, the Dardanelles blockade was broken and Istanbul's supply route was reopened. Köprülü crossed to the island himself and had the fortifications repaired; this success is the first great military gain of the Köprülü era.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["The recovery of Lemnos from Venice", "a4c3c69b"], "d": ["Lemnos, which Venice had taken in July 1656, returned to the Ottomans in November 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["The Conquest of Yanova (Ineu) and the Transylvanian Campaign", "d1089616"], "d": ["Köprülü Mehmed Pasha, who set out on campaign to punish George II Rákóczi, Prince of Transylvania, who had violated Ottoman protection by setting out on an unauthorised Polish campaign, marched by way of Belgrade and took the strategic fortress of Yanova. A new prince was appointed to Transylvania, and the vassalage bond was sharply recalled. This campaign was the first link in the Ottomans' attempt to re-establish their authority in Central Europe. Transylvania was already a principality subject to the Ottomans; the capture of Yanova was not a conquest from a foreign state, but the removal of this fortress of vassal Transylvania from the principality's administration and its attachment to an Ottoman sancak directly; the rest of the principality remained in vassal status.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["The Suppression of the Rebellion of Abaza Hasan Pasha", "4ba74321"], "d": ["Abaza Hasan Pasha, who had won over the Anatolian beylerbeyis and sekban agas against Köprülü Mehmed Pasha's harsh purges, began a great uprising by demanding the dismissal of the grand vizier. The rebellion was suppressed at Aleppo and its ringleaders were eliminated; this was the last collective resistance of the provincial pashas to the centre. Köprülü's authority thus became unquestioned, and the office of the grand vizierate rose again to the position of the true executive centre of the state.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["The Conquest of Várad (Oradea)", "0e6ad300"], "d": ["Within the framework of the campaign mounted against George II Rákóczi, Prince of Transylvania, who had declared war on the Ottomans, the fortress and city of Várad were taken. With the fall of one of the key fortresses of Transylvania, a new Ottoman province (the Province of Várad) was established in the region. The conquest alarmed the Habsburgs and became one of the direct causes of the Ottoman-Austrian war that would begin three years later. Other places that joined on the same date: Varat. Here too the land was not taken from a foreign state: Transylvania was already a vassal Ottoman principality; the making of Várad into a province merely took the administration of this town from the vassal principality and attached it directly to the sultan, just as at Yanova two years earlier.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["The Battle of St. Gotthard", "61ebc1f2"], "d": ["The Ottoman forces that crossed the Raab river were stopped by the allied European army under Montecuccoli and suffered heavy losses. The battle is regarded as a turning point in military history in that it showed clearly for the first time the superiority of the musket fire of disciplined infantry over the Ottoman cavalry charge. Despite the defeat, the Ottomans managed to obtain advantageous terms in the Treaty of Vasvár signed nine days later.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["The Treaty of Vasvár", "089c978c"], "d": ["The treaty signed despite the defeat at St. Gotthard stipulated that Uyvar and Várad would remain with the Ottomans, that Transylvania would be left neutral under Ottoman protection, and that Austria would pay a 'gift' of 200,000 kuruş. This peace of twenty years' duration is one of the rare examples of the side that lost the war winning at the table. The discontent that the treaty created in Habsburg public opinion would feed the Central Hungarian movement and, indirectly, the 1683 Vienna campaign.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Beginning of dey rule in Algiers", "e99faa51"], "d": ["The Algiers ocak and the taife-i reis (corps of corsair captains) deposed the last agha and elected Hacı Mehmed dey for life. After this date Algiers was governed not by a beylerbeyi appointed by Istanbul but by a dey chosen by the local ocak from among its own members; the Ottoman tie remained limited to the reading of the sultan's name in the khutba and to obligations of the standard and of campaign service. Algiers thus changed from a province into an ocaklık — the same transformation was experienced by Tunis in 1705 with the Husaynids and by Tripolitania in 1711 with the Karamanlis.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["The Polish Campaign Began — Mehmed IV and Fâzıl Ahmed Pasha at the Head of the Army", "75e15a39"], "d": ["When Polish attacks continued against the Ukrainian hetman Petro Doroshenko, who had come under Ottoman protection, Istanbul asked the Polish king to desist from the attacks; when no favourable answer came, the decision for a campaign against Poland was taken. The Grand Vizier Fâzıl Ahmed Pasha set out for Poland on 4 June 1672 with the army, in which the sultan was also present. The campaign would end in the conquest of Kamaniçe and the Treaty of Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["The Conquest of Kamaniçe and the Establishment of the Province of Podolia", "c3f4f6d0"], "d": ["After a siege of nine days Kamaniçe, regarded as Poland's strongest fortress in the east, was taken; on 2 September Mehmed IV performed the first Friday prayer in the mosque converted from the cathedral. With the fortress made the centre, the Province of Podolia was established, and the Ottoman flag reached its northernmost point on the territory of present-day Ukraine. Kamaniçe would remain the northwestern extremity of the empire until the 1699 Treaty of Karlowitz.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasha Received the Surrender of Uman from Poland", "0d3543a0"], "d": ["Kara Mustafa Pasha, sent against Poland, received the surrender of Uman, one of the fortresses held by Poland; the city remained under Ottoman administration until Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["The Conquest of the Fortress of Chyhyryn", "a17cedd0"], "d": ["After the operation in which Melek Ibrahim Pasha had failed to achieve a result the previous year, the Grand Vizier Merzifonlu Kara Mustafa Pasha, commanding in person, besieged the fortified fortress of Chyhyryn (19/21 July) and captured it on 21 August. The fall of the fortress, a symbol of the Ottoman-Russian rivalry over the Cossack hetmanate in Ukraine, forced Russia to peace. This success was also one of the sources of the self-confidence with which Merzifonlu would turn toward Vienna.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["The Treaty of Bakhchysarai — The First Official Peace with Russia", "df82bc0b"], "d": ["As a result of negotiations conducted through the mediation of the Crimean Khan after the Chyhyryn campaigns, a twenty-year peace was signed between the Ottoman State and Russia, with the Özü (Dnieper) river accepted as the frontier. Being the first comprehensive treaty between the two states, it is regarded as the founding document of Ottoman-Russian relations. Thanks to the peace, the eastern front was secured and the army could be directed to Central Europe.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["The Granting of the Berat of the Kingship of Central Hungary to Imre Thököly", "3cd8d51d"], "d": ["Imre Thököly, the Protestant Hungarian nobleman who rose against Habsburg pressure, began to be regarded from April 1682 as the 'elected king of Central Hungary', and on 16 September the Beylerbeyi of Buda, Ibrahim Pasha, presented him with the insignia of princeship. Thus a new vassal Hungarian state was established under Ottoman protection. This intervention made war with Austria unavoidable and set in motion the chain leading to the Second Siege of Vienna the following year.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["The Loss of Ayamavra (Lefkada) to Venice", "e6905fee"], "d": ["The fleet of Venice, which had joined the Holy League, bombarded the town and then occupied the Island of Ayamavra in the Ionian Sea. With the fall of Preveza in the same year, Ottoman control at the mouth of the Adriatic was broken. These losses were the opening steps of the operation in which Morosini would seize the whole of the Morea within three years.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["The Loss of Koroni to Venice", "2ed762bc"], "d": ["The Venetian forces under Morosini captured the fortress of Koroni at the southwestern tip of the Morea peninsula; the city would remain under Venetian administration for thirty years thereafter. The fall of Koroni was the first great gain of the Venetian operation aimed at the conquest of the Morea. The fortress could be retaken only in 1715 by the Ottoman army under Silâhdar Ali Pasha.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["The recovery of Athens — the withdrawal of Venice", "03393b46"], "d": ["Morosini, who in September 1687 had bombarded the Acropolis and blown up the Parthenon, realised after spending the winter in Athens that he could not hold on in the city. Upon the plague epidemic, the difficulty of supply and the recovery of the Ottoman forces, the Venetian garrison evacuated the city and withdrew to the Morea. Athens thus returned to Ottoman administration without a fight, but the destruction the Parthenon had suffered could not be undone.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) surrendered to Caraffa — passed into Austrian hands", "7f0a8d38"], "d": ["After Antonio Caraffa's three-day siege, Lipova surrendered between 12 and 22 June 1688 and passed into Austria's hands. The Ottomans later retook the city, Austria seized it again in 1691; in the campaign of 1695 the Ottomans re-established control.", "9ddd4e2f"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["The Repulse of the Venetian Siege of Negroponte", "aae7e6a0"], "d": ["Morosini, who turned to the Aegean after seizing the Morea, tried to take Negroponte with a siege lasting more than three months; however, in the face of the fortifications strengthened in the winter of 1687-1688 and the resistance of the garrison, he was forced to withdraw after suffering heavy losses. This failure halted Venice's advance in the Aegean and shook Morosini's military prestige. Negroponte would also remain in Ottoman hands at Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["The Loss of the Fortress of Kanizsa to Austria", "553b45f3"], "d": ["Kanizsa, placed under the tight blockade of a Habsburg army of 60,000 men from January 1690, held out for months without receiving help and then was lost through a surrender agreement signed by its last commander, Mustafa Pasha. Thus ninety years of Ottoman dominion ended in the fortress remembered for the epic defence of Tiryaki Hasan Pasha. The loss of Kanizsa was the collapse of the Ottomans' last great stronghold in western Hungary.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["The death of Süleyman II", "d2478080"], "d": ["Süleyman II, who was placed on the throne in 1687 after spending about forty years in the kafes, died at Edirne toward noon on Friday, 22 June 1691, while, ill, he was following the army's preparations; his reign lasted three years, eight months and two days. The grand vizier had given in advance the necessary instructions for his brother Ahmed to be placed on the throne in the event of the sultan's death. The funeral prayer was performed the same day at the Alay Köşkü; his body was brought to Istanbul and buried in the tomb of Süleyman the Lawgiver, on his right side.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["The Accession of Ahmed II", "52947b14"], "d": ["Upon the death of Süleyman II, his forty-nine-year-old brother Ahmed II ascended the throne at Edirne. His reign coincided with the hardest years of the Holy League wars; two months after his accession, the Grand Vizier Fâzıl Mustafa Pasha was martyred at Slankamen. On the other hand, the mâlikâne system put into practice in his period became one of the most important arrangements that changed the long-term structure of Ottoman finance.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["The death of Mehmed IV at Edirne", "17388b7e"], "d": ["Mehmed the Hunter, who was deposed in 1687, was brought to Edirne during Süleyman II's 1689 Hungarian campaign and also witnessed the reign of his other brother, Ahmed II. He died in this city, which he loved very much. His body was brought to Istanbul and buried in the tomb of his mother, Turhan Sultan, next to the Yeni Cami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["The death of Ahmed II at Edirne", "c6306c08"], "d": ["Ahmed II, whose four-year reign was passed in war, died at Edirne at the age of fifty-two of istiskā (dropsy). His body was brought to Istanbul and interred in the tomb of Süleyman the Lawgiver. His nephew Mustafa II succeeded him.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["The capture of Basra by the Iranians", "a9cdf3a3"], "d": ["While the Ottoman state was occupied with the wars of the Holy League in the west, Basra, after the plague epidemic of 1690, was plundered first by Mâni, the sheikh of the Muntafiq, and then by Ferecullah, the Khan of Huveyza. Taking advantage of this turmoil, the Iranians seized the city in 1696 and left a garrison in Basra.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["The Treaty of Istanbul — The Ceding of Azov to Russia", "79db4724"], "d": ["At Karlowitz only a two-year armistice could be made with Russia; the lasting peace was signed in Istanbul after difficult negotiations lasting a year and a half. The Ottoman State officially relinquished to Russia the Fortress of Azov, which it had lost in 1696, and the lands around it, and gave up the annual tax the Crimean khan received from Moscow. In return, Russia obtained the right to keep a permanent envoy in Istanbul; thus the Russian presence on the northern shore of the Black Sea was legally registered.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Pasha's recapture of Qurna and Basra", "7adb777d"], "d": ["Daltaban Mustafa Pasha, who was appointed to the governorship of Baghdad and the seraskership of Basra after the Treaty of Karlowitz, marched south with the forces of Aleppo, Raqqa, Sivas and Karaman and with a river fleet that descended from Birecik. The tribal sheikhs of the region submitted one by one, Dâvud Khan, the Iranian commander of Basra, abandoned the city, and Qurna and Basra came once again under Ottoman administration.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["The death of Mustafa II", "626c394d"], "d": ["Mustafa II, who left the throne to his brother Ahmed III through the Edirne Incident, died about five months after his deposition in Edirne, which he loved very much. To his illness was added grief over the latest developments. Some Western sources write that the belief that he had been poisoned was widespread among the people.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["The Beginning of Kölemen (Mamluk) Rule in Baghdad", "abe52618"], "d": ["With the appointment of Hasan Pasha, of Georgian origin, to the governorship of Baghdad, a period began in Iraq in which, in place of governors appointed from the centre, a ruling class raised from among their own slaves became dominant. With Süleyman Pasha's governorship in 1749 the system became firmly established, and the Sublime Porte was no longer able to appoint the person it wished but had to appoint one of the kölemens who had seized influence. Although this semi-autonomous structure was useful in the defence of the Iranian frontier, it weakened the central authority's control over Iraq for a century and a half.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["The Founding of the Husainid Dynasty in Tunis", "cb1a98f9"], "d": ["In the vacuum of authority that arose upon the invasion of Tunis by Algerian forces, Husayn b. Ali, a sipahi agha of Turkish origin, seized the beylik and gained legitimacy by declaring his allegiance to the Ottoman sultan. The dynasty he founded ruled Tunis in 1705-1735 and 1756-1957; the order of a beylik passing from father to son replaced the rule of the ocak. Thus the first example was born in the Western ocaks of dynastic structures that were attached to the centre but in practice autonomous.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["The Taking of Oran (Vahran) and Mers el-Kébir from the Spanish", "b67ce06a"], "d": ["The forces of the beylerbeyi of the Ocak of Algiers captured Oran, which had been in the hands of a Spanish garrison for two centuries, and its port Mers el-Kébir, after a long siege. It was the greatest success won against Spain by the Western ocaks under Ottoman protection in the Western Mediterranean, and it secured the western flank of Algiers. The city would be occupied by the Spanish again in 1732, but would be definitively retaken in 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["The Treaty of the Prut — The Recovery of Azov and Taganrog", "bac5d2a1"], "d": ["The seven-article treaty signed upon the surrender of the Russian army besieged on the banks of the Prut stipulated the return of the Fortress of Azov to the Ottomans together with its lands and munitions. The fortifications of Taganrog, Kamenka and Yenikale would be demolished, and the parties would not build new fortresses in these regions. The system of fleet and bases that Peter I had built over sixteen years at Voronezh and Azov collapsed; Russia's descent to the Black Sea was delayed by about fifty years.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["The Founding of the Karamanli Dynasty in Tripolitania", "e1105d4a"], "d": ["In Tripolitania, exhausted by the quarrels of the ocak agas, the cavalry officer Ahmed Karamanlı seized the administration and made his position official with the beylerbeyilik berat he received from Istanbul. A dynasty lasting from 1711 to 1835 was born through Ahmed Pasha, his son Mehmed Pasha and his grandson Yûsuf Pasha; a semi-independent structure emerged which built its own fleet and signed treaties directly with European states. This period would end only in 1835, with the direct attachment of the province to the centre.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["The Treaty of Edirne with Russia", "14901a70"], "d": ["After the promises given at the Prut were not fulfilled, war was declared twice more, and finally, when the Russians accepted the commitments, a lasting peace was signed at Edirne. The treaty confirmed the Prut terms; Russia would not interfere in Polish affairs, would withdraw from Cossack lands, and would not obstruct the return to his country of the Swedish king Charles XII, 'the Iron Head' (Demirbaş Şarl). The closing of the northern front in this way made it possible for the Ottoman State to turn its face to the Morea and Venetian front. Other places that joined on the same date: Khotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["The Declaration of War on Venice — The Preparation of the Morea Campaign", "d970b122"], "d": ["The decision for war was taken in the Divan on the grounds that Venice supported the Montenegrin rebels, seized Ottoman merchant ships, and oppressed the Morea, which it had taken at Karlowitz, with heavy taxes. The campaign prepared by the Grand Vizier Silâhdar Damad Ali Pasha would end the following year in the recovery of the whole Morea peninsula in less than a hundred days. However, this success would set Austria in motion and open the door in 1716 to a much heavier war.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos: the surrender of Venice's last island in the Aegean", "4abec891"], "d": ["The fleet setting out on the Morea campaign anchored off Tinos, the only island remaining in Venetian hands in the Aegean, on its route. The island, which, thanks to its Latin population, had borne the Venetian flag for another hundred and fifty years even though the Duchy of Naxos had fallen in 1566, surrendered without bloodshed after a short siege. Thus Venice's last footprint in the Aegean Sea was erased, and the sea became wholly an Ottoman inland sea.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["The conquest of Nauplia — the key fortress of the Morea", "62a5808a"], "d": ["Nauplia, Venice's capital in the Morea and its strongest fortification, fell when the bastion of Palamidi was taken after nine days of bombardment. The fortress's being taken so quickly broke the resistance in the rest of the peninsula. The recovery of the Morea, lost at Karlowitz, was in effect completed here.", "9b883577"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["The surrender of Modon", "43faa909"], "d": ["After the fall of Nauplia, the fortress of Modon at the southwestern tip of the Morea was besieged by the army from the land and by the fleet from the sea, and surrendered in a short time. This port, which Venice had used for two hundred years in its eastern Mediterranean campaigns, was the obligatory stopping point where ships took on water and provisions. Its loss ended the Venetian fleet's freedom of movement in the Aegean.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["The surrender of Koroni — the completion of the Morea campaign", "e4b9c8a4"], "d": ["With the surrender of the fortress of Koroni, which holds the mouth of the Gulf of Messenia, Venetian administration on the Morean peninsula came completely to an end. The peninsula, lost at Karlowitz, was thus wholly recovered only three months after the opening of the campaign. In the continuation of the same campaign, in September 1715, the island of Santa Maura (Lefkada) in the Ionian Sea was also taken from Venice. This speed forced Venice to bring Austria into the war and opened the road, three years later, to Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["The taking of Çuha Island (Kythira)", "494de6c6"], "d": ["Çuha Island at the southern tip of the Morea was taken over by the fleet following the completion of the peninsula. The island, which overlooks the passage between the Ionian Sea and the Aegean, was the forward outpost Venice used to control these waters. However, it did not remain the only island held by the Ottomans: three years later it was returned to Venice at Passarowitz.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria and Venice Formed an Alliance — The Gateway to the Ottoman-Austrian War of 1716-1718", "99511ca2"], "d": ["After the Ottomans retook the Morea from Venice, Austria, claiming that the Treaty of Karlowitz had been violated, signed an alliance treaty with Venice; Prince Eugene, in a letter to the grand vizier, demanded the return of the places taken from Venice. In the consultation at the camp of Davutpaşa, war was declared on Austria under the pressure of the grand vizier Ali Pasha, and a fatwa was obtained from the şeyhülislam for this.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["The Grand Vizier Ali Pasha Set Out on the Austrian Campaign", "2fbdce42"], "d": ["After war was declared on Austria, the serdâr-ı ekrem Ali Pasha set out on the Austrian campaign with an army of over 100,000, while the fleet turned toward Corfu the same summer. The army would march from Belgrade upon Petrovaradin, and the grand vizier would be martyred in the defeat at the beginning of August.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["The Defeat at Petrovaradin (Varadin) — The Martyrdom of Damad Ali Pasha", "265c1d81"], "d": ["The Ottoman army, which crossed the Danube by way of Belgrade, met the Austrian forces under Prince Eugene before Petrovaradin; although in the first onset the Janissary charge forced the enemy trenches, the ranks broke up with the collapse of the cavalry wing. The Grand Vizier Silâhdar Damad Ali Pasha was shot in the forehead and martyred, and the camp and the artillery train fell entirely into enemy hands. This defeat, which the Ottoman chronicles recall as 'the year of Varadin', was the first link of the chain leading to the loss of Temesvár and, the following year, of Belgrade.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["The Failure of the Siege of Corfu", "b2aa7011"], "d": ["The serasker of the Morea, Kara Mustafa Pasha, by land, and the Kaptanıderyâ Canım Hoca Mehmed Pasha, with the fleet by sea, pressed upon Corfu; the island was Venice's key base in the Adriatic. However, the extremely strong fortifications of the fortress, the reinforcements brought by the Venetian fleet, and the news of the defeat from the Danube front led to the lifting of the siege. The failure to take Corfu extinguished the mood that had risen with the reconquest of the Morea and shifted the centre of gravity of the war to Hungary.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["The Loss of Temesvár (Timișoara) to Austria", "27fe1365"], "d": ["After the defeat at Petrovaradin, Prince Eugene marched directly upon Temesvár, and the fortress was surrendered with a capitulation (vire) at the end of a siege of more than forty days. The city, conquered in 1552 in the reign of Süleyman the Lawgiver and regarded for 164 years, as a beylerbeyilik centre, as the eastern pillar of the defence of Hungary, was thus lost. With the fall of Temesvár the whole of the Banat region passed to Austria, and the Ottoman frontier was pushed south of the Danube.", "3f3368fd"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["The Surrender of the Fortress of Haram (Yeni Palanka) to Austria — The Danube Bank of the Banat Was Lost", "38ee4c6d"], "d": ["After the fall of Temesvár, the Austrian cavalry general Mercy, charged with taking the rest of the Banat, marched on 14 November upon Haram (Yeni Palanka) on the Danube bank; when he reached the fortress on 16 November, the Ottoman garrison of 200 men raised the white flag and surrendered on condition of free withdrawal. Thus the Danube line of the Southern Banat, which had been in Ottoman hands since 1552, also passed to Austria.", "8026e3e4"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["The Treaty of Passarowitz — the Morea gained, Belgrade and the Banat lost", "d46aa216"], "d": ["The Morea had been retaken from Venice, but Austria, which entered the war, gained the upper hand at the negotiating table with its victories at Petrovaradin and Belgrade. The treaty, signed under the mediation of England and the Netherlands, left the Morea with the Ottomans, but in return abandoned to Austria Northern Serbia, the Banat and Lesser Wallachia, together with Belgrade; in the words of the TDV, 'Northern Bosnia was entirely abandoned to Austria' — fortresses such as Bosnian Dubica and Bosanski Brod on the Sava pass to Austria on the map from this day (the commissioners drew the exact frontier one by one; the TDV does not name these fortresses), while Venice retained its positions on the Ionian coast such as Preveza and Çuha. With the commercial ahidname signed on the same day, the customs duty collected on Austrian goods was reduced from five percent to three. While it confirmed the Ottoman State's retreat in Central Europe, the twenty-seven-year peace the treaty opened laid the ground for the Tulip Period (1718-1730): under Nevşehirli Damad Ibrahim Pasha, the first Ottoman printing press (1727, Ibrahim Müteferrika), translation committees, observations on smallpox inoculation and a new palace-cultural life are products of these years of peace.", "3a9f1433"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["The Eastern Campaign: The Taking of Tiflis and the Beginning of the Iranian War", "78343dc2"], "d": ["Upon the collapse of the Safavid State through the Afghan invasion and Russia's descent to the Caspian shores, the Ottoman State sent an army to the east so that the vacuum would not be left entirely to Russian influence. Tiflis was captured and Georgia was attached to Ottoman administration; the advance then continued in the direction of Ganja, Revan and Nakhchivan. This campaign, conducted behind the peaceful appearance of the Tulip Era, was the beginning of a long eastern adventure that would last thirteen years and end with the return of every place gained.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["The 1723 Iranian Campaign: entry into Shirvan and Georgia", "c81189fc"], "d": ["When the Safavid State collapsed under the Afghan invasion, a campaign was launched to the east on the grounds of preventing Russia from descending onto the Caspian shores. The Erzurum army entered Tbilisi by way of Georgia, and the Shirvan column entered Shamakhi, retaking territories lost a hundred and thirty years earlier. This campaign was the Ottomans' last great advance in the Caucasus.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["The taking of Kermanshah — the gate of the Zagros", "ad14799f"], "d": ["The Baghdad army crossed the passes of the Zagros and seized Kermanshah, regarded as the western gate of Iran. The city lay on the caravan and army road from Baghdad to Isfahan, and its capture secured the eastern safety of the province of Iraq. This advance began a race for partition between the Ottomans and Russia in the dissolving Safavid land.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["The Istanbul Mukāsemenâme — The Partition of Iran with Russia", "fce8eec2"], "d": ["A partition treaty was signed through the mediation of the French ambassador to prevent the Ottoman Empire and Russia from coming face to face over the collapsing Safavid realm. The western and southern shores of the Caspian Sea were left to Russia; Georgia, Shirvan, Azerbaijan and the cities of western Iran were left to the Ottoman State. This partition, which looked like a great gain on paper, would soon become void in practice with the rise of Nader Shah. According to the treaty, the fertile lands of Shirvan such as Shabran and Mushkur were left on the Russian side (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["The taking of Nakhchivan", "bdf14d0a"], "d": ["Ottoman forces advancing along the Aras took Nakhchivan and Ordubad; Julfa was also added to the liva of Nakhchivan. The city was attached to the newly founded province of Revan as Iran's northwestern gate. Thus the Ottoman frontier once more reached its easternmost line from the time of Süleyman the Lawgiver.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["The conquest of Hamadan", "e1339a97"], "d": ["The army marching east from Kermanshah took Hamadan, at the western threshold of the Iranian plateau, after a long siege. The city was the last great stopping place on the road to Isfahan, the easternmost point the Ottoman armies had been able to reach since the Campaign of the Two Iraqs. The Treaty of Istanbul with Russia, signed the same year, set down on paper the partition of the dissolving Iran between the Ottomans and Russia.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["The reconquest of Revan", "88acabef"], "d": ["After a hard siege lasting ninety days, Revan, the key fortress of the Aras valley, again came under Ottoman administration. The fortress, built in 1583 and lost in 1604, was this time fortified with a stronger garrison. The length of the siege was an indication that the Ottoman army no longer advanced easily. The nahiyes of Karpi (Üçkilise), Şerür, Maku and Şüregel were also attached to the province of Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["The Capture of Tabriz — The Seizure of Azerbaijan", "e502a4f7"], "d": ["Tabriz, besieged again after the unsuccessful attempt of a year earlier, surrendered to the Ottoman army after a hard-fought battle that went on street by street. Merend, Maragha and Sovukbulak (Mahabad), attached to the province of Tabriz, also came under Ottoman administration. In the same year Lori, Ganja, Ardabil and Khurramabad were also taken, and the regions that fell to the Ottoman share by the Istanbul Mukāsemenâme were effectively occupied. This extent reached in the east was the farthest frontier since the era of the Treaty of Ferhad Pasha; however, holding it placed a heavy burden on the army and the treasury.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["The conquest of Ganja — the end of the Caucasus campaign", "875bca7a"], "d": ["Ganja, the final objective of the Caucasus operation, was taken over as the centre of Karabakh between the Kura and the Aras. With the completion of the line of Shirvan, Revan, Nakhchivan and Ganja, the Ottoman State reached in the Caucasus the extent it had had in 1590. However, this gain proved short-lived: the rise of Nadir Shah would retake the entire region within ten years.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["The Treaty of Hamadan — The Annexation of Western Iran to the Ottomans", "94a29dc3"], "d": ["By the treaty signed with the Afghan ruler Ashraf Shah, the war lasting four years ended and the Western Iranian lands occupied by the Ottoman State were legally recognised. In return, Ashraf Shah accepted the caliphate of the Ottoman sultan and undertook to have the khutba read in Iran in the name of the sultan. This diplomatic victory was short-lived; the counter-offensive Nadir Shah launched in 1730 would wipe out the gains of the treaty within a few years.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pasha took Urmia", "eac7f64d"], "d": ["In the Iranian campaign Hekimoğlu Ali Pasha first took Urmia (Rûmiye), and then Tabriz, evacuated to the Ottomans, on 15 November 1731. The TDV does not give the day of the capture of Urmia; only the year, and that it came before Tabriz, is known.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["The Treaty of Ahmed Pasha — The Return of the Greater Part of Western Iran", "590d839f"], "d": ["Following Nadir Shah's victory at Malayer and the successive Iranian offensives, the governor of Baghdad, Ahmed Pasha, signed a peace text without consulting the centre. According to the treaty, the Aras river was accepted as the frontier; Western Iranian cities such as Hamadan, Kermanshah, Ardalan, Ardabil and Tabriz were given back to Iran, while Ganja and Tiflis remained with the Ottomans. This text, which was met with reaction in Istanbul, was also found insufficient by Nadir Shah, and before the year 1732 was out the war flared up again.", "b7cf810a"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["The Renewed Loss of Oran (Vahran) to Spain", "20485027"], "d": ["The great landing fleet sent by King Philip V of Spain came before Oran under the command of Count Montemar, defeated the forces of the Ocak of Algiers and retook the city. The port, conquered twenty-four years earlier, would remain in the hands of a Spanish garrison again for sixty years. This loss, which showed the limits of the power of the Western ocaks in the Western Mediterranean, could be made good only with the definitive conquest of Oran in 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["The Reform of the Humbaracı Corps along European Lines and the Founding of the Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pasha, of French origin, who had entered Ottoman service, with the support of the Grand Vizier Hekimoğlu Ali Pasha made the humbaracı corps a salaried unit organised in the European manner. Three hundred soldiers recruited from Bosnia were given regular training based on arithmetic and geometry; new regulations were prepared for organisation, equipment and retirement, and one hundred mortars and fifty thousand shells were manufactured with contemporary technique. The Humbarahâne, where geometry was taught, is regarded as the first nucleus of modern military engineering education in the Ottoman Empire.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["The death of Ahmed III", "455f7fba"], "d": ["Ahmed III, who was deposed in 1730 by the Patrona Halil rebellion, spent the last six years of his life in the apartment of Topkapı Palace set aside for deposed sultans and died at the age of sixty-three. He was buried at Bahçekapı in the tomb of his grandmother Turhan Sultan next to the Yeni Cami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["The Treaty of Istanbul — The Ceding of the Southern Caucasus to Iran", "8c205aab"], "d": ["The second Iranian war, which lasted four years, ended with the treaty signed after the defeat at Arpaçay and the loss of Ganja and Tiflis. The Ottoman State withdrew from all the Southern Caucasian and Western Iranian lands it had taken since 1723, and the frontier returned to the Qasr-i Shirin line of 1639. What remained of thirteen years of eastern campaigns was a heavy financial burden and an emptied treasury; on the other hand, the closing of the eastern front was a vital gain for the new war that had begun with Russia.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["The Fall of the Fortress of Özi (Ochakov) to the Russians", "f93e61f3"], "d": ["The Russian army under Field Marshal Münnich besieged the Fortress of Özi at the mouth of the Dnieper; the defence collapsed when the arsenal exploded, and the fortress fell with great loss of life. The loss of Özi, regarded as the lock of the northwestern shore of the Black Sea, opened the road to Crimea to the Russians and created great panic in Istanbul. The following year the fortress would be evacuated by the Russians because of epidemic and supply difficulties and would pass to the Ottomans again.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["The Victory of Banja Luka — The Liberation of Bosnia", "f603865a"], "d": ["When Austrian forces entered Bosnia and besieged Banja Luka, the governor of Bosnia, Hekimoğlu Ali Pasha, hurried to the rescue with forces he had gathered from the local population and inflicted a heavy defeat on the numerically superior enemy. This victory collapsed Austria's plan to occupy Bosnia at the very first move, and the north of the province was completely recovered. Banja Luka became one of the turning points that restored the morale of the Ottoman army, which after 1683 had been constantly retreating before Austria.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["The Victory of Hisarcık (Grocka) — The Opening of the Road to Belgrade", "2101cdff"], "d": ["The Austrian army advancing to protect Belgrade was ambushed in a narrow defile on the Danube bank and suffered heavy losses in a battle lasting all day. As the forces of Field Marshal Wallis fell back on Belgrade in disorder, the Ottoman army pressed up to the fortress and began the siege. Hisarcık was the most decisive pitched victory won against Austria since Karlowitz and directly secured the recovery of Belgrade.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["The Treaty of Niš — Peace with Russia, the Neutralisation of Azov and the Halting of Crimean Raids", "674f974e"], "d": ["Russia, left alone when Austria consented to peace at Belgrade, was compelled to end the war through the mediation of the French ambassador Villeneuve. With the fortifications of the Fortress of Azov demolished, the region was declared neutral ground between the two states; Russia accepted the condition of keeping no warships or merchant ships in the Black Sea. Thus Russia's aim of access to the sea was postponed by another generation, and the Ottoman State rose from the table with a gain for the last time in the eighteenth century.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi Returned from the Russian Occupation: Handed Over after the Fortress Was Demolished under the Peace of 1739", "7ecc2bef"], "d": ["The Russians had taken Özi on 11 July 1737. Under the peace made with Russia in 1739, the fortress was handed back to the Ottomans after its fortifications had been demolished; the Ottomans held Özi until 1788, before the Treaty of Jassy.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["The Defence of Mosul — The Repulse of Nadir Shah", "c03ffbc1"], "d": ["Nadir Shah, who came before Mosul after taking Kirkuk and Erbil, bombarded the city for forty days and mounted successive general assaults. The defence conducted by the governor Hüseyin Pasha al-Jalili, who also armed the townspeople, compelled the Iranian army to lift the siege with heavy losses. Mosul's holding out prevented the loss of the whole of Iraq and consolidated the influence of the Jalili family in the city for a century.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["The Diriyah Alliance — The Founding of the First Saudi Emirate in Najd", "188751bf"], "d": ["The emir Muhammad b. Saud, who took under his protection in Diriyah the scholar Muhammad b. Abd al-Wahhab, expelled from Uyaynah, formed with him an alliance that placed political authority at the service of the religious call. This agreement began a new history for the Saud family and united the scattered oasis emirates of Najd around a single movement. This power, which within half a century would extend to Karbala, Mecca and Medina, would force the Ottoman State to defend its dominion in the Hijaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["The Treaty of Kerden — The End of the Ottoman-Iranian Wars", "1d3a919e"], "d": ["By the treaty signed after the last war, lasting four years, the Qasr-i Shirin frontier of 1639 was renewed exactly; neither side obtained a territorial gain. Nadir Shah's insistent demand that Jafarism be recognised as a fifth school of law went unanswered; in return it was decided that Iranian pilgrims would perform the pilgrimage freely and that envoys would be exchanged. The Ottoman-Iranian wars, which had lasted more than two centuries, were thus effectively closed; this frontier has been largely preserved to the present day.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["The Death of Mahmud I and the Accession of Osman III", "30203700"], "d": ["Mahmud I, who in his reign of twenty-four years had recovered the lands lost by the Treaty of Belgrade and supported the reform of the Humbaracı Corps, died while returning from the Friday selamlık. He was succeeded by his brother Osman III, who had lived the life of the cage until the age of fifty-eight. A short and uneasy reign began; in the period of Osman III, who changed six grand viziers in three years, a marked stagnation prevailed in the affairs of state.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["The Death of Osman III and the Accession of Mustafa III", "3ac10f85"], "d": ["With the death of Osman III after a reign of three years, Mustafa III, who was open to ideas of reform and showed close interest in the affairs of state, came to the throne. The new sultan, relying on the experience of the Grand Vizier Koca Râgıb Pasha, tried to set the finances right and renew the army; Baron de Tott's rapid-fire artillerymen were established in this period. However, the Russian war entered in 1768 would overshadow all the achievements of the seventeen-year reign.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["The Declaration of War on Russia — The Balta Incident and the Beginning of the War of 1768-1774", "9c6aabe0"], "d": ["When Russian and Cossack units pursuing the Bar Confederation in Poland raided and burned the town of Balta on the Ottoman frontier, the Divan took the decision for war, and the Russian envoy was imprisoned in Yedikule. The war, entered without serious military preparation and declared six months in advance, went badly from the very start. This struggle, which would last six years, would turn, with the raid on Çeşme, the defeat at Kartal and the occupation of Crimea, into one of the heaviest series of defeats in Ottoman history.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["The Loss of the Fortress of Khotin to the Russians", "66d43ea4"], "d": ["Although two attempts by the Russian army under Prince Golitsyn had been repulsed, the army withdrew upon the defeat the grand vizier suffered between Kamaniçe and Khotin, and the garrison evacuated the fortress. The loss without resistance of the strongest Ottoman fortification north of the Danube opened the gates of Wallachia and Moldavia to the Russians. The two principalities were occupied in the same year; Khotin could be recovered only in 1774 by the Treaty of Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["The Defeat on the Plain of Kartal (Kagul)", "6f408eaf"], "d": ["Three weeks after the burning of the fleet at Çeşme, the main Ottoman army on the Danube was dispersed on the plain of Kartal before the far smaller but disciplined units of Field Marshal Rumyantsev. The camp, the baggage and hundreds of cannon fell into enemy hands; the fleeing units suffered great losses while crossing the Danube. The destruction within the same summer of both the fleet and the land army led to the falling one after another of Kili, Akkerman, Ismail and Bender and to the occupation of Crimea.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["The Russian Occupation of the Crimean Peninsula", "217837b0"], "d": ["The Russian armies, which had seized Bucak a year earlier, crossed Or Kapı (Perekop) under the command of Prince Dolgorukov and invaded the whole of the Crimean peninsula. The khan was deposed and the pro-Russian Sahib Giray was put at the head, taking the first step toward severing the khanate from the Ottomans. The loss of Crimea, for three centuries the northern shield of the Ottomans, was the beginning of the process of independence in 1774 and of direct annexation in 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["The Death of Mustafa III and the Accession of Abdülhamid I", "42cba8e2"], "d": ["In place of Mustafa III, who died at the most critical moment of the Russian war, his brother Abdülhamid I, who had spent forty-three years in the cage of the palace, ascended the throne at the age of forty-nine. The new sultan, who took over one of the most difficult periods of the state, was obliged to face the heavy terms of the Treaty of Küçük Kaynarca to be signed in the same year. His reign of fifteen years would pass with the loss of Crimea and a new Russian war, and would end with the stroke he suffered while reading the news of the fall of Özi in 1789.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["The Defeat at Kozludzha — The Defeat Leading to Küçük Kaynarca", "8e0542f9"], "d": ["The Ottoman forces gathered before Shumla were defeated at Kozludzha by the combined columns of Suvorov and Kamensky, and the greater part of the army was dispersed. With this defeat there was no force left to resist in the Balkans; the Russian vanguards besieged Shumla and the grand vizier's headquarters came under threat. The sitting down at the table at Küçük Kaynarca and the acceptance of extraordinarily heavy terms before a month had passed are a direct result of this defeat.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["The Ceding of Bukovina (Northern Moldavia) to Austria", "190f9caa"], "d": ["Exploiting the weakness caused by Küçük Kaynarca, Austria demanded Bukovina, the region linking Moldavia and Transylvania, and obtained this land without going to war, through threats and bribery. The loss of this fertile and strategic region southwest of Hotin effectively split the voivodeship of Moldavia in two. This cession, made without a single shot being fired, was regarded as one of the clearest signs that the Ottoman State had lost its deterrent power. With the cession of Bukovina in 1775, Suceava and Czernowitz passed to Austria (day unconfirmed).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["The Iranian Occupation of Basra", "0161e709"], "d": ["Sadiq Khan, the brother of the Zand ruler Karim Khan, captured Basra after a siege lasting a year, and the Ottoman State lost its most important port on the Gulf of Basra. The occupation directly shook the Indian trade route, the date and pearl revenues, and the southern defence of Iraq. The city could be retaken only in 1779, during the struggles for the throne that broke out in Iran with the death of Karim Khan.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["The Aynalıkavak Tenkihnâme — A Provisional Settlement over Crimea", "9b3b0468"], "d": ["The two states, brought to the brink of war over who would take the head of the Crimean khanate, signed an explanatory text at the Aynalıkavak Pavilion through the mediation of France. Russia agreed to withdraw its troops from Crimea, and the Ottoman State to recognise the khanate of the pro-Russian Şahin Giray; the sultan's religious right of caliphate over Crimea was confirmed. This fragile balance, which would last four years, would collapse completely with Russia's direct annexation of the peninsula in 1783.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["The construction of the fortress of Anapa — the Caucasus defence line", "be92a80f"], "d": ["When Crimea was lost with Küçük Kaynarca, the construction of a new fortress at the mouth of the Kuban River was undertaken in order to preserve Ottoman influence in the Caucasus. Anapa, founded on the remains of a Genoese colony, with its bazaar, its baths and its more than two hundred and fifty shops, soon became a city that provided the link with the Circassian tribes. The fortress remained for forty-eight years the Ottomans' most advanced outpost against Russia's descent into the Caucasus.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["The dismissal and execution of Grand Vizier Halil Hamid Pasha", "c44001ca"], "d": ["Halil Hamid Pasha, the reformist grand vizier with whose services Abdülhamid I had on various occasions expressed his satisfaction, was suddenly dismissed toward the morning of 31 March 1785 and exiled to Gallipoli, and all his property was confiscated. He was first given the province of Habeş, the sancak of Jeddah and the şeyhülharemlik of Mecca; while spending April 1785 on Tenedos making preparations for the journey, he was also dismissed from this governorship, and on the death decree that was issued he was killed by Karakethüdâzâde Ali, one of the men of Cezayirli Gazi Hasan Pasha. His severed head was sent to Istanbul and displayed at the Ortakapı. According to the TDV, although this sudden fall has been interpreted with the accusation of a plot to depose the sultan and put Prince Selim in his place, the real causes must have been the outrage at his silence over the annexation of Crimea, the hostility of the circles injured by his reforms, and the opposition of Gazi Hasan Pasha.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["The Declaration of War on Russia — The Ottoman-Russian War of 1787-1792 Began", "3bfb870c"], "d": ["After Catherine II's ostentatious journey to Crimea and her taking Georgia under her protection, the Divan took the decision for war with the aim of reversing the annexation, and the Russian envoy was again shut up in Yedikule. However, the army was not ready, the treasury was empty, and the search for allies had been fruitless. The war, which would last five years, would end with the fall of Özi through a massacre, the loss of Ismail and the heavy terms of the Treaty of Jassy.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Austria's Entry into the War — A Struggle on Two Fronts", "ae912290"], "d": ["In accordance with the secret alliance he had made with Russia in 1781, the Austrian emperor Joseph II declared war on the Ottoman State and moved in the direction of Belgrade and Bosnia. The Ottoman army was suddenly obliged to fight on two fronts at once, Russia in the north and Austria in the west. Despite the victories won against the Austrians at Lazarethane, Mehadia and Șebeș, the western front too would collapse with the loss of Belgrade in 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["The Ottoman-Prussian Alliance", "03b88e51"], "d": ["Selim III, who sought allies in Europe as soon as he came to the throne, signed with Prussia an alliance treaty envisaging mutual assistance; Prussia undertook to declare war on Russia and Austria, and the Ottoman State to make no peace until Crimea was recovered. This was the first real text of mutual alliance signed with a European state in Ottoman history and showed that the classical notion of 'no alliance with the infidels' had been abandoned. Prussia did not enter the war, but by forcing Austria to peace it paved the way for the Treaty of Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["The Fall and Massacre of the Fortress of Ismail", "6a296b0c"], "d": ["The Fortress of Ismail, regarded as the strongest fortification of the Danube delta, was taken in a single day by a bloody general assault mounted by General Suvorov; the garrison and the townspeople were for the most part put to the sword. This massacre, which aroused wide repercussions in Europe, created a deep shock in Ottoman public opinion and broke the backbone of the Danube defence line. The fortress would be recovered a year later by the Treaty of Jassy, but the fate of the war would already have been determined.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["The Treaty of Sistova — The Closing of the Austrian Front", "58741f1d"], "d": ["Thanks to Prussian pressure and the French Revolution's occupying Austria in the west, the two states reached peace on the basis of the pre-war frontiers. Austria gave back all the places it had occupied, including Belgrade; the Ottoman State accepted only minor adjustments on the Croatian frontier. The closing of the western front on these terms enabled the Ottoman State to concentrate all its strength against Russia and limited the loss at the Treaty of Jassy.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["The Treaty of Jassy — The Definitive Loss of Crimea and the Turla Frontier", "a56fd194"], "d": ["By the treaty signed at the end of the five-year war, the Turla (Dniester) river was accepted as the frontier; the left bank of the river was left to Russia and the right bank to the Ottomans, and Özi and its surroundings were definitively lost. The Ottoman State abandoned entirely the hope of recovering Crimea and legally recognised the annexation of 1783; Wallachia and Moldavia were returned with a two-year tax exemption. With the acceptance also of the obligation of a war indemnity of twelve million kuruş, the north of the Black Sea was permanently ceded to Russia. Other places that joined on the same date: Ismail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["The evacuation of Oran by the Spanish and its transfer to Algiers", "9f95cee6"], "d": ["When the fortress and the city were largely destroyed in the earthquake of 1790, Spain, which could no longer bear the costly garrison it had maintained for three centuries, came to an agreement with the Algiers ocak and handed over Oran and Mers el-Kébir without a war. Thus the last European position on the North African coast was also liquidated. Ottoman Algiers remained master of the whole coast for the thirty-eight years that would pass until the French occupation.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["The De Facto Rule of Pazvandoğlu Osman at Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, who rose against the Nizam-ı Cedid arrangements, made the governor of Vidin flee, seized the city and fortified it with deep trenches along the Danube. In 1797, at the peak of his power, he gathered a force of nearly eighty thousand and brought Nikopol, Sistova, Rusçuk, Sofia and Niš under his control; he presented himself not as a rebel but as a reformer. The Sublime Porte's siege of 1798-1799, lasting months, was fruitless, and until his death in 1807 he ruled in Northern Bulgaria in a semi-independent manner.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["The Opening of the Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["A land engineering school was opened at Hasköy to train artillery, fortification and map-making officers for the Nizam-ı Cedid army; it was the land-army counterpart of the Naval Engineering School founded in 1773. In the programme algebra, geometry, mechanics, fortification and ballistics were taught, and mathematics and gunnery books were translated from European languages. This school, regarded as the root of modern engineering education in Turkey, is accepted as the beginning of today's Istanbul Technical University.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["The Declaration of War on France and the Alliance with Russia and England", "80e95bd7"], "d": ["Upon Napoleon's occupation of Egypt, the Ottoman State broke the traditional French friendship of two and a half centuries and declared war on France. In the same process it made an alliance with Russia for the first time in its history and allowed the Russian fleet to pass through the Straits into the Mediterranean; an alliance with England was then also signed. Thanks to these alliances the Ionian Islands were taken from the French, but the opening of the Straits to a foreign fleet created a precedent with a heavy price in the future.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["The taking of Preveza from the French — the Battle of Nikopolis", "d8e5e892"], "d": ["When the Republic of Venice was destroyed in 1797, the Ionian islands and Preveza, Parga and Vonitsa on the mainland passed into French hands. Ali Pasha of Tepelena, governor of Ioannina, taking advantage of the war opened by the French occupation of Egypt, marched on Preveza and inflicted a heavy defeat on the French garrison at the ruins of Nikopolis outside the city. Thus this port, which had been left to Venice at Passarowitz, came under Ottoman administration eighty years later.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["The Defence of Acre — The Repulse of Napoleon", "56b5c45b"], "d": ["Napoleon, advancing from Egypt to Syria, besieged Acre and mounted successive assaults for two months; the city was defended by Cezzâr Ahmed Pasha, with the support of the English fleet and Nizam-ı Cedid units sent from Istanbul. Napoleon, who was obliged to lift the siege and withdraw to Egypt, buried his dream of reaching toward the east before these walls. The news was met in Istanbul with great joy and was regarded as proof that the newly formed trained army had passed its first serious test.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["The Wahhabi Raid on Karbala", "522341ed"], "d": ["Wahhabi forces rising from Najd entered Karbala, plundered the city, destroyed the tomb of Imam Husayn and killed more than three thousand people. The kölemen governors of the Ottoman State in Iraq were unable to prevent the raid; the event aroused great reaction both in Iran and in Istanbul. This attack was the declaration that the Saudi movement had ceased to be an oasis emirate and had become a regional power threatening the holy cities of the Ottomans.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kakheti (Eastern Georgia) annexed to Russia", "3b650c5e"], "d": ["The kingdom of Kartli-Kakheti, which had accepted Russian protection in 1783 and suffered Iran's devastating campaign in 1795, was dissolved; by an order dated 12 September 1801 it was declared a province of Russia, and the Russian administrative system began to be installed. From this date Georgia lost its independence; within a few years Mingrelia (1803), Imereti and Guria (1804) also came under Russian domination, and Russia reached the Ottoman frontier in the Caucasus.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["The Evacuation of Egypt by the French", "00cfdc8c"], "d": ["As a result of the joint operation of Ottoman and English forces by land and sea, first Cairo and then Alexandria were taken over, and the French forces were sent to their country by ship. As the occupation, lasting three years, ended, Egypt returned to Ottoman administration on paper, but the struggle for dominance between the kölemen beys and the Albanian units dragged the country into chaos. This vacuum would prepare the ground, within a few years, for the rise of Mehmed Ali of Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["The Treaty of Paris — The Re-establishment of Peace with France", "1b76991f"], "d": ["By the treaty signed after the evacuation of Egypt, the state of war between the Ottoman State and France officially ended and the old capitulations were renewed. French merchant ships were permitted to enter the Black Sea; in return France recognised the territorial integrity of the Ottomans. The establishment of peace gave room for manoeuvre again to the foreign policy of Selim III, which had been squeezed between Russia and England.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["The Wahhabi Capture of Taif", "7b791359"], "d": ["The Wahhabi forces under Saud b. Abd al-Aziz, in their first move toward the Hijaz, besieged and plundered Taif; the city fell as the first gate opening onto the holy lands. For the Ottoman sultan, who bore the title of protector of the Haramayn, this was a blow that directly shook the legitimacy of the sultanate. Two and a half months later the same army would march on Mecca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["The First Wahhabi Capture of Mecca", "21157c05"], "d": ["Two and a half months after the fall of Taif, the Wahhabi forces entered Mecca, destroyed the tombs and established an order according to their own understanding; Sharif Ghalib was forced to withdraw to Jeddah. The closing of the pilgrimage routes echoed throughout the Islamic world and obliged Istanbul to ask the governor of Egypt, Mehmed Ali, for military aid. This first dominion would last only three months.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Sharif Ghalib's Retaking of Mecca", "83d08dff"], "d": ["Sharif Ghalib, who had withdrawn to Jeddah, besieged Mecca with the forces he had gathered and, after a siege of twenty-five days, retook the city from the Wahhabis; the khutba was again read in the name of the Ottomans. This second dominion too would not be lasting; the Saudi forces would take the city again in 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["The Beginning of the First Serbian Uprising", "0f6e8767"], "d": ["When the rebel Janissary dahis who had seized the administration in Belgrade massacred the Serbian notables en masse, an armed resistance began under the leadership of Karađorđe (Kara Yorgi). The movement, which at first remained loyal to the sultan and was directed only against the dahis, soon turned into a national rebellion demanding autonomy and independence. The Serbian forces captured Belgrade in 1806; this uprising became the first link of the nationalist independence movements in the Balkans.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["The Wahhabi Occupation of Medina", "84e310d7"], "d": ["After Mecca, Medina too fell into the hands of the Wahhabi forces; the treasury of the Rawda-i Mutahhara was dispersed and the domed tombs in the city were destroyed. Thus both holy cities left Ottoman control at once, and the pilgrim caravans from Damascus and Egypt were unable to set out for years. Medina could be retaken only seven years later, in 1812, by the Egyptian army under Tosun Pasha, the son of Mehmed Ali Pasha.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["The Beginning of the War with Russia (the Ottoman-Russian War of 1806-1812) and the Closing of the Straits", "ea170804"], "d": ["When Selim III, who had drawn closer to France after Napoleon's victory at Austerlitz, dismissed the voivodes of Wallachia and Moldavia despite Russian pressure, Russian armies occupied the two principalities and war began. The Ottoman State closed the Straits to the Russian fleet; in response England too took Russia's side and sent a fleet to Istanbul. This war, which would last six years, interwoven with the Kabakçı Rebellion and the deposition of Selim III, would end with the loss of Bessarabia in the 1812 Treaty of Bucharest.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["The Coming of the English Fleet before Istanbul (the Duckworth Operation)", "195bb58f"], "d": ["England, wishing to force the Ottoman State to break its tie with France, passed the fleet under Admiral Duckworth through the Dardanelles and anchored it before Istanbul. With the direction also of the French ambassador Sébastiani, the people of Istanbul mobilised, the coastal batteries were reinforced within days, and the fleet was obliged to withdraw before the city could be bombarded; on the return it suffered heavy losses at the Dardanelles. The capital's being threatened so closely by a foreign fleet for the first time placed the question of the Straits at the centre of European diplomacy.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["The strangling of Mustafa IV", "eeb75c20"], "d": ["When Alemdar Mustafa Pasha was attacked and died and the rebels wished to march on the palace, the deposed Mustafa IV was strangled on the order of his brother Mahmud II. His body was buried at Bahçekapı in the tomb of his father, Abdülhamid I; a rumour spread among the rebels that the coffin was empty.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["The Treaty of Kal'a-i Sultâniyye — Peace with England and the Rule of the Straits", "fe282117"], "d": ["By the treaty signed with England after the failure of the Duckworth operation, the war between the two states ended and the old privileges of English merchants were restored. The provision in the text called the 'ancient rule' recorded that in peacetime no foreign warship could pass through the Straits. This principle became the legal basis of all the international arrangements that would shape the regime of the Straits throughout the nineteenth century.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["The Defeat at Slobozia — The Encirclement of the Danube Army", "54b60fd1"], "d": ["The greater part of the Ottoman army that crossed the Danube before Rusçuk was hemmed in at Slobozia by Kutuzov's encircling manoeuvre from the opposite bank of the river and left to starve. Thousands of soldiers were obliged to surrender; the force in the grand vizier's hands effectively melted away, and the Sublime Porte was obliged to ask for an armistice a month later. This defeat is the direct reason for the acceptance of the ceding of Bessarabia in the 1812 Treaty of Bucharest.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["The Retaking of Belgrade and the Suppression of the First Serbian Uprising", "06f56f52"], "d": ["The Serbian rebels, deprived of Russian support by the Treaty of Bucharest, could not hold out against the joint operation of forces coming from Bosnia and Rumelia; Hurşid Ahmed Pasha entered Belgrade and the nine-year uprising was completely suppressed. Karađorđe fled to Austria, and the sancak of Smederevo was again attached directly to Ottoman administration. However, the harsh measures applied would trigger a second and lasting rebellion two years later under the leadership of Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["The Second Serbian Uprising and Miloš Obrenović's Princeship (Başknez)", "e6e82ad2"], "d": ["Against the heavy measures applied after the suppression of the first uprising, a new rebellion broke out under the leadership of Miloš Obrenović; this time the Sublime Porte preferred settlement to force. By the agreement made, Miloš was recognised with the title of 'başknez' (chief knez), and the authority to collect taxes and conduct internal affairs was left to the Serbian knezes. This first nucleus of de facto autonomy became the starting point of the process extending to the firman of 1830 and independence in 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["The Wallachian Uprising — Ypsilantis's Crossing of the Prut and the Vladimirescu Revolt", "67d46a98"], "d": ["Alexander Ypsilantis, a general in the Russian army, crossed the Prut on behalf of the Filiki Eteria and tried to begin a general Greek uprising in Wallachia and Moldavia; in the same days Tudor Vladimirescu also set the local peasants in motion. The two movements could not unite: Vladimirescu answered Ypsilantis's call to fight the Turks together with 'I did not rise against the Turks but against the Greeks', and was soon killed by Ypsilantis's men. The uprising was suppressed by Ottoman forces in May, but the Phanariot voivodeship order came to an end and the flame of revolt spread to the Morea.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["The Founding of the Second Saudi State at Riyadh", "34dad3bd"], "d": ["Six years after the fall of Diriyah in 1818 and the destruction of the first Saudi State, Turki b. Abdullah expelled the Egyptian garrisons from Najd and founded a new Saudi emirate centred on Riyadh. The new structure avoided extending to the Hijaz, preferring to remain in Najd, and kept away from direct clashes with the Ottoman-Egyptian forces. This second state would last until the end of the century and would form the second link of the chain leading to the founding of present-day Saudi Arabia. Other settlements lost on the same date: Diriyah (Najd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["The Akkerman Convention — Concessions to Serbia and the Principalities", "c75f15d0"], "d": ["The Ottoman State, left without an army immediately after the abolition of the Janissary Corps, was obliged to accept an agreement with heavy terms in the face of Russia's ultimatum. The autonomy promised to Serbia was confirmed, it was accepted that the voivodes of Wallachia and Moldavia could not be dismissed without Russian approval, and Russian merchant ships were granted complete freedom in the Straits. When the Sublime Porte declared two years later, over the Greek question, that it did not recognise the agreement, Russia would regard this as a ground for war.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["The Liquidation of the Timar System", "84d5d1d6"], "d": ["One year after the abolition of the Janissary Corps, about 5,200 timar-holding sipahis in fifty-three sancaks in Rumelia and Anatolia were converted, together with their timar revenues, into cavalry of the Asâkir-i Mansûre. Thus the timar regime, the four-century backbone of the Ottoman order of land, taxation and army, effectively came to an end. The vacated timars were transferred to the treasury, and the way was opened to the transition to a centrally salaried army and a cash tax system.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["The Founding of the Tıphâne-i Âmire — The Beginning of Modern Medical Education", "ac3e57c0"], "d": ["To train physicians and surgeons for the newly formed army of the Asâkir-i Mansûre, the Tıphâne-i Âmire was opened at Şehzadebaşı on the proposal of the chief physician (hekimbaşı) Mustafa Behçet Efendi. The lessons were arranged according to the curriculum in Europe, and instruction was at first given in French; a few years later the Cerrahhâne-i Âmire was also established and the two institutions were merged. This school, regarded as the beginning of modern medical teaching in Turkey, is accepted as the origin of today's Istanbul Faculty of Medicine.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["The Beginning of the Ottoman-Russian War of 1828-1829", "9dff4e05"], "d": ["Upon the burning of the fleet at Navarino and the Sublime Porte's declaration that it did not recognise the Akkerman Convention, Russia declared war on two fronts at once. Since the Janissary Corps had only just been abolished and the new army was still in the process of being formed, the Ottoman defence was weak from the start; as the Russians crossed the Danube, they took Kars and Akhaltsikhe in the east. The Russian army, which within a year advanced as far as Edirne, would impose the heavy terms of the 1829 Treaty of Edirne and the independence of Greece.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["The First Treaty with the United States of America", "d737516f"], "d": ["By the treaty of commerce and navigation signed after years of contacts, the United States obtained in the Ottoman lands the status of most favoured nation and the right of commercial passage through the Straits. A separate secret article envisaged that the Ottomans, whenever they wished, would have ships built in American shipyards and buy ready-made ships and timber; the United States Senate ratified the treaty but rejected this secret article by 27 votes to 18. The ship route was nonetheless not closed: Henry Eckford sold to the Ottomans in 1831 the ship he had brought, and American craftsmen working at Aynalıkavak gave the fleet new types of ships. This treaty became the document of the first comprehensive relationship the Ottoman State established with a state outside Europe.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["The End of Kölemen Rule in Baghdad", "7e1d38a3"], "d": ["Mahmud II, who pursued a policy of centralisation, declared the governor of Baghdad, Dâvud Pasha, who did not send the money demanded and had the official sent from the centre killed, a rebel. The force under Ali Rızâ Pasha captured the city after a siege lasting ninety days, and nearly all the kölemens were purged. Thus the semi-independent Kölemen administration that had lasted since 1704 came to an end and Iraq was again attached directly to the centre.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["The Founding of the Mekteb-i Harbiye at the Maçka Barracks", "bf31c7d9"], "d": ["The Mekteb-i Fünûn-ı Harbiyye was opened at the Maçka Barracks to provide the Asâkir-i Mansûre-i Muhammediyye with officers trained in the European manner. The students were taught mathematics, mapmaking, fortification and foreign languages; soon students were sent to Vienna and Paris and the cadre strengthened. This school became the place where the tradition of school-trained officers in the Ottoman army, and hence the new soldier-intellectual generation that would emerge at the end of the nineteenth century, was born.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["The Attachment of Tripolitania Directly to the Centre — The End of the Karamanli Dynasty", "faabcb96"], "d": ["Following the struggles for the throne within the Karamanlı family and the European pressure that increased after France's occupation of Algiers in 1830, the Sublime Porte intervened directly in Tripolitania. The fleet sent from Istanbul entered the city, the last Karamanlı bey was dismissed and brought to Istanbul, and the province was handed over to a governor appointed from the centre. As the dynastic period of 124 years ended, the last piece of land in North Africa directly administered by the Ottoman State was consolidated.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["The Abolition of the Defterdarlık and the Founding of the Maliye Nezâreti", "89f8125e"], "d": ["The office of defterdar, the head of the classical Ottoman financial order, was abolished, the Maliye Nezâreti (Ministry of Finance), a ministry in the European fashion, was established, and the scattered treasuries were gathered into one hand. In the same year the other units of the Sublime Porte were also reorganised under the name of nezâret, and a transition was made to the structure of a modern council of ministers. This arrangement was one of the most important steps preparing the administrative infrastructure of the Tanzimat Edict to be proclaimed a year later.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["The Settlement of the British at Aden", "ddbd556b"], "d": ["England, relying on the trade and friendship agreement it had signed in 1802 with the sultan of Lahej, Ahmed b. Abd al-Karim, landed troops at the port of Aden and took the city under its control. This port, holding the mouth of the Red Sea, turned into a key point of British imperial strategy as the coaling base on the route to India. Although the Ottoman State's claim over Yemen continued on paper, its de facto dominion on the southern coast never returned after this date.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["The Return to the Tihama Coast: The Taking of Hodeida, Zabid and Mocha", "353982d2"], "d": ["Forces under Tevfik Pasha, under the supervision of the sharif of Mecca, landed on the Yemeni coast, left ownerless by the withdrawal of the Egyptian army in 1840, and attached the ports of Hodeida, Zabid and Mocha to Ottoman administration. Although it was wished to advance as far as Sana'a, the forces returned to Hodeida because of the resistance of the people; thus the highlands remained with the Zaydi imams, and Ottoman dominion continued for twenty-three years only in the Tihama strip. Inner Yemen would be retaken only in 1872 by the campaign of Ahmed Muhtar Pasha.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["The Convention of Balta Liman: A Joint Ottoman-Russian Protectorate in Wallachia and Moldavia", "d3bb22e9"], "d": ["When the revolutions of 1848 spread to Wallachia and Moldavia, Ottoman and Russian forces had jointly occupied the principalities. By the convention signed at Balta Liman it was decided that the voivodes would be appointed by the sultan for seven years rather than elected, and that the two states would establish joint control in the region. While preserving Ottoman sovereignty on paper, the agreement granted Russia a de facto right of partnership and hastened the severing of the Danubian principalities from the Ottomans.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["The Question of the Hungarian Refugees: The Taking of Refuge in the Ottoman Lands by Kossuth and His Companions", "1c7d7ef4"], "d": ["When the Hungarian revolution of 1848-1849 was suppressed by Russian and Austrian intervention, Lajos Kossuth and thousands of Hungarian and Polish refugees took refuge in Ottoman territory. Austria and Russia sternly demanded the extradition of the refugees; the Sublime Porte, with the support of England and France, refused extradition and settled the group at Kütahya. Kossuth's circle stayed there for about eighteen months, and hundreds of refugees became Muslims and entered Ottoman service. The event was regarded as one of the rare diplomatic victories that raised the standing of the Tanzimat Ottoman Empire in European public opinion.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["The Founding of the Encümen-i Dâniş: The First Ottoman Academy in Istanbul", "6fda1365"], "d": ["The Encümen-i Dâniş, founded by decision of the Meclis-i Maârif-i Umûmiyye, was the first Ottoman scientific academy, formed to prepare scholarly and textbooks in Turkish. It was opened with a ceremony on 18 July 1851 in the building of the Dârülmaârif; among its native and foreign members was Ahmed Cevdet Pasha. Although short-lived, works such as Cevdet Pasha's Târih and Kavâid-i Osmâniyye were products of this institution, and it is regarded as a cornerstone in Turkish's becoming a language of scholarship.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["The Victory of Oltenița: The First Ottoman Success on the Danube Front", "a660ad2f"], "d": ["In the opening phase of the Crimean War, the Serdâr-ı Ekrem Ömer Lütfi Pasha crossed the Danube and repulsed the Russian forces at Oltenița with heavy losses. By halting the Russian advance at the very beginning of the war, the victory showed Europe the strength the Ottoman army had gained through post-Tanzimat training. This success prepared the psychological ground that eased the decision of England and France to enter the war on the Ottoman side.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["The Alliance Treaty with England and France in Istanbul", "04809278"], "d": ["The alliance treaty signed in the Crimean War against Russia between the Ottoman State and England and France stipulated that the three states would conduct joint operations and that the allies would make no separate peace before the war ended. Thus the Ottoman State entered, for the first time in its history, into a military alliance with the great European states as an equal party. This treaty also formed the legal basis for the Ottomans' official admission to the European system of states in Paris two years later.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["The Founding of the Istanbul Şehremaneti: The First Modern Municipal Organisation", "be4af27f"], "d": ["The infrastructure crisis created by the allied soldiers massed in Istanbul during the Crimean War and by the growing population exposed the inadequacy of the classical city administration centred on the kadi. With the Şehremaneti, established on European models, cleaning, price controls (narh), market supervision and building works were gathered into one hand; the following year the Sixth Municipal District (Altıncı Daire-i Belediye) was formed in Beyoğlu-Galata as a pilot region. This step is accepted as the beginning of modern municipal government in the Ottoman Empire.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["The Treaty of Paris: The End of the Crimean War and the Ottomans' Admission to the European System of States", "4aee0e2a"], "d": ["With the Treaty of Paris, which ended the Crimean War, the Ottoman State was declared an equal member of European public law and its territorial integrity was placed under the joint guarantee of the great powers. The Black Sea was neutralised, Russia's claim of protection over Orthodox subjects, which it had held since Küçük Kaynarca, was invalidated, and the south of Bessarabia (the kazas of Kilia, Cahul, Ismail and Bolgrad) was given to Moldavia. However, by making the Reform Edict an international commitment, the same treaty also opened the door to interference in internal affairs.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["The Opening of the Dolmabahçe Palace: The Moving of the Administrative Centre from Topkapı", "71ad26d0"], "d": ["The palace that Abdülmecid had commissioned from the Balyan family in 1842 was opened after fourteen years of construction, and the administrative centre of the state was moved from the four-century-old Topkapı to the shore of the Bosphorus. With its European style, crystal staircase and Muayede Hall, the palace became the expression in stone of the Tanzimat's claim to Westernisation. Its enormous cost became one of the most criticised items of the years in which Ottoman finance entered the spiral of foreign borrowing.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["The Union of Wallachia and Moldavia under Cuza: The Birth of Romania", "baef4da5"], "d": ["In the elections held after the Treaty of Paris, both principalities elected Colonel Alexandru Ioan Cuza as voivode and thus realised a de facto union. Although the Sublime Porte and Austria opposed it, the fait accompli, supported by France, had to be accepted. This union, which remained attached to the Ottomans on paper, would take the name Romania in 1862 and declare its unilateral independence in 1877; it is a turning point in the dissolution of Ottoman dominion on the Danube.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["The Kuleli Incident: The First Coup Attempt against Abdülmecid in Istanbul", "e3653b21"], "d": ["A secret society of mixed military and civilian membership, reacting against the Tanzimat policy and the equality that the Reform Edict granted to non-Muslims, was raided in a meeting at the Kılıç Ali Pasha Mosque while it was planning to depose the sultan. The event was named after the Kuleli Barracks, where the accused were tried; the death sentences were commuted to exile. It is accepted as the first palace coup attempt in Ottoman history undertaken by an organisation founded on ideological grounds.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["The Druze-Maronite Civil War in Mount Lebanon and the Damascus Events", "5595fdd6"], "d": ["The clashes that erupted in May 1860 with the killing of two Druze near Sidon turned into the bloodiest Druze-Maronite civil war in the mountain and spread to Damascus in July, resulting in the deaths of thousands of Christians. Upon France's landing of troops, the Sublime Porte sent Fuad Pasha to the region with extraordinary powers; a harsh punitive operation was conducted. The events provided a pretext for European intervention and were the direct reason for Lebanon's acquiring a special status.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["The Beginning of Publication of Tercümân-ı Ahvâl: The First Private Turkish Newspaper in Istanbul", "24792957"], "d": ["Tercümân-ı Ahvâl, published by Agâh Efendi with Şinâsi taking on the editorial work, is the first Turkish newspaper published without state support. In the preface of its first issue the people's right to speak about their own affairs was defended, and by serialising Şinâsi's Şair Evlenmesi the newspaper also opened the door to modern Turkish literature. The birth of the concept of public opinion and of the opposition press in the Ottoman Empire is traced to this date.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["The Statute of Mount Lebanon: The Status of a Privileged Mutasarrıflık for Lebanon", "bf375603"], "d": ["The statute, prepared under the pressure of the great powers after the massacres of 1860, made Mount Lebanon a privileged mutasarrıflık directly attached to the Sublime Porte and governed by an administrative council set up according to the balance between the sects. It was stipulated that the mutasarrıf must be an Ottoman subject and a Catholic Christian and that his appointment be submitted to the approval of the great powers; the first mutasarrıf was Dâvud Pasha. This order would last until 1915 and would form the nucleus of the modern Lebanese state.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["The Death of Abdülmecid and the Accession of Sultan Abdülaziz", "27204d7c"], "d": ["Upon the death from tuberculosis of Abdülmecid, who in his reign of twenty-two years had put his signature to the Tanzimat and Reform edicts, his brother Abdülaziz ascended the throne. In the first years the new sultan gave hope with measures of economy and his simple way of living; he made the navy one of the few leading naval powers in the world. However, towards the end of his reign the heavy foreign debt, the bankruptcy of 1875 and the Balkan rebellions accumulated and prepared the ground for the deposition movement of 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["The Taking of the Name Romania by the United Principalities", "d960e3fc"], "d": ["Wallachia and Moldavia, which had effectively united through the double election of Cuza in 1859, gathered their assemblies and governments under a single roof in Bucharest in 1862 and officially took the name Romania. Although the Ottoman State legally retained the status of suzerain and the annual tribute, it effectively lost its control over the principality. The end of four centuries of Ottoman influence north of the Danube is symbolised by this date.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["The Attachment of Suakin, Massawa and Dahlak to Egypt", "a0924860"], "d": ["Massawa, which in 1846 had been given by Sultan Abdülmecid to the Khedive of Egypt Mehmed Ali Pasha together with Suakin as sâlyâne (a revenue allocation), was incorporated in the time of the Khedive Ismail Pasha, together with Dahlak and Suakin, into the Egyptian possessions and organised with the status of a kaymakamlık. Thus these three ports on the African shore of the Red Sea, while legally remaining Ottoman territory, passed administratively from the Sublime Porte directly to Cairo — they entered the same vassal tier as their neighbours Egypt and Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["The Beginning of the Cretan Revolt (1866-1869)", "3679b861"], "d": ["The wide-ranging uprising that broke out on the island with the open support of Greece turned the demand of the Cretan Greeks for enosis (union with Greece) into an international question for the first time. The hard mountain war, lasting three years, inflicted heavy losses on the Ottoman army and aroused great repercussions in European public opinion. The revolt could be put out only in 1868, when Âlî Pasha went to the island and put into force a statute granting broad privileges.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["The Withdrawal of the Last Ottoman Garrisons from the Fortresses of Belgrade and Serbia", "b34217db"], "d": ["Upon the pressure of the great powers and the insistent demand of Prince Mihailo, the Sublime Porte consented to evacuate the last military bases remaining in its hands in Serbia; on 18 April 1867 the Ottoman standard at the Fortress of Belgrade was lowered and the keys were handed to the prince. Thus the de facto Ottoman military presence that had continued since 1521 ended, and the last great obstacle on Serbia's road to independence was removed. The sultan's suzerainty was reduced to a matter of merely a symbolic flag and tribute.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["The Granting of the Title of Khedive to the Governors of Egypt", "09e10c12"], "d": ["As a result of the intense lobbying of Ismail Pasha, of the third generation of the Kavala dynasty, and the money he channelled to Istanbul, the governor of Egypt was given the title of khedive, which emphasised his superiority over other governors. In the same years the rule of succession was also changed so as to pass from father to son, and Egypt was granted powers of a sovereign nature such as foreign borrowing, awarding medals and keeping consulates. These steps are the first link of the chain that hastened Egypt's legal break from the Ottomans.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["The Cretan Statute: Broad Administrative Privileges for the Island", "12052262"], "d": ["To end the three-year revolt, the Grand Vizier Âlî Pasha crossed to the island in person, and by the statute issued with the sultan's approval the Cretans were granted mixed administrative councils, local courts, the use of Greek in official transactions, and tax relief. This arrangement kept Ottoman dominion on the island standing for thirty more years. However, the privileges granted to the Christian population weakened the position of the Muslim Cretans and sowed the seeds of the crisis of 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["The Opening of the Şûrâ-yı Devlet: The Founding of the Ottoman Council of State", "70b16497"], "d": ["By the irade of 5 March 1868 the Meclis-i Ahkâm-ı Adliyye was divided in two, with administrative and legislative affairs left to the Şûrâ-yı Devlet and judicial matters to the Dîvân-ı Ahkâm-ı Adliyye; the institution was opened with a ceremony at the Sublime Porte, and Midhat Pasha was appointed as its first president. It was charged with preparing draft laws, resolving administrative disputes and conducting the trials of officials. With its mixed Muslim and non-Muslim membership, it is regarded as the first institutional application of the idea of the separation of powers in the Ottoman Empire.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["The Opening of the Suez Canal: The Shortening of the Route to India via Egypt", "377ccd04"], "d": ["The construction, begun in 1859, lasted ten years, and the 163-kilometre canal linking the Mediterranean with the Red Sea entered service with a magnificent ceremony. When the route linking Europe with India was shortened by thousands of miles, Egypt suddenly became a key point of world trade. This geostrategic value would be the principal reason for England's occupation of Egypt thirteen years after the opening of the canal; the debt the canal placed on Egypt would drag the khedivate into bankruptcy.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["The Founding of the Bulgarian Exarchate: The Separation of the Bulgarian Church from the Phanar", "33a8272c"], "d": ["By imperial firman, an independent Bulgarian church (exarchate) separate from the Greek Patriarchate was established, and which kazas would be attached to the exarchate was left to a popular vote. Although the Sublime Porte took this step to break Greek influence, the result worked in reverse: the church turned into the organised centre of Bulgarian national identity and of the Bulgarian claim over Macedonia. The institutional ground of the Bulgarian-Greek-Serbian rivalry in the Balkans and of the uprisings of 1876 was thus laid.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["The taking of Asir under direct administration", "4559e099"], "d": ["When the strategic value of the Red Sea rose with the opening of the Suez Canal, it was recognised that the Asir mountains, in the middle of the land route to Yemen, could not be left uncontrolled. The forces of Redif Pasha, setting out on the Yemen campaign, entered Abha and attached the region to direct Ottoman administration, and the sancak of Asir was founded. Because of the mountainous geography and Idrisid influence, this domination never became fully settled.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Midhat Pasha's Najd Campaign: The Re-establishment of Ottoman Dominion in al-Hasa", "7db51461"], "d": ["Midhat Pasha, the governor of Baghdad, exploiting the struggle for the throne within the Saudi family, sent troops to the western shore of the Persian Gulf and attached the region of al-Hasa to the vilayet of Basra under the name of the sancak of Najd. With Abdullah b. Faysal appointed mutasarrıf, Ottoman dominion was established on paper. The campaign aimed at halting the spread of British influence in the Gulf and in the same year led to Qatar's also coming under Ottoman control.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["The Death of the Grand Vizier Âlî Pasha: The End of the Tanzimat Cadre", "1cf0141c"], "d": ["With the death of Âlî Pasha, who after Fuad Pasha's death in 1869 had shouldered the Tanzimat policy alone, the generation of master diplomats who had directed the state's foreign policy for thirty years was exhausted. The pro-Russian and arbitrary administration of Mahmud Nedim Pasha, who took his place, strengthened Abdülaziz's personal rule. In the five years after Âlî Pasha's death, the finances went bankrupt, the Balkans rose in revolt, and a change of reign became unavoidable.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["The Establishment of Ottoman Control in Qatar", "3b453165"], "d": ["Upon the invitation of Sheikh Qasim b. Thani, who was under British pressure, Ottoman forces landed on the Qatar peninsula, and in the autumn of 1871 Ottoman control was established in the region. Qatar was organised as a kaza attached to the sancak of Najd, and the sheikh was appointed kaymakam. This move was the most concrete gain of the forward policy that Midhat Pasha conducted in the Gulf against England; the Ottoman flag flew on the peninsula until 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["The decree of succession for Tunisia — the beylik to the family of Mehmed Sadık Pasha", "1509ebb0"], "d": ["By a firman issued through the efforts of Hayreddin Pasha, whom the bey of Tunis, Mehmed Sadık Pasha, sent to Istanbul taking advantage of France's defeat by Prussia, Tunisia was given to Mehmed Sadık Pasha and his progeny by hereditary succession, remaining directly attached to Istanbul. War and peace negotiations would not be conducted without the sultan's permission, no territory of the country would be given to anyone else, and the Ottoman demand for troops would be met. France did not recognise the firman; ten years later it occupied Tunisia.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["The Taking of Sana'a: The Re-establishment of Ottoman Authority in Yemen", "978e20a0"], "d": ["When the strategic value of the Red Sea increased with the opening of the Suez Canal, the Sublime Porte sent the reserve army (fırka-i ihtiyâtiyye) to Yemen under the command of Ahmed Muhtar Pasha. With the taking of Sana'a, state authority was re-established in inner Yemen, which had been effectively lost for two centuries, and the region was made a vilayet. However, the struggle with the Zaydi imams never ended; the rebellions of 1891, 1898 and 1904 formed the Ottomans' most costly and longest-lasting internal front. Other places that joined on the same date: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["The Beginning of the Herzegovina Uprising: The Re-ignition of the Eastern Question", "571b18ec"], "d": ["The uprising of Christian peasants around Nevesinje because of heavy taxes and the pressure of the ayans spread within a short time to the whole of Herzegovina and was fed by volunteers coming from Serbia and Montenegro. The rebellion, which led to reform impositions by Austria and Russia, triggered the Bulgarian uprisings and the Serbian-Montenegrin declarations of war the following year. Thus the first link was broken of the great chain leading to the '93 War and, by the Treaty of Berlin, to the loss of the Balkans.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["The Bankruptcy of Ottoman Finance: The Halving of Foreign Debt Payments", "2cac2fa5"], "d": ["The loans taken one after another since 1854, the expenses of the Crimean War, the palace constructions and the Anatolian famine of 1873-74 turned the budget deficit into an abyss exceeding five million lira. The government of Mahmud Nedim Pasha effectively declared a moratorium by announcing that debt interest and principal payments would be halved for five years. This decision, which aroused great reaction on the European exchanges, began the process that would end six years later with the Decree of Muharrem and the founding of the Ottoman Public Debt Administration (Düyûn-ı Umûmiyye İdaresi).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["The Deposition of Murad V and the Accession of Abdülhamid II", "cffb2271"], "d": ["Murad V, who ascended the throne after Abdülaziz's deposition, became unable to perform his duties because of his mental health, shaken by his uncle's death and by the Çerkes Hasan Incident; of his reign of ninety-three days, his judgement was sound for only seven days. He was deposed by a fatwa of the şeyhülislam, and his brother Abdülhamid II was brought in his place. The new sultan came to the throne having given Midhat Pasha his word that he would proclaim the constitutional regime; an era that would last thirty-three years was beginning.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["The Tersane Conference: The Great Powers' Imposition of Balkan Reforms", "b5006a2c"], "d": ["The conference that the great powers convened in Istanbul to resolve the Balkan crisis demanded the division of Bulgaria into two autonomous vilayets and the application of reforms under international supervision in Bosnia-Herzegovina. On the day the conference opened, the Sublime Porte announced the proclamation of the Kanûn-ı Esâsî with cannon salvos, trying to meet the impositions with a constitutional reform. The delegates regarded this as stalling and dispersed on 20 January 1877; four months later Russia declared war.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["The Opening of the First Meclis-i Meb'ûsan at Dolmabahçe", "429bb279"], "d": ["The 115 deputies elected in accordance with the Kanûn-ı Esâsî met for the first time on 19 March 1877 in a ceremony held in the Muayede Hall of the Dolmabahçe Palace; thus the period of representative assemblies began in Ottoman history. Muslim and non-Muslim deputies sharply questioned the government and debated the conduct of the war and the responsibility of the ministers. This bold opposition would be the principal reason that shortened the life of the assembly.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["The Beginning of the Defence of Plevna: The Resistance of Gazi Osman Pasha", "0e04a878"], "d": ["Osman Pasha, who marched from Vidin to Plevna in order to cut the road to Istanbul of the Russian army that had crossed the Danube in the '93 War, fortified the town with redoubts and trenches and began a legendary defence of five months. Three successive great Russian-Romanian assaults were repulsed with heavy losses, and the army, directed in person by Tsar Alexander II, was obliged to settle for a siege. Plevna went down in history as the Ottoman army's most brilliant defensive success of the nineteenth century.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["The Fall of Plevna: The Collapse of the Danube Front", "185e7602"], "d": ["Osman Pasha, whose provisions ran out in the siege of five months, attempted a sortie across the Vid river; when he was wounded and taken prisoner, the city surrendered. The Russian commanders saluted the captured pasha by returning his sword, and Osman Pasha was given the title 'Gazi'. With the fall of Plevna the road lay open to the Russian army; within two months Sofia, Philippopolis and Edirne fell, and the Russian vanguards reached Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["The Occupation of Sofia by Russian Forces", "ef369d22"], "d": ["The Russian army, which crossed the Balkans after the fall of Plevna, entered the defenceless Sofia. The city would never return to Ottoman administration; it would become the capital of the autonomous Principality of Bulgaria at the end of 1878 and in practice in 1879. On the map, from this date Sofia leaves direct Ottoman administration and passes to a temporary Russian occupation and then to autonomous Bulgarian rule.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["The Armistice of Edirne: The Silencing of the Guns in the '93 War", "1f899180"], "d": ["With the successive fall of Sofia, Philippopolis and Edirne and the Russian army's pressing up to the shores of the Marmara, the Sublime Porte was obliged to ask for an armistice. The ceasefire signed at Edirne made the Ottomans accept preliminary peace terms such as autonomy for Bulgaria, the independence of Montenegro, Serbia and Romania, and a heavy war indemnity. These terms would be turned a month later into a treaty text at San Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdülhamid II's Indefinite Prorogation of the Meclis-i Meb'ûsan", "e770b540"], "d": ["Upon the sharp criticisms of the deputies, who held the government and the palace responsible for the disastrous outcome of the war, Abdülhamid II prorogued the assembly indefinitely, relying on the authority granted him by the Kanûn-ı Esâsî. The first Ottoman parliament, which had worked for about eleven months, was thus closed, and the era of despotism (istibdat), which would last thirty years, began. The assembly would be able to meet again only after the Revolution of 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["The Treaty of San Stefano: The Greater Bulgaria Project", "2c7cc611"], "d": ["The Treaty of San Stefano, which ended the '93 War, established a huge autonomous Bulgaria extending to the Aegean and including Macedonia; recognised the independence of Serbia, Montenegro and Romania; ceded Kars, Ardahan, Batum and Doğubayazıt to Russia; and in addition imposed a war indemnity impossible to pay. This text, which brought Russia down to the Mediterranean, drew the fierce reaction of England and Austria. Before being put into effect it was rearranged within four months by the Congress of Berlin; nonetheless it remained the document that proclaimed the end of Ottoman Rumelia.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan and Batum ceded to Russia — the elviye-i selâse", "99bdfad2"], "d": ["By the Treaty of Berlin the Ottoman State ceded Kars, Ardahan and Batum to Russia in lieu of a part of the war indemnity; Doğubayazıt and the Eleşkirt valley, which had been given to Russia at San Stefano, remained with the Ottomans. Although Batum was granted as a free port, it could preserve this status only until 1886. The Russians made Kars a province attached to the Transcaucasian governor-generalship centred on Tbilisi; a population reaching 100,000 from the elviye-i selâse had to migrate toward Erzurum.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["The Occupation of Bosnia-Herzegovina and Yenipazar by Austria-Hungary", "e5f901df"], "d": ["Relying on the authority granted by the Treaty of Berlin, Austro-Hungarian armies entered Bosnia; although the Ottoman government had agreed not to resist, the local Muslim and Orthodox population in Sarajevo and Mostar took up arms and offered hard resistance for three months. The occupation could be completed only on 20 October 1878. The sultan's legal sovereignty continued on paper until 1908, but four centuries of Ottoman Bosnia was effectively lost, and a great wave of Muslim emigration began. Other settlements lost on the same date: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["The Decree of Muharrem and the Founding of the Ottoman Public Debt Administration", "02b7cc03"], "d": ["The negotiations conducted with the representatives of the creditor states after the bankruptcy of 1875 ended in the decree dated 28 Muharrem 1299 (20 December 1881): the debt principal was reduced by more than half, and in return the most productive revenue items, such as the salt, tobacco, silk, stamp and fish duties, were transferred to the Düyûn-ı Umûmiyye İdaresi (Public Debt Administration), directly managed by the creditors. This administration, which employed thousands of officials, turned into a separate financial organisation within the state. It is accepted as the date on which Ottoman financial independence effectively ended.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — The Only Port Not to Fall to the Mahdi", "5a37b198"], "d": ["From February 1884, while all the regions of eastern Sudan other than Suakin passed to the dominion of Muhammad Ahmad al-Mahdi, the port stood under the military protection of a British force of three battalions under General Graham. This was the beginning of a period in which the de facto and legal situations diverged: although the coast was in fact under British military control, its administrative tie would be taken from Egypt in 1885 and attached directly to the vilayet of Yemen, that is, to the Sublime Porte — that arrangement lasted until it ended in 1888 with France's occupation of Zeila.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["The Killing of Midhat Pasha in the Prison of Taif", "f4562261"], "d": ["Midhat Pasha, the architect of the Kanûn-ı Esâsî and the symbolic name of the First Constitutional Era, had been found guilty by the Yıldız Court in connection with Abdülaziz's death and, his death sentence commuted to exile, had been sent to Taif. According to the TDV record, he was strangled to death in his cell on the night of 7-8 May 1884, and the official reason was announced as the 'şîrpençe' disease. His death became the symbol of the liquidation of constitutional opposition in the reign of Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["The Granting of the Haydarpaşa-Ankara Railway Concession to the Germans", "5705b163"], "d": ["By the sultan's irade, the concession for the construction and operation of the Haydarpaşa-Ankara line was given to Alfred von Kaulla, the banker representing the Deutsche Bank, and the Anatolian Railway Company was established. This concession was the turning point that broke the Anglo-French monopoly in Ottoman transport and foreign policy and established German influence. Together with the Baghdad line concession to be given to the same company eleven years later, the dream of 'Berlin-Baghdad' would be born, and this would become one of the main axes of great-power rivalry before the First World War.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["The Founding of the İttihâd-ı Osmânî Cemiyeti in Istanbul", "b7187939"], "d": ["Four students of the Military Medical School founded the İttihâd-ı Osmânî Cemiyeti as a secret organisation against the despotic regime; this body soon turned into the Committee of Union and Progress, which would gather all the opposing elements of the Young Turk movement under its roof. The cell-based organisation united with the exiles in Europe and the officers in Salonica. The cadre that would have the Second Constitutional Era proclaimed in 1908 and would rule the state alone after 1913 came out of this small student cell.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["The Ottoman Bank Raid: The Dashnak Militants' Action at Galata", "08b3095f"], "d": ["An armed group of the Armenian Dashnaktsutyun organisation, in order to draw Europe's attention to the Armenian question, raided and took hostage the headquarters of the Ottoman Bank at Galata and threatened to blow up the building. The crisis ended, through the intervention of the ambassadors, in exchange for the militants' being taken out of the country on a ship. The bloody events that took place in Istanbul in the days following the raid were decisive in the Armenian question's turning into a lever of international intervention.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["The Beginning of the Ottoman-Greek War of 1897: The Thessaly Front", "33e490ab"], "d": ["Upon Greece's landing of fleet and troops in Crete and the raids of bands on the Rumelian frontier, the Ottoman State declared war. The Ottoman army, trained by the German reform mission, advanced rapidly in Thessaly and within a month took Yenişehir, Çatalca and Dömeke; the Greek army was dispersed. With the intervention of the great powers the territories won were returned, but the war remained the only decisive military victory of the reign of Abdülhamid II and could not prevent the de facto loss of Crete.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["The Granting of the Konya-Baghdad Railway Concession to the Germans", "fd8b6cbd"], "d": ["Following Kaiser Wilhelm II's visit to Istanbul and Damascus in 1898, the Anatolian Railway Company was given the preliminary concession for the line to extend from Konya to Baghdad and Basra. The Baghdad Railway project meant, for the Ottomans, strengthening central control over the Arab vilayets, and for Germany, reaching the Persian Gulf. This project, which England and Russia opposed fiercely, became one of the most contested files of the imperialist rivalry leading to the First World War.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["The Beginning of the Construction of the Hejaz Railway at Damascus", "62f58f68"], "d": ["The line, ordered by the irade of Abdülhamid II dated 2 May 1900, began construction with an official ceremony held at Damascus on 1 September 1900. The project, built entirely with donations collected from the Islamic world and the labour of Ottoman engineer-soldiers, reduced the pilgrims' journey from Damascus to Medina from forty days to five. It was both a work of prestige reinforcing the spiritual authority of the caliphate and a strategic investment strengthening military control over the Hijaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["The Mürzsteg Programme: International Reform Supervision in Macedonia", "4c7464da"], "d": ["After the Ilinden uprising, the Russian and Austrian emperors met at Mürzsteg and prepared a new reform package for Macedonia. The programme envisaged placing two foreign civil agents beside the Ottoman inspector-general, reorganising the gendarmerie by European officers, and changing administrative boundaries on the basis of nationality. Although the Sublime Porte resisted on the grounds that its sovereign rights were being violated, it was obliged to accept in the face of the joint pressure; the programme became one of the fundamental factors that accelerated Unionist organisation among young officers.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["The death of Murad V", "396659a7"], "d": ["Murad V, who remained on the throne for about three months in 1876 and was deposed, lived twenty-eight years as a prisoner under close guard after the attempts to restore him to the throne, and died of diabetes. He was interred next to his mother in the Cedid Havatin Tomb in the Yeni Cami. He went down in history as the Ottoman sultan who remained on the throne for the shortest time.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["The Loss of Sana'a to Imam Yahya", "e7f876cb"], "d": ["The uprising begun in 1904 by the Zaydi Imam Yahya Hamid al-Din ended in April 1905 with the fall of Sana'a at the end of a siege; the city left Ottoman administration, and hunger and epidemic broke out during the siege. The mountainous geography of Yemen, the length of the supply lines and the local legitimacy of the Zaydi imamate had made Ottoman dominion there fragile since its establishment. The city would be retaken five months later at the price of heavy losses, but the Yemen question would not be closed until 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["The Yıldız Assassination: The Bomb Attack on Abdülhamid II", "1ee2e1a6"], "d": ["The Dashnaktsutyun organisation mounted an assassination by exploding a landau with a time bomb at the sultan's carriage as he came out of the Friday selamlık; Abdülhamid's being delayed by a few minutes while talking with the şeyhülislam saved his life. Twenty-six people died in the explosion and more than fifty were wounded. The event hardened still further the sultan's obsession with security and his despotic rule based on the spy organisation; it was also the subject of Tevfik Fikret's poem 'Bir Lahza-i Taahhur'.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["The Retaking of Sana'a: The Suppression of Imam Yahya's Rebellion", "dec3b8f9"], "d": ["The uprising that began in 1904 under the leadership of the Zaydi Imam Yahya ended in April 1905 with the fall of Sana'a, and hunger and epidemic broke out in the city. The reinforcement armies under Ali Rızâ Pasha and Ahmed Feyzi Pasha retook the city at the price of heavy losses, in an operation carried out between 15 July and 1 September 1905 and supported also by the forces at Taiz, and the rebellion was suppressed. The Yemen operation cost the Ottoman army tens of thousands of casualties and brought an enormous financial burden; among the officers in Rumelia, the fear of 'exile to Yemen' was foremost among the grievances feeding Unionist organisation.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["The Convening of the First Meclis-i Meb'ûsan of the Second Constitutional Era", "e7fd2716"], "d": ["The assembly, formed through the two-stage elections held after an interval of thirty years, was opened on 17 December 1908 with the sultan's speech, and Ahmed Rızâ Bey, the leader of the Young Turk movement, was elected its president. Composed of Turkish, Arab, Albanian, Greek, Armenian and Jewish deputies, the assembly was the last great trial of the ideal of Ottomanism. However, Bulgaria's independence, the annexation of Bosnia and Crete's declaration of union with Greece had overshadowed this optimism even before the assembly opened.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["The Action Army and the Deposition of Abdülhamid II: The Accession of Mehmed V Reşad", "6a65a704"], "d": ["The Action Army (Hareket Ordusu), which set out from Salonica upon the 31 March Incident, entered Istanbul in four columns on the night of 22-23 April, and on 24 April the Yıldız Palace surrendered. The Meclis-i Umûmî-i Millî decided on 27 April on the deposition of Abdülhamid II; the sultan was sent to Salonica, and his brother Mehmed V Reşad was placed on the throne. The personal rule of thirty-three years thus ended, but it was replaced by a new period in which the sultan became a symbol and the Committee of Union and Progress governed with the support of the army.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["The Albanian Revolt: Armed Resistance in Kosovo and Shkodër", "93ed30c6"], "d": ["The Unionist government's centralist tax policy, its campaign of collecting arms and the debate over the Latin alphabet set in revolt the Albanian tribes, who until then had been regarded as among the elements most loyal to the state. Although the army under Mahmud Şevket Pasha suppressed the revolt harshly, the unrest flared up again in 1911 and 1912. These revolts wore down the Ottoman army on the eve of the Balkan War and also accelerated the birth of the Albanian national movement.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["The Treaty of Ouchy: The Ceding of Tripolitania and Benghazi to Italy", "4ffa1fd2"], "d": ["The Sublime Porte, unable to risk a two-front conflict in the face of the war preparations of the Balkan states, signed a secret peace with Italy in the Swiss town of Ouchy and abandoned Tripolitania and Benghazi. The Ottoman State thus lost its last territory in Africa; in return, although the return of Rhodes and the Twelve Islands occupied by Italy was promised, this promise was never fulfilled. By the time the treaty was signed, the Balkan War had long since begun.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["The Greek occupation of Lemnos", "9555af1d"], "d": ["In the First Balkan War the Greek fleet occupied Lemnos; the island's port of Mudros became a base for the blockade of the Dardanelles. The island was left to Greece at Lausanne (24 July 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["The Greek occupation of Thasos", "6c03c7f0"], "d": ["In the First Balkan War Greece occupied Thasos and Samothrace.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["The Greek occupation of Samothrace", "911e82a3"], "d": ["In the First Balkan War Greece occupied Samothrace.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["The Greek occupation of Lesbos", "6b2b07ba"], "d": ["The Greek fleet landed on Lesbos; the island was taken by the Greek army and fleet at the end of the First Balkan War. The London Conference (May 1913) confirmed the situation.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["The Greek landing on Chios", "901c6539"], "d": ["The Greeks made a landing on Chios, which had been bombarded on 7 April 1912 in the First Balkan War; the Ottoman garrison surrendered on 3 January 1913. The island was left to Greece by the Treaty of Lausanne (24 July 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["The Assassination of the Grand Vizier Mahmud Şevket Pasha in Istanbul", "68e60e63"], "d": ["Mahmud Şevket Pasha, who had been brought to the grand vizierate after the Raid on the Sublime Porte, was killed by shots fired at his carriage near Çarşıkapı while he was going to the Ministry of War. The Committee of Union and Progress, blaming the assassination on the opposition, began a wave of mass arrests and executions, and the Freedom and Accord Party was effectively liquidated. With this event the one-party dictatorship of the Unionists, based on the Enver-Talat-Cemal triumvirate, was firmly established.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["The Beginning of the Second Balkan War: The Allies' Quarrel over Partition", "48d088a2"], "d": ["The Balkan allies, who could not share the lands they had taken from the Ottomans under the Treaty of London, fell upon one another; the second war began with Bulgaria's attack on the Serbian and Greek positions. When Romania and Montenegro also entered the front against Bulgaria, the Bulgarian army collapsed. The Ottoman State, exploiting this opportunity, crossed the Midye-Enez line drawn by the Treaty of London and retook Eastern Thrace together with Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["The Treaty of Istanbul: Peace with Bulgaria and the Registration of Edirne", "c8c18b2d"], "d": ["The treaty signed between the Ottoman State and Bulgaria after the Second Balkan War, accepting the Maritsa river as the frontier, legally registered the remaining of Edirne, Kırklareli, Dimetoka and Eastern Thrace with the Ottomans. Dedeağaç was left in Bulgaria (Kavala, however, had passed to Greece in July 1913 after the Bulgarian occupation of the autumn of 1912 and had been registered in Greece by the Treaty of Bucharest of 10 August 1913), and a mutual exchange of populations between the two countries and the rights of the Muslims in Bulgaria were regulated. This text is the guarantee of the only piece of land that could be recovered from the Balkan catastrophe. Other places that joined on the same date: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["The retaking of Tenedos and Imbros — the Treaty of Athens", "ec084d09"], "d": ["Of the North Aegean islands occupied by Greece in the Balkan War, Tenedos and Imbros, which hold the mouth of the Straits, were regarded as indispensable for the defence of Çanakkale during the negotiations for the Treaty of Athens and were returned to the Ottomans. The other islands remained with Greece. These two islands became the last territories the Empire held in the Aegean, and at Lausanne they were also left to Turkey.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["The Treaty of Athens: Peace with Greece and the Transfer of Salonica and Yanya", "8e94def7"], "d": ["The treaty signed between the Ottoman State and Greece officially recognised the passing to Greece of Salonica, Yanya and Southern Macedonia, lost in the Balkan War, and gave up the Ottoman rights over Crete. The religious and property rights of the Muslims remaining in Greece, the status of the pious foundations and the appointment of muftis were regulated in detail. The status of the Aegean islands, however, was left unresolved and remained a source of constant tension between the two states.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["The Signing of the Ottoman-German Secret Alliance Treaty in Istanbul", "0472efb3"], "d": ["As soon as war broke out in Europe, a secret alliance treaty was signed between the Ottoman State and Germany in the mansion of the Grand Vizier Said Halim Pasha; the text envisaged that the Ottomans too would take Germany's side if Russia entered the war against Germany. The treaty was concealed even from the cabinet and was known to only four persons. Three months later the Ottoman State would be dragged effectively into the war by the Black Sea raid, and the fate of the empire would be bound by this document.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["The Unilateral Abolition of the Capitulations", "ec773d18"], "d": ["The Ottoman government, at a moment when Europe was occupied with the war, declared that it was abolishing unilaterally, from 1 October 1914, the capitulations that granted foreigners judicial, financial and customs privileges. The ending of this privilege order of four centuries was greeted within the country with great enthusiasm for independence, and celebrations were held in Istanbul. All the states, including its ally Germany, protested the decision; the capitulations would pass into history definitively only in 1923 at Lausanne.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["The Black Sea Raid: The Bombardment of Russian Ports by the Ottoman Fleet", "8ad4ef61"], "d": ["The Goeben and Breslau (Yavuz and Midilli), which had escaped from Germany and joined the Ottoman fleet as though 'purchased', put out into the Black Sea under Admiral Souchon, bombarded Russian ports and sank ships. This order, which Enver Pasha gave secretly from the cabinet, effectively ended neutrality. Within a week Russia, England and France declared war, and the Ottoman State had irrevocably entered the First World War.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["The capture of Fao by Anglo-Indian forces — the opening of the Iraq front", "08663813"], "d": ["On the morning after the day on which the Allied powers declared war on the Ottoman State, the Anglo-Indian brigade waiting in Bahrain landed at Fao, at the mouth of the Shatt al-Arab. The small Ottoman unit in the ruined Fao fortress withdrew under the fire of the warships, and the station of the Indian telegraph line fell into British hands. The Iraq front was thus opened.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["The Proclamation of the Cihâd-ı Ekber: The Reading of the Jihad Fatwa at the Fatih Mosque", "2a6174e8"], "d": ["The five fatwas issued by the Şeyhülislam Ürgüplü Hayri Efendi were read at the Fatih Mosque in the name of the caliph-sultan, and all Muslims were called to jihad against the Entente states. This move, on which Germany placed great hopes, aimed at inciting Muslims in the British and French colonies to revolt. The expected general uprising did not take place; on the contrary, the revolt of the Emir of Mecca, Sharif Husayn, with British support two years later painfully showed the limits of the caliphate's political influence.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["The surrender of Qurna to the British", "621d36b0"], "d": ["The forces of Subhi Bey, the governor of Basra, who had withdrawn to Qurna, where the Tigris and the Euphrates meet, after the fall of Basra, surrendered on the morning of 9 December 1914, after the clashes of 4-8 December.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["The Placing of Egypt under British Protection and the Proclamation of a Sultanate", "55d4e520"], "d": ["Upon the Ottoman State's entry into the war, England declared that it was officially taking under its protection Egypt, which it had kept in effective occupation since 1882; the Khedive Abbas Hilmi Pasha, who persisted in his allegiance to the Ottomans, was dismissed and Hüseyin Kâmil was brought in his place with the title of 'sultan'. Thus the legal Ottoman sovereignty that had lasted since 1517 was ended unilaterally. The Sublime Porte did not recognise the decision and two months later attempted to retake Egypt with the Canal Operation.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["The Sarıkamış Operation: Catastrophe on the Caucasus Front", "5cbde7f0"], "d": ["Enver Pasha, in order to retake Kars-Ardahan-Batum, lost in 1878, and to rouse the Turks in the Caucasus, drove the Third Army in winter over the Allahuekber mountains in a manoeuvre to encircle the Russian forces. Because of inadequate winter equipment, exhausted supplies and blizzards reaching minus thirty degrees, the army melted away before even entering battle; tens of thousands of soldiers froze to death. The operation became one of the heaviest catastrophes of the Ottomans in the war and left the eastern front defenceless for two years.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["The First Canal Operation: The Attack on Suez across the Sinai Desert", "02dd72f5"], "d": ["Cemal Pasha, the commander of the Fourth Army, mounted an attack across the Sinai desert with the aim of freeing Egypt from the British occupation and closing the Suez Canal to traffic. Although the Ottoman units reached the eastern bank of the canal and some managed to cross, they withdrew in the face of British superiority and the failure of the expected Egyptian popular uprising to materialise. The operation did not reach its objective, but by obliging England to keep a large force in Egypt it created an indirect strategic effect.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["The Issuing of the Law of Deportation and Resettlement (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["After the Van revolt and the Russian advance, the government issued a temporary law permitting army commanders to transfer to other regions the population judged to be disturbing security behind the front, and the sultan ratified it on 27 May 1915. As a result of the implementation, the greater part of the Armenian population in the eastern and southern vilayets of Anatolia was sent in the direction of Syria and Mosul; during the transfer, very great loss of life occurred through disease, hunger and attacks. The decision has remained the heaviest and still today the most contested question of the last years of the Ottomans.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Ottoman units retook Muş from the Russian occupation", "fb1be113"], "d": ["Six months after the first Russian occupation of Muş, the Ottoman 16th Corps entered the town in the Bitlis-Muş counteroffensive.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş fell once more into Russian hands", "43ad8a03"], "d": ["Upon the Russian counteroffensive, the Ottoman detachment evacuated Muş; the town came again under Russian occupation between 22 and 25 August 1916 and remained so until the spring of 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş was definitively liberated from the Russian occupation", "f0e89703"], "d": ["Muş, which came under Russian occupation in the First World War, was definitively retaken by Ottoman forces on 1 May 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["The Death of Abdülhamid II at the Beylerbeyi Palace", "c9662582"], "d": ["Abdülhamid II, who had been deposed in 1909 and brought first to Salonica and then, when the city was lost in the Balkan War, to Istanbul and kept under house arrest in the Beylerbeyi Palace, died. Throughout his reign of thirty-three years he had tried to gain time by keeping the state away from wars, but he was also remembered for his despotic rule. He was buried with a great crowd in the Tomb of Mahmud I on Divanyolu; his death coincided with a year of war in which the order he had established had long since been liquidated.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["The Treaty of Brest-Litovsk: The Recovery of Kars, Ardahan and Batum", "da82636f"], "d": ["The treaty signed between Russia, which had withdrawn from the war after the Bolshevik revolution, and the Central Powers closed the Eastern front and regained for the Ottoman State Kars, Ardahan and Batum (Elviye-i Selâse), which it had lost by the 1878 Treaty of Berlin. This was the only territorial gain in Ottoman history obtained after an interval of forty years. However, the region would be lost again after the Armistice of Mudros, and the definitive solution would come with the 1921 Treaty of Kars.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Ottoman units entered Artvin", "ca7d1778"], "d": ["The Ottoman units, which crossed the 1914 frontier on 25 March, marched on the Elviye-i Selâse, whose pre-1878 frontier Brest-Litovsk gave back, and entered Artvin on 28 March 1918. Artvin had been left to Russia in 1878 as part of the sancak of Batum; the TDV article on Artvin writes the return only as 'March 1918', while Sarı gives the day.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan fell into the hands of the Turkish army", "7fd9e3db"], "d": ["In the Elviye-i Selâse operation, the Ottoman army, after Artvin, took Ardahan on 3 April 1918; Ardahan had fallen in 1877 in the War of '93 and had been left to Russia in 1878. Kars would be taken a month later, on 25 April.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["The retaking of Batum", "d37a1a0d"], "d": ["When Russia withdrew from the war with the Treaty of Brest-Litovsk, the Ottoman army, advancing eastward, retook the port of Batum, lost in 1878, forty years later. This port at the eastern end of the Black Sea was the sea outlet of Baku oil. The gain lasted only seven months; after the Armistice of Mudros the region would be evacuated.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars came under Ottoman administration", "02cbf0b3"], "d": ["At Brest-Litovsk the return of the three sancaks lost by the 1878 Treaty of Berlin — Kars, Ardahan and Batum — had been agreed; the Ottoman army entered Ardahan on 3 April, Batum on 14 April and Kars on 25 April 1918, and administration was effectively established. These lands, known by the name 'Elviye-i Selâse', were regarded as compensation for the loss ongoing since the War of '93. After the armistice they would be lost again, and they would be definitively attached to Turkey only with the 1921 Treaty of Kars.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır was seized — the advance in the Aras valley", "87ebf4d3"], "d": ["Within the framework of the forward operation that began in February 1918, Turkish units defeated Armenian units at Serdarabad north of the Aras and seized Iğdır on 20 May 1918. Iğdır was not part of the Elviye-i Selâse but the Surmali district of the Erivan governorate; the first Ottoman administration in the region in about 180 years was established.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["The Death of Mehmed V Reşad and the Accession of Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, whose reign of nine years passed with the Tripolitanian, Balkan and World wars, died in the most critical period of the war, and his brother Vahdeddin ascended the throne under the name of Mehmed VI. The new sultan tried to free himself from the tutelage of the Unionist cadre; when the armistice was signed four months later, he would be obliged to manage the liquidation of the empire. He was the thirty-sixth and last sultan of the Ottoman dynasty.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["The Arrival of the Entente Fleet before Istanbul and the De Facto Occupation of the City", "d10cb14d"], "d": ["After the Armistice of Mudros, an allied fleet of more than sixty vessels made up of British, French, Italian and Greek ships anchored before Dolmabahçe, and Istanbul came effectively under occupation. After four hundred and sixty-five years the capital had for the first time passed under the control of foreign soldiers. The words 'They will go as they came', said to have been spoken on the same day by Mustafa Kemal Pasha on landing at Haydarpaşa and seeing the scene, would become one of the symbolic sentences of the National Struggle.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Withdrawal in the Aras region: Iğdır evacuated", "57572ab4"], "d": ["In accordance with the provision of the Armistice of Mudros requiring withdrawal behind the 1914 frontier, Yakup Şevki Pasha, by an order of 21 November, ordered units outside the Brest-Litovsk boundary to be withdrawn by 4 December; Iğdır and its surroundings were completely evacuated on this date. Afterwards the Aras-Turkish Government was overthrown by the Armenians in late December 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["The British settled in Artvin", "e2cb3153"], "d": ["Because the Armistice of Mudros of 30 October 1918 stipulated the Ottoman army's withdrawal behind the 1914 frontier, Artvin was evacuated and was occupied by the British on 17 December 1918. According to the TDV article on Artvin, the British occupation lasted until April 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["British administration in Batum after Mudros", "9dd768fc"], "d": ["Under the Armistice of Mudros of 30 October 1918, the Ottoman State was obliged to withdraw from Batum; the city was held by British units on 24 December 1918. Batum, made the centre of an independent sancak in April 1918, remained under British control from this date until July 1920.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan passed to Georgian domination", "97cf47f6"], "d": ["Ardahan, evacuated after Mudros, was occupied by Georgian forces on 20 April 1919, in the days when the South-West Caucasus Government was being dissolved by the British. Georgian domination would last until 23 February 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston handed the administration of Kars to the Armenian governor", "efa81cb0"], "d": ["The British commander Preston, who dissolved the South-West Caucasus Government on 12-13 April 1919, abolished the provisional shura government on 30 April 1919 and handed the administration of the city to the Armenian Karganov, who was made Governor of Kars; the period of Armenian administration in Kars began and lasted until Kâzım Karabekir's victory on 30 October 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["The Erzurum Congress: The Decision of National Resistance of the Eastern Vilayets", "41ef0457"], "d": ["The congress convened by the Society for the Defence of the Rights of Eastern Anatolia (Şarkî Anadolu Müdafaa-i Hukuk Cemiyeti), after being postponed under British pressure, opened with fifty-six delegates, and Mustafa Kemal Pasha, who had resigned from the army, was elected its president. The congress declared that within the national borders the homeland was a whole, that mandate and protectorate could not be accepted, and that if the government dissolved the nation would take its own destiny into its hands. These decisions would form the nucleus of the text of the Misâk-ı Millî six months later.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["The Sivas Congress: The Union of National Resistance under a Single Roof", "0e9ad36b"], "d": ["The congress, which began its work on 4 September 1919 at the Sivas Sultânî school, united the societies for the defence of rights from all parts of the country under the name of the Society for the Defence of the Rights of Anatolia and Rumelia (Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti) and elected a Representative Committee (Heyet-i Temsîliyye). The proposal of an American mandate was rejected after long debates. With the declaration published on 11 September, the National Struggle became a single-centred, legitimate political movement, and an open struggle for power with the Istanbul government began.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["The Amasya Protocol: The Meeting of the Istanbul Government with the Representative Committee", "40e6a6ab"], "d": ["After the fall of Damat Ferid and the formation of the government of Ali Rızâ Pasha, the Minister of the Navy Salih Pasha was sent to Amasya to meet the Representative Committee. By the protocols reached, the Istanbul government effectively recognised the existence of the Anatolian movement; the convening of the Meclis-i Meb'ûsan, the holding of free elections and the preservation of the national borders were accepted. This is the first official political gain the National Struggle obtained against Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["The Adoption of the Misâk-ı Millî in the Last Ottoman Assembly", "6322865e"], "d": ["The text of the Ahd-i Millî, signed by 121 deputies in the last Ottoman Meclis-i Meb'ûsan, stipulated the indivisible integrity of the lands remaining within the Mudros line and inhabited by a Muslim-Turkish majority, a plebiscite in the Arab vilayets and Western Thrace, the abolition of the capitulations, and full political and financial independence. The text was adopted unanimously on 17 February 1920 and announced to the world. This declaration was as much the political programme of the National Struggle as the map of the borders to be defended at Lausanne; it was the direct reason for the Entente states' officially occupying Istanbul on 16 March.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["As the British withdrew, Artvin remained in Georgia", "6d086b06"], "d": ["According to the TDV article on Artvin, the British occupation lasted until the month of April 1920; as the British withdrew, they left the city to Georgia. Artvin remained in Georgian hands until the ultimatum of the Grand National Assembly of Turkey on 23 February 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum was handed over to Georgian administration", "6523d095"], "d": ["The British formal handover of Batum to the Georgians took place on 7 July 1920 (the TDV article on Batum says only 'July 1920'). On 25 July the Ankara government protested the handover as an 'occupation'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["The Treaty of Gümrü: The First International Treaty of the Government of the Grand National Assembly", "9232c690"], "d": ["After the army of the Eastern front under Kâzım Karabekir retook Sarıkamış and Kars, Armenia asked for peace, and by the treaty signed at Gümrü it accepted that it did not recognise Sèvres and renounced its territorial claims in the east. This first treaty signed by the Ankara government was the first international document effectively rejecting Sèvres, and it opened to the Grand National Assembly (TBMM) the road to legal recognition. The eastern frontier was thus secured, and shifting forces to the Western front became possible.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["The First Battle of İnönü: The First Victory of the Regular Army", "4add3719"], "d": ["The newly formed regular army stopped the Greek forces advancing from the direction of Bursa at the İnönü positions and compelled them to withdraw. This success, limited in scale in military terms, was very great in its political consequences: the Ankara government was invited to the London Conference, the way was opened to the Treaty of Moscow with Soviet Russia, and the Law of Fundamental Organisation (Teşkilât-ı Esâsiyye Kanunu) was adopted. Confidence in the regular army in domestic public opinion was also consolidated by this victory.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["The Second Battle of İnönü: The Second Breaking of the Greek Offensive", "a974521c"], "d": ["The Greek army, which had achieved no result from the London Conference, launched a new offensive from the directions of Bursa and Uşak, but was again stopped on the İnönü ridges and obliged to withdraw. The telegram that Mustafa Kemal Pasha sent to İsmet Pasha, 'There you defeated not only the enemy but the nation's ill fortune', was written after this victory. The battle raised the international standing of the National Struggle and accelerated the process of Italy's withdrawal from Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["The Ankara Agreement (İtilâfnâme): Peace with France and the Closing of the Southern Front", "35fc32db"], "d": ["With the agreement signed in Ankara with France after the victory of Sakarya, the war on the southern front ended; the French forces evacuated Çukurova and the Southeast, including Adana, Antep, Maraş and Urfa, and withdrew to the Syrian frontier. One of the Entente states thus effectively recognised the Ankara government, and the first crack opened in the Sèvres front. The arms taken over from the evacuated regions and the units freed played a critical role in the preparation of the Great Offensive.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["The Armistice of Mudanya: The Transfer of Istanbul and the Straits without War", "ac0d9baf"], "d": ["After the Great Offensive, when the Turkish army came face to face with British forces at Çanakkale and İzmit, the conference convened at Mudanya ended, after eleven days of hard bargaining, in an armistice. It was accepted that Eastern Thrace as far as the Maritsa would be evacuated by Greece within fifteen days and transferred to Turkish administration, and that Istanbul and the Straits would also be handed over with the peace treaty. Thus the armed phase of the National Struggle closed with a diplomatic victory won without a single shot being fired, and the door to Lausanne was opened.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["The Departure of Mehmed VI Vahdeddin from Istanbul and the Election of Abdülmecid Efendi as Caliph", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, the last sultan, whose position had become disputed after the abolition of the sultanate, left Istanbul on the morning of Friday, 17 November 1922, aboard the British battleship Malaya and went to Malta. Two days later, on 19 November, the TBMM elected Abdülmecid Efendi as a caliph without political authority. The dynastic rule of the Ottomans, lasting six hundred and twenty-three years, thus effectively ended; the caliphate would continue symbolically for fifteen more months. Vahdeddin, who went to Malta and then to Italy, settled at the Villa Nobel in San Remo; his applications to be accepted into a Muslim country brought no result, and he died there on 16 May 1926, reiterating that he had never renounced his rights of sultanate and caliphate.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["The death of the last sultan, Mehmed VI Vahdeddin, at San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, the last Ottoman sultan, who settled in the Italian city of San Remo after leaving Istanbul, died on 16 May 1926 before learning that the caliphate congress (13 May 1926), at which he had declared that he had never renounced his rights to the sultanate and the caliphate, had convened. He was in severe financial difficulty; he owed 60,000 liras to the tradesmen of San Remo, and the creditors who heard of his death had the furnishings of his house seized.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Konuralp's conquest of the Bolu region — Mudurnu, Konurapa and Bolu", "e245cd27"], "d": ["Konuralp, one of the commanders of Orhan Gazi, turned toward the mountainous region east of the Sakarya and brought the Mudurnu, Konurapa and Bolu region under Ottoman administration; the town on the plain of Düzce was called by his name. The exact date of the conquest is not known; the account rests on the report of Aşıkpaşazade. The region was at that time a frontier zone that changed hands between the Candaroğulları and Byzantium; the conquest brought the Ottomans for the first time close to the western shore of the Black Sea. After the Battle of Ankara the region would pass again to the Candaroğulları, but it would be definitively retaken in the time of Mehmed the Conqueror.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["The taking of the Byzantine towns south of the Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["After Nicaea and Nicomedia had been taken, the towns remaining in Byzantine hands west of the Bursa plain came under Ottoman administration one by one. Gölyazı around Lake Uluabat, and Kirmasti and Mihaliç along the Susurluk stream, completed the corridor connecting the southern shore of the Marmara to the lands of Karesi. These towns surrendered for a long time without seeing a siege, as their surroundings were cut off; the Byzantine presence in the region was thus squeezed into the Gulf of Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Corinth) passed to the Despotate of the Morea", "392495eb"], "d": ["Corinth, which had been since 1358 a fief tied to the Principality of Achaea of the Florentine Acciaiuoli family, passed in 1395 into the hands of Theodore, the Byzantine despot of the Morea. From then until the Ottoman conquest the city remained under the administration of the despotate.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["The annexation of the Hacıemiroğulları Principality — Ordu and Ünye", "c064f07f"], "d": ["The Turkmen principality, founded around Ordu by Bayram Bey and expanded in the 1350s by his son Hacı Emir, was a small but strategic coastal state with its centre at present-day Eskipazar: it was the only independent area of domination between Samsun and Trebizond. Emir Süleyman had declared his allegiance in Bayezid the Thunderbolt's Canik operation of 1398, and after the Battle of Ankara the principality had become free again. In the time of Murad II, in the same years as the liquidation of the Tâceddinoğulları, the principality's lands were attached to direct Ottoman administration, and the Black Sea coast from Samsun to Giresun was united in a single hand.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["The conquest of Gördüs (Corinth)", "87a2bc59"], "d": ["In Mehmed the Conqueror's Morea campaign the fortress of Acrocorinth was besieged for three months and was finally taken over by peaceful means. The isthmus of Corinth, regarded as the gate of the Morea, thus passed to the Ottomans.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["The attachment of Montenegro to Ottoman administration — Cetinje", "7fdb7cc8"], "d": ["When the Crnojević dynasty, which ruled Zeta, gave up its sovereignty in 1496, the mountainous region of Montenegro, which was the backyard of Shkodër, was taken under direct Ottoman administration and organised first as a separate sancak, then as a part of the sancak of Shkodër. The monastery of Cetinje was left in place as the religious centre of the region. Because of the harshness of the geography, administration here never worked as tightly as on the plains; two centuries later, the vladika rule born from the same monastery would become the nucleus of de facto independence.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["The acceptance of Ottoman domination by the fortress of Bayezid in the Campaign of the Two Iraqs", "f29e2e17"], "d": ["When Grand Vizier Ibrahim Pasha came to the vicinity of Bingöl in the Campaign of the Two Iraqs, Van, Toprakkale, Avnik and Bayezid fortresses, together with many Kurdish tribes in the region, agreed to enter Ottoman domination. Bayezid had joined the Ottomans in 1514 in Selim the Grim's campaign, but when the army returned, the Safavids had retaken the region.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz passes again to the Safavids — the return from the Two Iraqs", "80b8b761"], "d": ["In the Campaign of the Two Iraqs the army had entered Tabriz, but because the real objective was Baghdad, no permanent garrison had been left in the city. As the army, having spent the winter in Baghdad, turned west, Shah Tahmasb re-entered the evacuated Azerbaijan and took Tabriz back. This was the repeated pattern of the Ottoman-Safavid wars: Tabriz was taken five times and could not be held in any of the five; the city would acquire a lasting Ottoman garrison only in 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van and Erciş fell into Tahmasb's hands (the Ottoman tenure ended in 1534-35)", "cb93d561"], "d": ["In the region that had given Van to Ottoman domination in 1534, Ulama Pasha held out in the fortress of Van against a Safavid siege; the fortress passed into Safavid hands, and the Safavid forces besieging Erciş had been pushed back with Ottoman help. By the time Süleyman the Lawgiver reached Ahlat (23 September 1535), Van was already in Tahmasb's hands. Van remained Safavid until 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["The passing of the sancak of Bayezid to Safavid domination (Van and Erciş were already Safavid in 1535)", "806a2cf1"], "d": ["The sancak of Bayezid, in the middle of the Ottoman-Safavid frontier, passed again into Iranian hands (Kaya 2017 mentions this 'together with Van and Erciş'; however, according to Karataş 2025 and the TDV, Van and Erciş had returned to the Safavids on 22 September 1535 — see the previous entry); in this change of hands some places in the sancak were ruined. The sancak changed hands between the two states many times until the last quarter of the 16th century.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["The sancak of Bayezid's passing again to the Ottomans during the Nakhchivan Campaign", "cf0171fa"], "d": ["During Süleyman the Lawgiver's third Iranian (Nakhchivan) campaign the sancak of Bayezid was taken again under Ottoman administration. In the campaign of 1554 Bayezid became an important base for the army; the sancak definitively entered Ottoman sovereignty in 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["The loss of Revan to Shah Abbas", "34413cf2"], "d": ["When the eastern front was left defenceless in the years when the Celali rebellions had paralysed Anatolia, Shah Abbas, who had reorganised his army in the European manner, went on the offensive. The fortress of Revan, built by Ferhad Pasha in 1583, surrendered after being besieged for seven months. The first link of the Caucasus line won by the Treaty of Ferhad Pasha had been broken, and within the following three years all of the South Caucasus would be lost.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["The loss of Tbilisi and Ganja", "3fb51753"], "d": ["After the fall of Revan the Safavid army advanced along the Kura valley; Ganja, the centre of Karabakh, and Tbilisi, the capital of Georgia, were lost one after the other. The Ottoman State was at the same time conducting the long thirteen-year war on the Austrian front and was occupied with the Celalis in Anatolia; there was no force to be dispatched to the east. Thus the broad order of Caucasian provinces established by the Treaty of Ferhad Pasha in 1590 effectively came to an end.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["The loss of Shirvan — Shamakhi, Baku and Derbent", "81beab11"], "d": ["The province of Shirvan on the Caspian shore, won by Özdemiroğlu Osman Pasha's campaigns of 1578-1585, had provided the Ottoman treasury with important revenue as the main source of the silk trade. Shah Abbas's operation turning northward liquidated this province by taking Shamakhi, Baku and Derbent in succession. The loss was not only territorial: the route by which Iranian silk flowed to Europe through the Ottomans also passed out of control, and the Safavid State began to market its silk via the Indian Ocean.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["The loss of Taiz", "65f20d53"], "d": ["In 1038 (1629) the Ottomans abandoned Taiz together with the domination of Yemen left to the Qasimi administration in Sana'a — the first major step in the process by which the Zaydi imams retook the interior of Yemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["The loss of Yemen — the domination of the Qasimi imams", "49e83e3c"], "d": ["Yemen had been an Ottoman province since 1538; however, the resistance of the Zaydi imams never ceased. The uprising begun by Imam al-Qasim spread across the whole country under his son al-Mu'ayyad Muhammad, and the Ottoman garrisons were besieged one after another. In the years when Murad IV was focused on Baghdad and Revan, no reinforcements could be sent; Taiz had been lost in 1629, while Mocha had been evacuated on 22 October 1635, in the final phase of the same collapse. In 1635 the last troops in Sanaa and Zabid also evacuated Yemen. Thus the eastern coast of the Red Sea remained outside the empire for two hundred and thirty-seven years, and could be recovered only in 1872. According to the TDV İslâm Ansiklopedisi, Lahij (al-Hawta) was in Ottoman hands until 1635; from that date the Zaydi imams became influential.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["The evacuation of Mocha", "c6b3061a"], "d": ["Mustafa Bey evacuated Mocha with the remaining force and arms on 10 Jumada al-Awwal 1045 (22 October 1635); then Hasan b. Qasim, the son of Imam Qasim, appointed his own men to Zabid and Mocha and established Qasimi control on the Tihama coast as well.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["The loss of al-Hasa to the Emirate of the Banu Khalid", "a9b6131a"], "d": ["Al-Hasa was a province established in 1550 to close the western shore of the Persian Gulf to Portugal; however, it was very far from Istanbul, at the end of a single desert road. In the years when the siege of Crete exhausted resources, the Banu Khalid tribe in the region, under the leadership of Barrak b. Ghurayr, expelled the Ottoman garrison and established their own emirate. The western shore of the Gulf remained for a century and a half in tribal emirates; it would pass to the Saudis in 1795 and again to the Ottomans in 1871.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["The loss of Preveza and Vonitsa to Venice — the opening of the Epirote coast", "1201204c"], "d": ["Venice, which had joined the Holy League, before beginning the Morea campaign took the two fortresses holding the mouth of the Gulf of Arta: Preveza and Vonitsa on the opposite shore. In the same summer Santa Maura (Lefkada) had also fallen. These three positions allowed the fleet to be brought safely from the Ionian Sea into the interior of Greece and became the base of the Morea operation that would begin the following year. Preveza and Vonitsa were also left with Venice at Passarowitz; they would return to Ottoman administration only in 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["The loss of Szolnok — the unravelling of the Tisza line", "51c2c8ef"], "d": ["After the fall of Neuhäusel in August, the Habsburg army turned south and took Szolnok, the bridgehead on the Tisza River. The city was the only safe crossing between Buda and Transylvania; its loss meant the severing of the Ottoman fortresses in the eastern half of Hungary from one another. The cutting of the supply road in the siege of Buda the following year was decisive.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["The loss of Modon to Venice", "114c9cc0"], "d": ["Modon, at the southwestern tip of the Morea peninsula, was the port that Venice had lost three centuries earlier and called 'one of the two eyes of the state'. The fortress, besieged after the fall of Koroni, was taken by being battered simultaneously from land and sea. Morosini's Morea operation thus captured the entire western coast of the peninsula, and the road opening to the interior was opened.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["The loss of Pécs", "99d54cf4"], "d": ["After the fall of Buda in September, Habsburg forces descended south west of the Danube and took Pécs, which had been Ottoman since the time of Süleyman the Lawgiver. The city, known for the Mosque of Gazi Kasım Pasha, was one of the most developed sancak centres of the province of Buda. Its loss meant the opening of the road descending to the plain of Mohács; the Second Mohács debacle would be experienced exactly there the following year.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["The loss of Szeged", "9fbee1b2"], "d": ["Szeged, at the confluence of the Tisza and Maros rivers, was the southern gate of the Hungarian plain and held the road to the province of Timișoara. The fortress, besieged after Buda and Pécs fell in the same autumn, surrendered in a short time. The loss of three fortresses within a season was a sign that the Ottoman administrative structure in Hungary, established since 1541, had begun to collapse.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["The loss of Patras — the northern gate of the Morea", "b9cff63c"], "d": ["Patras, at the mouth of the Gulf of Corinth, was the port controlling the passage between the Morea and Rumelia. After the Venetian army took the city, the fortresses on both sides of the gulf also fell one after another, and the peninsula was entirely isolated from the land. At the end of this operation the whole of the Morea passed to Venice; the region would be administered until 1715 under the name 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["The leaving of Gördüs (Corinth) to Venice", "9a25b6b9"], "d": ["After the fall of Patras, Corinth was left to the Venetians by peaceful means, and the Muslim population abandoned the city. In August 1687 Morosini's army was assembling at Corinth for the Athens campaign.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["The loss of Eger", "983391aa"], "d": ["Eger had been taken in 1596 in the campaign in which Mehmed III personally took part and had become the centre of a province bearing its name. This last great Ottoman fortress in northern Hungary, after the Second Mohács debacle, held out for a year completely besieged and surrendered because of hunger. With its loss the Ottoman State's northern flank in Hungary was entirely liquidated.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["The loss of Istolni Belgrade — the coronation city of the Hungarian kings", "c6147255"], "d": ["The city in which the Hungarian kings were crowned and buried for centuries had been taken in 1543 by Süleyman the Lawgiver and had become one of the most important sancak centres of the province of Buda. About two years after the fall of Buda, the fortress, its surroundings entirely cut off, surrendered. With this loss the Ottoman presence west of the Danube was squeezed into the Srem and Osijek region.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["The loss of Szigetvár", "834910a7"], "d": ["Szigetvár was the fortress where Süleyman the Lawgiver, on his thirteenth and last campaign, died in 1566 while the siege was continuing; for this reason it had a symbolic place in Ottoman memory. A hundred and twenty-three years later, after all the fortresses around it had fallen, the fortress protected by marshes also surrendered. The tomb in which Süleyman the Lawgiver's internal organs were buried, and the town around it, were destroyed after it passed to Habsburg administration.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["The loss of Várad", "6cce360d"], "d": ["Várad was the key fortress opening onto Transylvania, taken in 1660 by Köprülü Mehmed Pasha and made the centre of a province bearing its name. The fortress, left entirely alone after the Salankamen debacle, surrendered from hunger after a blockade lasting nearly two years. With its loss Ottoman influence over Transylvania effectively ended, and Habsburg domination settled east of the Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["The loss of Jenő — the closing of the Transylvanian road", "4b5e30d8"], "d": ["Jenő, taken in 1658, was a fortress holding the link between Várad and Timișoara. When its surroundings were cut off immediately after the fall of Várad, it too was lost. Thus the province of Timișoara was completely isolated from the north and continued to exist until Karlowitz as the only Hungarian territory remaining in Ottoman hands.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["The establishment of vladika rule in Montenegro — the de facto breakaway of Cetinje", "a924b778"], "d": ["In the years when the Holy League War loosened Ottoman control in the Balkans, the metropolitanate at the head of the monastery of Cetinje became an office passing from father to son in the Petrović family, and the region effectively acquired a separate administration. Thanks to the inaccessibility of the mountains, this vladikate continued for two centuries in a position neither fully independent nor fully dependent; its independence would be recognised in law only by the 1878 Treaty of Berlin.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["The recovery of Gördüs (Corinth)", "26f53e3a"], "d": ["The first great stopping place of Damad Ali Pasha's Morea campaign was Corinth; in June 1715 the Ottomans retook the city from the Venetians and advanced from here to the rest of the peninsula.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Nadir's offensive: the loss of Tabriz, Nakhchivan, Hamadan, Kermanshah, Maragheh and Qasr-i Shirin", "d95efd59"], "d": ["The cities of western Iran taken between 1723 and 1727 by exploiting the collapse of the Safavid State were lost one by one to the offensive of Nadir Khan, who had seized actual power in Iran. In Azerbaijan, Ardabil and Khalkhal also fell into Nadir's hands. The loss of Hamadan, Kermanshah and Qasr-i Shirin found a heavy echo in Istanbul; the army's not setting out on campaign but waiting at Üsküdar, and the attempt to hush up the loss, became one of the direct causes of the Patrona Halil Rebellion, which broke out six weeks later.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["The Baghavard (Arpaçay) debacle — the loss of the Caucasus to Nadir Khan", "4262f54c"], "d": ["The Caucasian provinces taken in 1723-1725 by exploiting the collapse of the Safavid State could be held for ten years. Nadir Khan, who had seized actual power in Iran, inflicted a heavy defeat on the Ottoman army at Baghavard near Revan; the commander-in-chief Abdullah Köprülü Pasha lost his life on the battlefield. Following the debacle, Revan, Tbilisi, Ganja and Shirvan were evacuated within months. The eastern frontier returned to the 1639 Qasr-i Shirin line, to be confirmed in 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["The loss of Bender to the Russians", "0daca453"], "d": ["After the Kartal Plain debacle the Ottoman army had withdrawn south of the Danube, and the fortresses between Moldavia and Özi had been left alone. Bender, which held the crossing point of the Dniester, was taken by assault after a two-month siege; the city was plundered. The loss of the fortress severed the middle link of the northern Black Sea defence line, and Akkerman and Kilia fell after it. At Küçük Kaynarca Bender would be returned, but it would be lost once again in 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["The entry of the emirate of the Sabah in Kuwait under Ottoman protection", "3584dba0"], "d": ["According to the TDV article on Kuwait, the harbour had been founded by the Utub tribe coming from Najd at the beginning of the 18th century, and the Sabah family had taken over the administration toward the end of the century. In the same years that al-Hasa passed into Saudi hands, the emirate, which had no choice but to lean on Basra in the face of Wahhabi pressure, came under Ottoman protection. The tie would be formalised in 1871 by Midhat Pasha's Basra arrangement, and Kuwait would be counted as one of the three kazas of the sancak of Basra; Iraq's later territorial claim also rests on this record.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["The loss of Mecca to the Wahhabis", "2da23acd"], "d": ["The Wahhabi movement, born in Najd, turned toward the Hejaz in the time of Saud b. Abd al-Aziz; after Ta'if and Medina, Mecca was also taken for a second time — Sharif Ghalib, the Emir of Mecca, surrendered the city to the Wahhabis on condition of remaining in the emirate. The tombs were destroyed, and the road of the pilgrim caravans coming from Damascus and Cairo was cut; the surre that the sultan sent every year to the Two Holy Cities was also interrupted in these years — the single exception to this allocation, which continued uninterrupted until 1915, is the period of Wahhabi domination. Because the title of protector of the Two Holy Cities was one of the main supports of the sultan's legitimacy, this loss was, beyond a territorial loss, a heavy political blow; its recovery would take seven years and would be possible with the army of Mehmed Ali Pasha of Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["The end of the Republic of Ragusa — French occupation", "f8e27bf1"], "d": ["The French, who had settled on the Dalmatian coast by the Treaty of Campo Formio (1797), seized Dubrovnik on 27 May 1806 and ended the small merchant republic. Thus the three-and-a-half-century tributary status of Dubrovnik, which had preserved its autonomy and trade privileges by paying tribute to the Ottomans since 1458, came to an end; the city and the republic's island of Mljet pass on the map to direct French administration.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["The loss of Sukhumi to the Russians — the opening of the eastern Black Sea coast", "adc96bd4"], "d": ["In the Ottoman-Russian war of 1806-1812 the Russian fleet turned toward the eastern Black Sea coast and took Sohumkale, on which Ottoman domination in Abkhazia rested. The fortress was the centre of contact with the Caucasian tribes and of coastal trade. With its loss Russia settled permanently on the eastern shore of the Black Sea for the first time; Ottoman influence in the Caucasus was squeezed into the area around Anapa and Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["The leaving of Parga to Ottoman administration", "66e0cc5d"], "d": ["Parga had been in Venetian hands since 1401 and had never come under Ottoman administration; after the destruction of Venice, it passed in turn to France and Britain. The TDV article on Ali Pasha of Tepelena summarises the situation thus: the city surrendered to the British and was abandoned to Ali Pasha's administration only in 1819. The transfer resulted in the migration of most of its people to the Ionian islands. Thus the last of the Preveza-Parga-Vonitsa trio left with Venice at Passarowitz was also added to the empire; Parga would remain Ottoman for ninety-four years.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["The passing of Gördüs (Corinth) to the Greek insurgents", "892dcdc6"], "d": ["During the Greek war of independence Acrocorinth fell into the hands of the insurgents, and the fortress commander Kâmil Bey was taken prisoner.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["The loss of Nauplion to the insurgents", "1a67fa50"], "d": ["Nauplion, the port with the strongest fortifications in the Morea, surrendered from hunger after a blockade of over a year. The fortress had been, since the start of the rebellion, Ottoman control's last great support on the peninsula; with its loss the whole of the Morea passed into the hands of the insurgents. The city would soon be the first capital of the new Greek state.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["The passing of Lepanto to Greek administration", "c9d19d4b"], "d": ["Lepanto, on the northern shore of the Gulf of Corinth, which had remained in Ottoman hands until the Greek rebellion, was lost in April 1829 and came under Greek administration; the name of the town was changed to the ancient Navpaktos. The Muslim and Jewish population of the city disappeared entirely, and it became a small town.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["The French occupation of Algiers — the end of the three-hundred-year ocak", "0be8f568"], "d": ["Using as a pretext the fan incident arising from a debt dispute, France kept the Algerian coast under blockade for three years, then landed troops at Sidi Ferruch. At the end of a three-week operation Hussein Dey surrendered, and the Ottoman Algiers Ocak, which had lasted since 1516, came to an end. The occupation was not limited to the capital; Tlemcen, Cherchell and Médéa in the interior were also lost the same summer. The entire coast coming under French control would take twenty-four more years.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["The giving of Negroponte to Greece — together with the island (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, which was the scene of intense fighting throughout the Greek war of independence but remained in Ottoman hands, was given to the Greeks in 1831 after the peace treaty entered into force. The Muslim population of the city, which had been an important naval base since 1470, sold all their property at very low prices and migrated en masse to Ottoman lands; the city remained empty for a long time, and the German traveller Fallmerayer in 1842 described it as a ghost city.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["The French occupation of Oran", "a8415d66"], "d": ["Oran, which Spain had handed over without a war in 1792, was the greatest port in the west of Algiers. Six months after the fall of the capital, French units entered the city. The western operation beginning from here would soon meet the resistance of Emir Abd al-Qadir, which would last fifteen years.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["The occupation of Annaba (Bône)", "21f37fb1"], "d": ["Annaba, the port of eastern Algeria near the Tunisian border, was taken by French forces and made the base for the march on Constantine. The city was at the same time the nearest African port opposite the island of Sardinia.", "1ca5b213"]},
"OLAYLAR_EK6:1833-03-31:0":{"b": ["The leaving of Athens to the new Greek state", "98af5572"], "d": ["Athens, Ottoman since 1456, had changed hands several times during the Greek war of independence, and the garrison on the Acropolis had passed again under Ottoman control in 1827. Because it lay north of the border drawn by the London Protocol, the city was handed over to the new kingdom, and the garrison evacuated the Acropolis. The following year Athens was declared the capital of Greece in place of Nauplion.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["The occupation of Bijâya (Bougie)", "a8927e00"], "d": ["The port of Bijâya, where the Kabylia mountains open to the sea, was the last independent link of the coastal line between Algiers and Annaba. It was taken with the support of naval artillery; however, the mountainous interior behind it would not come under French control for thirty more years. These coastal occupations make up the year-by-year melting away of Ottoman Algiers on the map.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["The occupation of Sétif", "2073731a"], "d": ["After the fall of Constantine a year earlier, French forces climbed onto the plateau and, taking the old Roman city of Sétif, established a permanent garrison there. Sétif was the point where the caravan routes between the coast and the Sahara intersected; its occupation showed that France had begun to control not only the ports but also the inland trade network.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["The occupation of Biskra — the loss of the gate of the Sahara", "d895cad0"], "d": ["Biskra, on the southern foot of the Atlas mountains, was the gate opening onto the Sahara and the centre of the date-palm oases. With its taking, in the years when the resistance of Emir Abd al-Qadir began to break, French control reached the northern edge of the desert for the first time. What followed would be a desert operation advancing oasis by oasis.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["The occupation of Touggourt — the loss of the whole of Algeria", "33c056e2"], "d": ["With the taking of Touggourt, the oasis city north of the Sahara, the occupation begun in 1830 was completed in the northern half of present-day Algeria. In these years the Ottoman State was fighting in the Crimean War on the same side as France; although it never formally abandoned its legal claim over Algeria, it could not in fact take a single step. The only land left in North Africa was Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["The fall of El Obeid — Kordofan passing to the Mahdist forces", "58299f62"], "d": ["The movement begun by Muhammad Ahmad, who proclaimed himself the Mahdi, spread rapidly against Egypt's administration in Sudan. El Obeid, the centre of Kordofan, fell after a four-month siege and became the capital of the rebellion; the treasury and arms depots in the city enabled the movement to become an army. Sudan was legally still territory of the Egyptian khedivate attached to the Ottomans, and therefore the loss falls away from the imperial body on the map.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["The fall of Khartoum — the loss of the whole of Sudan", "d4b98464"], "d": ["After a siege lasting ten months, Mahdist forces entered Khartoum, at the confluence of the Blue Nile and the White Nile; the governor of the city, Gordon, was killed, and the British column sent to help was two days late. After this date all of Sudan, including Sennar, Dongola and Kordofan, remained for fourteen years under the administration of the Mahdist State. The region would enter British-Egyptian joint administration only in 1899, with the Ottoman tie completely severed.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["The Italian occupation of Massawa — the loss of the western shore of the Red Sea", "c333b95b"], "d": ["The port of Massawa, the centre of the province of Habeş, was occupied by Italy, which took advantage of the turmoil in which the Mahdist rebellion covered Sudan; this formed the nucleus of Italian Eritrea. Suakin in the north and the Dahlak archipelago offshore were also lost in the same process. Thus Ottoman domination on the western shore of the Red Sea, which had lasted since the time of Selim the Grim, came to an end, and the sea became waters foreign on both of its sides.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["The Italian occupation of Rhodes", "e08662c5"], "d": ["Italy, wishing to bring the Ottoman State to the table in the Tripolitanian War, carried the war to the Mediterranean and landed troops on Rhodes. The island was taken over within a few days. Rhodes, which Süleyman the Lawgiver had taken in 1522 after a long siege and which was held for three hundred and ninety years, thus ceased to be the empire's greatest island base in the eastern Mediterranean; although it was counted as a temporary occupation in the Treaty of Ouchy, it could not be retaken again.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["The Italian occupation of the Dodecanese", "200aacf2"], "d": ["Within a week of the taking of Rhodes, the Italian fleet also occupied the surrounding islands; this archipelago would later be given the name 'Dodecanese'. Most of the islands were a few miles from the Anatolian coast and controlled the southeastern passage of the Aegean. The occupation was regarded as temporary in the Treaty of Ouchy in return for the abandonment of Tripolitania, but Italy never evacuated the islands; they would be handed over to Greece in 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["The occupation of Kos", "ab246c62"], "d": ["Kos, the last link of the Dodecanese operation, was a fertile and populous island immediately opposite the Bodrum peninsula. With the occupation, all the islands in the southeastern corner of the Aegean came under Italian control, and the southwestern coast of Anatolia was surrounded along its whole length by a chain of foreign islands.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["The declaration of independence of Nikaria", "c4452033"], "d": ["On the small island of Nikaria between Samos and Chios, the people, in the climate of uncertainty created by the Italian occupations, rose up and expelled the Ottoman gendarmerie from the island, and declared a 'free state' lasting five months with their own flag, stamp and assembly. In November 1912 the island was united with Greece. Despite its smallness, this event is a clear indication of how central administration was dissolving in the Aegean.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Samos's departure from Ottoman administration", "3a862f2b"], "d": ["Samos was an autonomous principality that had paid taxes to the Ottomans since 1832 and was governed by a prince appointed by Istanbul. In the vacuum created by the Tripolitanian War, the pro-union movement on the island seized the administration, and the autonomous principality order effectively came to an end; within the same year the island declared its union with Greece. This island, two kilometres from the Anatolian coast, became one of the first lands lost in the Aegean.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["The fall of Ioannina — the loss of Epirus and Parga", "d42fce18"], "d": ["Ioannina, besieged for five months in the Balkan War, surrendered after the fall of the Bizani positions; with the city the whole of Epirus passed to Greece. Parga, attached to the sancak of Ioannina, was also lost on this date, and ninety-four years of Ottoman administration ended. The loss of Ioannina meant the closing of the empire's last window opening onto the Adriatic.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["The fall of Edirne to the Bulgarians", "459d2e56"], "d": ["After a siege lasting five and a half months, Edirne, its ammunition and provisions exhausted, surrendered; Şükrü Pasha was taken prisoner. The fall of the city, Ottoman since 1361 and capital for ninety-two years, was regarded as the heaviest blow of the Balkan War. Edirne would be retaken four months later, in the Second Balkan War, by exploiting Bulgaria's collapse on the other fronts.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["The loss of Yanbu to the forces of Sharif Hussein", "e291c816"], "d": ["The uprising begun by Sharif Hussein in June spread to the Red Sea coast; Yanbu, the port of Medina, fell into the hands of the rebels with the support of the British fleet. The port became the main gate of the flow of arms and money coming from outside to the uprising. Thus the connection by sea of the forces of Fahreddin Pasha in Medina was cut, and the city was left alone at the end of the Hejaz railway.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["The Third Battle of Gaza — the loss of Gaza and Khan Yunis", "c142a069"], "d": ["After two failed attempts, Allenby in his third attack broke through the front by going around Beersheba, and the Gaza line, held for six months, collapsed. Gaza and Khan Yunis to its south were evacuated the same day. This breakthrough was the beginning of the disintegration of the Palestine front; Jerusalem would fall five weeks later.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["The occupation of Komotini — the loss of Western Thrace", "904d813c"], "d": ["Western Thrace, which after Mudros first came under the control of Allied units, was left to Greece by the decision of the San Remo conference, and the Greek army entered Komotini. The region, which had been retaken from Bulgaria in 1913, became the last land the empire lost in Rumelia. The status of the Turkish population in the region would be regulated three years later at Lausanne with a minority regime.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["The disintegration of the Ilkhanate: the death of Abu Sa'id Bahadur Khan", "0f187469"], "d": ["According to the TDV Encyclopaedia of Islam article on the İlhanlılar, Abu Sa'id's death without leaving an heir led to the fragmentation of the Ilkhanate, which had ruled Iran for a century; the emirs, taking advantage of the struggles for the throne, founded local dynasties such as the Jalayirids, the Qaraquyunlu, the Muzaffarids, the Sarbadars of Khorasan and the Eretnids. This disintegration divided the region into a mosaic of principalities that would last a century; it would ultimately be reunited by Timur's campaigns.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Timur's bringing the greater part of Iran under his domination", "1cee2b82"], "d": ["According to the TDV Encyclopaedia of Islam article on Timur, Timur, who from the early 1380s eliminated one by one the post-Ilkhanid local dynasties such as the Sarbadars, the Kartids and the Muzaffarids, effectively brought the greater part of Iran under his domination during the 'three-year campaign' of 1386-1388; the final blow to the Muzaffarid dynasty would be dealt in 1393. The region was thus again bound to a single central authority after a century of fragmentation.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Battle of the Aras: Qara Yusuf defeated the Timurid Abu Bakr Mirza", "4b61a75a"], "d": ["After returning from exile following Timur's death in 1405, the Qaraquyunlu ruler Qara Yusuf took Avnik and regained his lands in Eastern Anatolia; he then marched against Timur's grandson Abu Bakr Mirza, who was regarded as the master of Azerbaijan and the two Iraqs, and defeated him on the banks of the Aras. This victory did not give Tabriz to the Qaraquyunlu: the TDV entry `tebriz` states that the city was in the hands of Abu Bakr Mirza in 1408; the battle that won Azerbaijan is Sardrud on 13 April 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Victory at Sardrud: Tabriz and Azerbaijan passed to the Qaraquyunlu", "1f0a429d"], "d": ["Qara Yusuf defeated the Timurid Abu Bakr Mirza for a second time after the Aras, at Sardrud near Tabriz; this victory won Azerbaijan for the Qaraquyunlu. Qara Yusuf then charged Bistam Beg with the conquest of Persian Iraq;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Plague epidemic in Istanbul and the move of the palace to Edirne", "70c7a163"], "d": ["According to the TDV Encyclopaedia of Islam article on Istanbul, the rapid and dense settlement of the city prepared the ground for the spread of epidemic diseases from time to time; during the plague epidemic of 1466 the palace and the dignitaries of the state temporarily withdrew to Edirne. The population of the city suffered serious losses in such epidemics.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan's end of the Qaraquyunlu State", "ef68399e"], "d": ["According to the Uzun Hasan entry of the TDV İslâm Ansiklopedisi, the Aqquyunlu ruler Uzun Hasan defeated and killed the Qaraquyunlu ruler Jahan Shah in the Bingöl-Sancak region on 12 Rabi' al-Akhir 872 / 10 November 1467; Jahan Shah's son Hasan Ali was defeated at Merend in September 1468 and killed before Hamadan in April-May 1469, and the Qaraquyunlu State was brought to a definitive end. The lands passed under Aqquyunlu rule; over the following decade the state would expand as far as the interior of Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["The opening to instruction of the Sahn-ı Semân madrasas", "021f2a83"], "d": ["According to the TDV Encyclopaedia of Islam article on Sahn-ı Semân, these eight madrasas, established within the Fatih Complex, were designed as the highest-level educational institution of the period and formed the summit of the Ottoman ilmiye hierarchy. A professorship and graduation from here were regarded in the following centuries as the most prestigious step in the careers of kadı and müderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["The completion of Topkapı Palace (Saray-ı Cedîd)", "d2db6323"], "d": ["According to the TDV Encyclopaedia of Islam article on Topkapı Palace, the sources of the period diverge on the start and end dates of the construction; according to the date 883 (1478) on the inscription of the Bâb-ı Hümâyun, the construction, begun by order of Mehmed the Conqueror probably in 1465, had been largely completed by this year, and the palace took the place of the centre of the state in the old palace. Thus the sultan moved to the new residence that would be the administrative and ceremonial heart of the state for three centuries.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["The accession of Bayezid II in Istanbul", "9b686d04"], "d": ["According to the TDV Encyclopaedia of Islam article on Bayezid II, Prince Bayezid, the sancak bey of Amasya, upon the news of his father's death came quickly to Istanbul and ascended the throne; he outstripped his brother Cem's departure from Konya with the support of the Janissaries. At the accession, the accession gratuity customary for the Janissaries was distributed. This change of throne also lit the fuse of the struggle between the two brothers.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan's proclaiming himself sultan in Bursa", "b355168a"], "d": ["According to the TDV Encyclopaedia of Islam article on Cem Sultan, Cem, who reached Bursa by way of Karaman, seized the city, proclaimed himself sultan and had the khutba read. This short-lived sultanate ended when the forces sent by his elder brother Bayezid II defeated Cem at Yenişehir. After the defeat, Cem was forced to flee toward Egypt.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["The execution of Gedik Ahmed Pasha", "6d75a58c"], "d": ["According to the TDV Encyclopaedia of Islam article on Gedik Ahmed Pasha, the pasha, known for the Otranto campaign and his grand vizierate, was executed at Edirne on the order of Bayezid II because of his attitude in the matter of Cem Sultan and concern over his influence. The death of one of the most experienced commanders of the time of Mehmed the Conqueror aroused a wide echo in the palace.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["The founding of the first printing press in Istanbul", "04475930"], "d": ["According to the TDV Encyclopaedia of Islam article on Matbaa, the Jewish immigrants from Spain, the brothers David and Samuel ibn Nahmias, founded in Istanbul the first printing press to print in Hebrew letters. This went on record as the first printing venture operating in Ottoman lands; printing in Turkish-Arabic script would become possible much later, in the 18th century.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Shah Ismail's capture of Tabriz: the founding of the Safavid State", "014d81e6"], "d": ["According to the Safavids and Aqquyunlu entries of the TDV İslâm Ansiklopedisi, Ismail, the young sheikh of the Ardabil lodge, with an army raised from his Qizilbash disciples in Anatolia, inflicted a heavy defeat on the Aqquyunlu Sultan Alvand in the Nakhchivan region; Alvand fled to Diyarbekir, Ismail entered Tabriz and ascended the throne, and proclaimed Twelver Shiism the official creed. Thus both Aqquyunlu rule and the region's post-Ilkhanid era of principalities came to a close; the Safavid State, which would last three centuries, was founded.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["The 'Lesser Doomsday' earthquake in Istanbul", "53e3b1d6"], "d": ["According to the TDV Encyclopaedia of Islam article on Istanbul, the severe earthquake that struck the city was remembered among the people as the 'Lesser Doomsday'; heavy damage occurred to the walls, mosques and many buildings, and there was a large loss of life. By order of Bayezid II, a wide-scale repair and reconstruction mobilisation was begun in the city.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["The start of the Şahkulu rebellion", "3d9a4a90"], "d": ["According to the TDV Encyclopaedia of Islam article on Şahkulu Baba Tekeli, Şahkulu, nourished by Safavid propaganda, gathered a large Turkmen mass around him in the Teke region and began a great rebellion of a religious-social character. The rebellion, as one of the most serious internal security crises of the period, deeply shook the central authority of the state.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["The death of Bayezid II on the road to Dimetoka", "c46e98c9"], "d": ["The former sultan, who after abdicating left Istanbul to go to Dimetoka, the city of his birth, fell ill at the village of Abalar near Çorlu while advancing in his litter, which could cover only 5-6 km a day, and died on 25 Rabi al-Awwal 918 (10 June 1512). The TDV Encyclopaedia of Islam finds the cause of death very suspicious; according to some native and foreign sources, the possibility that he was poisoned is emphasised. After a reign of thirty-one years, the eighth sultan of the line of Osman Gazi thus lost his life.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["The execution of Prince Ahmed on the order of Selim the Grim", "65abb2f2"], "d": ["According to the TDV Encyclopaedia of Islam article on Selim I, Prince Ahmed, the favourite of his father Bayezid II and the real rival for the throne, was routed on the plain of Yenişehir in the struggle he undertook after his brother Selim's accession, and was caught and killed while fleeing from the battlefield. With this event Selim largely ended the rivalry for the throne among his brothers and nephews.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ibrahim Pasha appointed grand vizier", "9c94c1e3"], "d": ["According to the TDV Encyclopaedia of Islam article on Ibrâhîm Pasha, Makbul, Ibrahim Pasha, who was promoted from chief of the privy chamber to the beylerbeylik of Rumelia and on the same day to the grand vizierate, became grand vizier on 13 Sha'ban 929 (27 June 1523). This was an unprecedented appointment, moving directly from palace service to the grand vizierate, and showed Ibrahim Pasha's extraordinary closeness to Süleyman the Lawgiver.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbarossa Hayreddin Pasha appointed kapudan pasha", "a0ff6bab"], "d": ["According to the TDV Encyclopaedia of Islam article on Barbaros Hayreddin Pasha, Hayreddin Pasha, known for his successes in Algiers, was summoned to Istanbul on 6 April 1534 and appointed to the kapudan pashalık and the beylerbeylik of Cezâyir-i Bahr-i Sefîd. This appointment is regarded as the beginning of the restructuring of the Ottoman navy and the institutionalisation of naval power in the Mediterranean.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pasha became grand vizier for the first time", "ddfcc014"], "d": ["According to the TDV Encyclopaedia of Islam article on Rüstem Pasha, after Hadım Süleyman Pasha was dismissed following a disagreement he had with a vizier, Rüstem Pasha was appointed to the grand vizierate on 17 Ramadan 951 (2 December 1544). Rüstem Pasha, whose closeness to the palace increased through his marriage to Mihrimah Sultan, became with this office one of the most influential statesmen of the age of Süleyman the Lawgiver.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebussuud Efendi became şeyhülislam", "11ed04f8"], "d": ["According to the TDV Encyclopaedia of Islam article on Ebüssuûd Efendi, Ebussuud Efendi, who had served for eight years as kazasker of Rumelia, was appointed to the şeyhülislamate in Sha'ban 952 (October 1545) and remained in this office for twenty-eight years and eleven months. Ebussuud Efendi, known for his fatwas that brought the kanunnames of Süleyman the Lawgiver into harmony with the sharia, played a decisive role in the shaping of the legal and educational institutions of his time.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Barbarossa Hayreddin Pasha died", "3378a0bf"], "d": ["According to the TDV Encyclopaedia of Islam article on Barbaros Hayreddin Pasha, after a short illness he died in Istanbul on 6 Jumada al-Awwal 953 (5 July 1546). The death of Barbarossa, who was buried in the tomb adjoining the madrasa he himself had built at Beşiktaş, was seen as the close of an era in the Mediterranean supremacy established by the Ottoman navy.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Construction of the Süleymaniye Mosque and complex began", "101ec36f"], "d": ["According to the TDV Encyclopaedia of Islam article on the Süleymaniye Mosque and Complex, the complex, whose foundation was laid in 1550 under the chief architect Mimar Sinan, was designed as a great social complex made up, besides the mosque, of madrasas, a hospital, a soup kitchen and a library. The construction was one of the greatest building programmes symbolising the power of Süleyman the Lawgiver's reign and the development of Istanbul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["A new wave of plague began in Istanbul and its surroundings", "547d6bf6"], "d": ["According to the TDV Encyclopaedia of Islam article on Tâun, one of the 16th-century epidemics affecting the Islamic world occurred between 1552 and 1566 and was especially effective in Istanbul, Anatolia, Rumelia, Egypt and North Africa. Expanding trade routes and increasing population mobility are counted among the factors that facilitated the spread of epidemic diseases in the empire's most powerful period.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pasha appointed grand vizier", "a7d7748e"], "d": ["According to the TDV Encyclopaedia of Islam article on Kara Ahmed Pasha, Kara Ahmed Pasha, who was serving as second vizier, was promoted to the grand vizierate on 27 Shawwal 960 (5 October 1553) after the sudden dismissal of the existing grand vizier. This change points to a period, coinciding with the days of Prince Mustafa's execution, in which the balances of power within the palace changed hands rapidly.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Kapudan pasha Piri Reis was executed", "3b2ad7a0"], "d": ["According to the TDV Encyclopaedia of Islam article on Pîrî Reis, when the accusations that, while lifting the siege of Hormuz, he had plundered the property of Muslims in return for bribes and had abandoned his army on the battlefield reached Egypt, the famous seaman and cartographer was executed at Cairo at the end of the year 960 (late 1553). The death of Piri Reis, whose property was confiscated, is regarded as a result of the rivalry among pashas in the Basra and Indian Ocean naval policy of the time.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pasha was executed, Rüstem Pasha became grand vizier again", "9a85076a"], "d": ["According to the TDV Encyclopaedia of Islam articles on Rüstem Pasha and Kara Ahmed Pasha, in place of Kara Ahmed Pasha, who was suddenly executed during a divan meeting on 13 Dhu al-Qa'da 962 (29 September 1555), Rüstem Pasha was made grand vizier for the second time the same day, with the support of the sultanas Hürrem and Mihrimah. The background of the incident is left open in the sources and has been assessed as the result of palace intrigues.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Hürrem Sultan died", "1ae998b5"], "d": ["According to the TDV Encyclopaedia of Islam article on Hürrem Sultan, Hürrem Sultan, who as the haseki sultan of Süleyman the Lawgiver had held great influence within the palace for years, died in Istanbul on 26 Jumada al-Akhira 965 (15 April 1558) and was buried in her tomb in the Süleymaniye Mosque complex. Hürrem Sultan, who had consolidated her authority over the harem after the death of Valide Sultan Hafsa in 1534, with her death also removed the balancing effect in the way of the rivalry for the throne between her sons Bayezid and Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Pasha rose to the grand vizierate", "896391a2"], "d": ["According to the TDV Encyclopaedia of Islam article on Sokollu Mehmed Pasha, Sokollu Mehmed Pasha, who rose to the grand vizierate upon the death of Semiz Ali Pasha on 30 Dhu al-Qa'da 972 (29 June 1565), became the last grand vizier of Süleyman the Lawgiver and, continuing in this office after him in the reigns of Selim II and Murad III, became one of the longest-serving grand viziers in Ottoman history.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II reached Istanbul and acceded to the throne", "0289ef97"], "d": ["After the death of Süleyman the Lawgiver at Szigetvár, the news was kept secret for weeks by Sokollu Mehmed Pasha in order not to disturb order. According to the TDV Encyclopaedia of Islam, while Selânikî gives the date of Selim's arrival in Istanbul as 15 Rabi al-Awwal 974 (30 September 1566), most contemporary historians accept 9 Rabi al-Awwal (24 September) as correct. The death of Süleyman the Lawgiver was officially announced only on 24-25 October 1566 in Belgrade.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["The fleet rebuilt by Kılıç Ali Pasha put to sea", "d0fc9f48"], "d": ["After the heavy defeat at Lepanto (7 October 1571), ships were built in the shipyards throughout the winter. According to the TDV Encyclopaedia of Islam, on 1 Safar 980 (13 June 1572) the new fleet, consisting of 250 galleys and about 300 volunteer reis galleys, was launched in a show of strength.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pasha was assassinated", "6ffa8dec"], "d": ["Sokollu Mehmed Pasha, who had served fourteen years as grand vizier under three sultans, was stabbed to death on 20 Sha'ban 987 (12 October 1579) by a dervish who approached as if to hand a petition to the afternoon divan in his mansion. According to the TDV Encyclopaedia of Islam, it is debated whether the assassination may have been connected with vengeance for the executed Hamzawi sheikh Hamza Bali.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["The first commercial ahidname with England — capitulations granted to the English", "59c8e3ee"], "d": ["William Harborne, the English representative sent to Istanbul in October 1578, obtained an ahidname dated 1580 from Murad III with the support of Sokollu Mehmed Pasha and Hoca Sadeddin Efendi. With this ahidname, English merchants gained the right to benefit to the same degree from the commercial privileges (capitulations) previously granted to the French and the Venetians. Letters were exchanged between Queen Elizabeth I and Murad III, and an official relationship was also established between the two states. Immediately after these privileges, the Levant Company was founded in London in 1581; the English conducted their trade in the region through this company until 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["The Istanbul Observatory was demolished by hatt-ı hümâyun", "3bc0c78c"], "d": ["Under the influence of a fatwa to the effect that observatories bring ill fortune to countries and of opposition in the palace, the Istanbul Observatory was demolished with all its instruments by a hatt-ı hümâyun dated 4 Dhu al-Hijja 987 (22 January 1580). According to the TDV Encyclopaedia of Islam, this was the short-lived end of the institution founded by Taqi al-Din al-Rasid.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["The circumcision festival of Prince Mehmed at the Hippodrome began", "c2926d5d"], "d": ["Prince Mehmed, the son of Murad III, was circumcised with magnificent ceremonies that began on 6 Jumada al-Awwal 990 (29 May 1582) and lasted fifty-six to fifty-seven days. According to the TDV Encyclopaedia of Islam, the festivities held at the Hippodrome were among the most splendid palace celebrations of the period.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Nurbanu Valide Sultan died", "77d0a577"], "d": ["Nurbanu Sultan, the mother of Murad III, died on 22 Dhu al-Qa'da 991 (7 December 1583). According to the TDV Encyclopaedia of Islam, as valide sultan she had conducted correspondence with the courts of Venice and France, and the Venetian Senate had agreed that same year to send her a gift worth 2000 Venetian gold pieces in return for her services.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["The Beylerbeyi Incident broke out because of the debased akçe", "db2f2e61"], "d": ["When the state made payments by lowering the silver content of the akçe, the sipahis and Janissaries besieged the palace and raised a bloody uprising that went down in history as the Beylerbeyi Incident. According to the TDV Encyclopaedia of Islam article on Abdülkadir Şeyhî Efendi, the şeyhülislam was dismissed from office as a result of this event.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III acceded to the throne, nineteen princes were strangled", "2cd9a8c5"], "d": ["Mehmed III, upon the death of his father Murad III, reached Istanbul on Friday, 16 Jumada al-Awwal 1003 (27 January 1595) and ascended the throne. According to the TDV Encyclopaedia of Islam, nineteen princes, four of them adults (Mustafa, Bayezid, Osman and Abdullah), were strangled to death the same night; this was the most numerous fratricide in Ottoman history.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan gained influence as valide sultan", "000bec21"], "d": ["Safiye Sultan, the consort of Murad III and the mother of Mehmed III, rose with her son's accession to a decisive position in palace politics as valide sultan. According to the TDV Encyclopaedia of Islam, in this period influence stemming from the harem reached the point of direct interference in affairs of state.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III set out on campaign in person under Janissary pressure", "d3c50656"], "d": ["Despite the opposition of Grand Vizier Damad Ibrahim Pasha, under the pressure of the Janissaries Mehmed III set out from Istanbul on campaign on 20 June 1596 as the first sultan since Süleyman the Lawgiver to take command of the army in person. According to the TDV Encyclopaedia of Islam, this meant the revival of the old tradition of ghaza.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["The plague epidemic that began in the 1570s continued to affect Istanbul", "eb4ca37a"], "d": ["According to the TDV Encyclopaedia of Islam article on Tâun, the epidemic that began in the 1570s continued its effect until the beginning of the 17th century and struck Anatolia, the Balkans, Egypt and North Africa, above all Istanbul. Periods of epidemic constituted a chronic threat that frequently interrupted palace and city life.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim died, the rebel movement weakened", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, who withdrew wounded after the heavy defeat he suffered on 12 August 1601 at Sepetli near Elbistan, died in the year 1010 (1602). According to the TDV Encyclopaedia of Islam, the news of his death reached Istanbul in Ramadan of the year 1010 (February-March 1602); the sources note that it is disputed whether his death resulted from the wound or was carried out by his own men.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["The effective end of the tradition of fratricide", "9046c607"], "d": ["At his accession, Ahmed I, unlike the previous sultans, did not have his brother Prince Mustafa killed but spared his life; this decision is regarded as the beginning of the effective adoption of the principle of seniority (ekber-erşed) in the Ottoman system of succession. The TDV Encyclopaedia of Islam article on 'Mustafa I' relates that from this date Mustafa led a life of seclusion in the palace. The practice brought a de facto end to the accession murders that had continued for centuries.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["The foundation of the Sultanahmet Mosque was laid", "1683262f"], "d": ["By order of Ahmed I, the foundation of the mosque, to be built by the architect Sedefkâr Mehmed Agha, was laid with a ceremony at the Hippodrome. According to the TDV Encyclopaedia of Islam article on 'Sultan Ahmed Mosque and Complex', the building also became the subject of contemporary criticism as the first great imperial mosque built directly from the treasury without a conquest victory. The complex was designed to include, together with the mosque, a madrasa, a soup kitchen and a tomb.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["The killing of Osman the Young by the Janissaries (Hâile-i Osmâniye)", "324f6582"], "d": ["The Janissaries and sipahis, who rose up upon rumours that he planned to leave Istanbul under the pretext of the pilgrimage and to dissolve the Janissary corps, deposed Osman II and had him strangled in the dungeons of Yedikule. According to the TDV Encyclopaedia of Islam article on 'Osman II', this event is the first case in Ottoman history of a sultan being openly killed by a military rebellion and created a deep rupture in the relationship between dynasty and army. His last hours passed as follows: when his attempt to take refuge in the mansion of the Janissary agha Ali Agha produced no result, the sultan, in the words of the TDV, 'in a pitiful state, bareheaded and in disarray', was put on a nag and taken, under heavy insults, first to the Orta Cami, where Mustafa I was, and in the afternoon of the same day to Yedikule; according to some historians, to prove his death his ear and nose were cut off and shown to the mother of Mustafa I. After the event Mustafa I was placed on the throne for the second time. The event, known as 'Hâile-i Osmâniye' (the Osman calamity), permanently upset the palace-corps balance and began the debates over legitimacy that would continue for a century.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["The second accession of Mustafa I", "34a0b29a"], "d": ["After the killing of Osman the Young by the Janissaries, since there was no other adult male member in the dynasty, Mustafa I was placed on the throne for the second time. According to the TDV Encyclopaedia of Islam article on 'Mustafa I', this second reign, no differently from the first, passed without his being able actually to conduct the affairs of state, and the administration of the state was left to the viziers and the valide sultan. This period, lasting fourteen months, ended in 1623 with the accession of Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["The Cibali Fire", "3e42fb08"], "d": ["The fire that broke out in Cibali and spread rapidly under the effect of the wind reduced a large part of Istanbul to ashes; according to the TDV Encyclopaedia of Islam article on 'Istanbul', the sources of the period relate that thousands of houses burned. The association of the fire with the wooden house fabric and with tobacco smoking became the direct justification for the harsh ban on tobacco and coffeehouses that Murad IV would proclaim shortly afterwards. The disaster was only one of the repeated great fires in the Istanbul of the period.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Murad IV's ban on tobacco and coffeehouses", "5dd71297"], "d": ["After the Cibali Fire, out of concern for fire and public order, Murad IV banned tobacco smoking and coffeehouses; heavy penalties, including the death penalty, were applied to those who did not comply. According to the TDV Encyclopaedia of Islam article on 'Murad IV', the sultan followed so strict a policy of internal discipline that he roamed the streets of the city in disguise himself to enforce the ban. These harsh measures are regarded as part of Murad IV's effort to re-establish central authority.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Plague epidemic in Istanbul", "f33f58c5"], "d": ["In the time of Murad IV, Istanbul was shaken by a severe plague epidemic that affected a significant part of the population; trade within the city and daily life were disrupted for months. The TDV Encyclopaedia of Islam article on 'Istanbul' records that the repeated epidemics of the 17th century seriously affected the city's population balance. During the epidemic the palace and the elite moved for a time to gardens and pavilions outside the city.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Hezarfen Ahmed Çelebi's winged flight (legend)", "df474c04"], "d": ["According to the account related by Evliya Çelebi, Hezarfen Ahmed Çelebi managed to glide from the Galata Tower as far as Üsküdar with wings he had made himself; although its historical certainty is disputed, it became a symbol of technical imagination. The sultan, who had at first rewarded Hezarfen, later exiled him to Algiers because of the stir the event caused.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi gained influence in the palace", "41d21572"], "d": ["Hüseyin Efendi, an exorcist summoned to the palace to treat Sultan Ibrahim's psychological troubles, quickly won the sultan's trust and rose as far as the kazaskership of Anatolia. According to the TDV Encyclopaedia of Islam article on 'Hüseyin Efendi, Cinci Hoca', he used this influence to accumulate wealth and to interfere in the political events of the period. After Ibrahim's death he was removed from all his offices and executed in 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["The execution of Kemankeş Mustafa Pasha", "0ecc8030"], "d": ["Kemankeş Mustafa Pasha, who had been grand vizier since the time of Murad IV and had earned the treasury a significant surplus with his financial reforms, was strangled and executed after his rivals in the palace influenced Ibrahim and accused him of raising a Janissary uprising. According to the TDV Encyclopaedia of Islam article on 'Kemankeş Mustafa Pasha', his execution took place on 21 Dhu al-Qa'da 1053 / 31 January 1644: Kemankeş Kara Mustafa Pasha was strangled by the executioner Kara Ali in the Hocapaşa Bazaar and buried in his own tomb at Çarşıkapı. His death is remembered as a striking example of the instability of the grand vizierate in the period, and it ended a short period of strict reform.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["The Cretan Campaign was decided in the divan and the fleet set out", "9076827e"], "d": ["The opening of a large-scale campaign against the island of Crete, belonging to Venice, was decided in the Imperial Council, and the Ottoman fleet under the command of the kapudan pasha moved from Istanbul toward Crete. According to the TDV Encyclopaedia of Islam article on 'Crete', this decision formed the political beginning of a long period of siege and war lasting about twenty-five years. The opening of the campaign had led to wide debates among the statesmen as the greatest foreign-policy venture of Ibrahim's reign.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Mehmed IV's accession at the age of seven", "a197a3bc"], "d": ["Immediately after Ibrahim's deposition, his son Mehmed, only seven years old, was placed on the throne and became sultan with the title Mehmed IV. According to the TDV Encyclopaedia of Islam article on 'Mehmed IV', such a young accession to the throne intensified the struggle for influence within the palace between his grandmother Kösem Sultan and his mother Turhan Sultan. This power struggle would end in 1651 with the killing of Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Tarhuncu Ahmed Pasha's balanced-budget reform", "376fc7f2"], "d": ["Grand Vizier Tarhuncu Ahmed Pasha, in order to overcome the financial crisis caused by the long years of war, implemented a harsh austerity programme that also covered palace expenses and prepared the first known balanced budget in Ottoman history (the tarhuncu memorandum). According to the TDV Encyclopaedia of Islam article on 'Tarhuncu Ahmed Pasha', this reform earned the treasury a significant surplus, but it created wide discontent among the palace circle and the high bureaucracy. This discontent would result a year later in his execution.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["The Plane Tree Incident (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["According to the TDV Encyclopaedia of Islam article on the Çınar Vak'ası, the Janissaries and sipahis who returned from the Cretan campaign without pay rose up in Istanbul and demanded the execution of the statesmen they accused of corruption. Grand Vizier Zurnazen Mustafa Pasha's proposal of confiscation and exile was not accepted; first three officials, then nearly thirty statesmen were executed, and their bodies were hung from the plane trees in the Sultanahmet Square. The event was therefore called the Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Köprülü Mehmed Pasha appointed grand vizier on conditional acceptance", "3a6b7f8f"], "d": ["According to the TDV Encyclopaedia of Islam article on Köprülü Mehmed Pasha, Köprülü Mehmed Pasha, nearly eighty years old, took the seal only after having Valide Turhan Sultan and Mehmed IV accept the heavy conditions he presented — that his appointments not be interfered with and that what was said against him not be believed. He took office on 26 Dhu al-Qa'da 1066 in place of Boynueğri Mehmed Pasha and set about re-establishing state discipline severely.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["The suppression of the Kadızadeli movement by Köprülü Mehmed Pasha", "5ec3ce84"], "d": ["According to the TDV Encyclopaedia of Islam article on the Kadızâdeliler, as soon as he took office Köprülü Mehmed Pasha took up the religious conflict between the circle of Kadızâde Mehmed Efendi and the followers of the tarikats. After consulting the ulema, although he had death decrees issued for the leaders of the movement, Üstüvânî Mehmed Efendi, Türk Ahmed and Divâne Mustafa, this penalty was commuted to exile, and the three were sent to Cyprus; thus the second phase of the movement ended.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Great fire in Istanbul: the burning of the Ağakapısı", "b9253b66"], "d": ["According to the TDV Encyclopaedia of Islam article on Ağakapısı, in the great fire that broke out in July 1660 in the time of Mehmed IV, the Ağakapısı, the official headquarters of the Janissary agha, burned down completely and was rebuilt afterwards. This fire was one of the great city fires that struck the Istanbul of the period again and again.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Köprülüzade Fazıl Ahmed Pasha appointed grand vizier", "c1999b5c"], "d": ["According to the TDV Encyclopaedia of Islam article on Köprülüzade Fazıl Ahmed Pasha, upon the death of his father Köprülü Mehmed Pasha he was made grand vizier on 8 Rabi al-Awwal 1072 (1 November 1661). Fazıl Ahmed Pasha, known, unlike his father, as gentle in temperament, pious and a patron of scholars and artists, had libraries and charitable institutions founded in Istanbul and the conquered lands during his grand vizierate of more than fifteen years.", "25ea9a1e"]}
});
